def list_boards(organization_id=None, team_id=None, project_id=None, status=None, created_by_user_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- request logging / quota ----
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, credential_id, status_code, error_code=None, meta=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha1(f"{endpoint}|{_now_iso()}|{len(logs)}".encode("utf-8")).hexdigest()[:18].upper(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "ts": _now_iso(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(endpoint, credential_id):
        # Simple default: 300 requests/min per credential (or anonymous bucket)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        bucket = credential_id or "ambient"
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("credential_id") != bucket:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                rt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rt < window_start:
                continue
            cnt += 1
            if cnt >= 300:
                return False
        return True

    endpoint = "list-boards"
    credential_id = None

    if not _enforce_rate_limit(endpoint, credential_id):
        _log(endpoint, credential_id or "ambient", 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    # ---- validation ----
    prn_pat = re.compile(r"^mir_prn_[0-9A-Z]{18}$")
    def _check_prn(x, field):
        if x is None:
            return None
        if not isinstance(x, str) or not prn_pat.match(x):
            return _err("VALIDATION_ERROR", f"Invalid {field}", field=field)
        return None

    for val, field in [(organization_id, "organization_id"), (team_id, "team_id"), (project_id, "project_id"), (created_by_user_id, "created_by_user_id")]:
        e = _check_prn(val, field)
        if e:
            _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": field})
            return e

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "trashed", "deleted"):
            _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "Invalid limit", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "name"):
        _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "sort_by"})
        return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")

    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "sort_order"})
        return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

    # ---- load data ----
    principals = _load("principals.json")
    boards = _load("boards.json")
    memberships = _load("board_memberships.json")

    if not isinstance(principals, list) or not isinstance(boards, list) or not isinstance(memberships, list):
        _log(endpoint, credential_id or "ambient", 500, "CONFLICT")
        return _err("CONFLICT", "Datastore is in an invalid state")

    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and isinstance(p.get("id"), str)}
    board_by_id = {b.get("id"): b for b in boards if isinstance(b, dict) and isinstance(b.get("id"), str)}

    # ---- resolve ambient "caller accessible memberships"
    # No explicit auth parameter exists; choose a caller context that can serve the request.
    # Heuristic: prefer a user principal with active memberships; otherwise allow "public" view of boards (none).
    user_ids_with_memberships = []
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("status") not in ("active", "invited"):
            continue
        mp = m.get("member_principal_id")
        if isinstance(mp, str):
            pr = principal_by_id.get(mp)
            if pr and pr.get("principal_type") == "user" and pr.get("status") == "active":
                user_ids_with_memberships.append(mp)
    caller_user_id = user_ids_with_memberships[0] if user_ids_with_memberships else None

    if caller_user_id is None:
        # No authenticated context can list any boards.
        _log(endpoint, credential_id or "ambient", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated principal context available")

    # Accessible boards: via memberships for caller.
    accessible_board_ids = set()
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("member_principal_id") != caller_user_id:
            continue
        if m.get("status") not in ("active", "invited"):
            continue
        bid = m.get("board_id")
        if isinstance(bid, str) and bid in board_by_id:
            accessible_board_ids.add(bid)

    # Base filter: only active boards unless status filter explicitly set.
    # Business rule: trashed excluded unless internal admin flag used (not in surface); deleted excluded.
    def _board_visible(b):
        if not isinstance(b, dict):
            return False
        if b.get("id") not in accessible_board_ids:
            return False
        st = b.get("status")
        if status is None:
            return st == "active"
        # If caller asks for trashed/deleted: allow trashed, but deleted should still be excluded by server rule unless explicitly requested.
        if status == "deleted":
            return st == "deleted"
        return st == status

    results = [b for b in boards if _board_visible(b)]

    # Additional filters
    def _match_principal_type(pid, expected):
        pr = principal_by_id.get(pid)
        return bool(pr and pr.get("principal_type") == expected and pr.get("status") != "deleted")

    if organization_id is not None:
        if not _match_principal_type(organization_id, "organization"):
            _log(endpoint, credential_id or "ambient", 404, "NOT_FOUND", {"field": "organization_id"})
            return _err("NOT_FOUND", "Organization not found", field="organization_id")
        results = [b for b in results if b.get("organization_id") == organization_id]

    if team_id is not None:
        if not _match_principal_type(team_id, "team"):
            _log(endpoint, credential_id or "ambient", 404, "NOT_FOUND", {"field": "team_id"})
            return _err("NOT_FOUND", "Team not found", field="team_id")
        results = [b for b in results if b.get("team_id") == team_id]

    if project_id is not None:
        if not _match_principal_type(project_id, "project"):
            _log(endpoint, credential_id or "ambient", 404, "NOT_FOUND", {"field": "project_id"})
            return _err("NOT_FOUND", "Project not found", field="project_id")
        results = [b for b in results if b.get("project_id") == project_id]

    if created_by_user_id is not None:
        if not _match_principal_type(created_by_user_id, "user"):
            _log(endpoint, credential_id or "ambient", 404, "NOT_FOUND", {"field": "created_by_user_id"})
            return _err("NOT_FOUND", "User not found", field="created_by_user_id")
        results = [b for b in results if b.get("created_by_user_id") == created_by_user_id]

    # Enforce server-side rule about deleted boards excluded unless explicitly requested.
    if status is None:
        results = [b for b in results if b.get("status") != "deleted"]
    else:
        if status != "deleted":
            results = [b for b in results if b.get("status") != "deleted" or status == "deleted"]

    # Sorting
    def _dt_key(v):
        if not isinstance(v, str):
            return ""
        return v

    if sort_by in ("created_at", "updated_at"):
        results.sort(key=lambda b: _dt_key(b.get(sort_by)), reverse=(sort_order == "desc"))
    elif sort_by == "name":
        results.sort(key=lambda b: ("" if b.get("name") is None else str(b.get("name")).lower(), _dt_key(b.get("updated_at"))), reverse=(sort_order == "desc"))

    total = len(results)

    # Cursor handling (opaque): "idx:<int>"
    start = 0
    if cursor:
        if not cursor.startswith("idx:"):
            _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        try:
            start = int(cursor.split(":", 1)[1])
        except Exception:
            _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        if start < 0 or start > total:
            _log(endpoint, credential_id or "ambient", 400, "VALIDATION_ERROR", {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor range", field="cursor")

    page = results[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = f"idx:{start + limit}"

    resp = {
        "boards": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log(endpoint, credential_id or "ambient", 200, None, {"returned": len(page), "total": total})
    return resp

def create_board(organization_id=None, team_id=None, project_id=None, name=None, description=None, sharing_policy=None, classification=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- request logging + rate/quota enforcement (best-effort, schema not provided) ----
    def _log_call(status_code, error_code=None, extra=None):
        extra = extra or {}
        for fname in ("request_logs.json", "usage.json", "audit.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                entry = {
                    "id": "mir_req_" + hashlib.sha256(f"{now_iso}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper(),
                    "endpoint": "create-board",
                    "timestamp": now_iso,
                    "status": status_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                }
                if error_code:
                    entry["error_code"] = error_code
                entry.update(extra)
                rows.append(entry)
                _save(fname, rows)
                break

    def _enforce_limits():
        limits = None
        if os.path.exists(os.path.join(_DB, "usage_limits.json")):
            try:
                with open(os.path.join(_DB, "usage_limits.json"), encoding="utf-8") as f:
                    limits = json.load(f)
            except Exception:
                limits = None
        if not limits:
            return None

        log_file = None
        for fname in ("request_logs.json", "api_requests.json", "usage.json", "audit.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                log_file = fname
                break
        if not log_file:
            return None

        logs = _load(log_file)

        def _parse(ts):
            if not isinstance(ts, str):
                return None
            s = ts[:-1] if ts.endswith("Z") else ts
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        per_min = limits.get("rate_limit_per_minute")
        per_day = limits.get("quota_per_day")
        dt_now = now
        if isinstance(per_min, int) and per_min > 0:
            window_start = dt_now - datetime.timedelta(minutes=1)
            cnt = 0
            for r in logs[::-1]:
                dt = _parse(r.get("timestamp") or r.get("created_at") or r.get("time"))
                if not dt:
                    continue
                if dt < window_start:
                    break
                cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")

        if isinstance(per_day, int) and per_day > 0:
            day_start = dt_now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in logs:
                dt = _parse(r.get("timestamp") or r.get("created_at") or r.get("time"))
                if not dt:
                    continue
                if dt >= day_start:
                    cnt += 1
            if cnt >= per_day:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log_call(429, lim_err["error"]["code"])
        return lim_err

    # ---- validation ----
    prn_re = re.compile(r"^mir_prn_[0-9A-Z]{18}$")
    def _v_prn(val, field):
        if val is None:
            return None
        if not isinstance(val, str) or not prn_re.match(val):
            return _err("VALIDATION_ERROR", f"Invalid {field}", field=field)
        return None

    for v, f in ((organization_id, "organization_id"), (team_id, "team_id"), (project_id, "project_id")):
        e = _v_prn(v, f)
        if e:
            _log_call(400, "VALIDATION_ERROR")
            return e

    if not isinstance(name, str) or len(name.strip()) < 1:
        _log_call(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing or invalid name", field="name")
    name = name.strip()

    if description is not None and not isinstance(description, str):
        _log_call(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid description", field="description")
    if sharing_policy is not None and not isinstance(sharing_policy, dict):
        _log_call(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sharing_policy", field="sharing_policy")
    if classification is not None and not isinstance(classification, dict):
        _log_call(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid classification", field="classification")

    # ---- load data ----
    principals = _load("principals.json")
    boards = _load("boards.json")
    memberships = _load("board_memberships.json")

    principals_by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and isinstance(p.get("id"), str)}

    # validate container principals exist and types match constraints
    org_row = None
    if organization_id:
        org_row = principals_by_id.get(organization_id)
        if not org_row:
            _log_call(404, "NOT_FOUND")
            return _err("NOT_FOUND", "organization_id not found", field="organization_id")
        if org_row.get("principal_type") != "organization":
            _log_call(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "organization_id must refer to an organization principal", field="organization_id")

    if team_id:
        team_row = principals_by_id.get(team_id)
        if not team_row:
            _log_call(404, "NOT_FOUND")
            return _err("NOT_FOUND", "team_id not found", field="team_id")
        if team_row.get("principal_type") != "team":
            _log_call(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "team_id must refer to a team principal", field="team_id")
        # If org provided, enforce hierarchy team->org when known
        if organization_id and team_row.get("parent_principal_id") and team_row.get("parent_principal_id") != organization_id:
            _log_call(409, "CONFLICT")
            return _err("CONFLICT", "team_id is not under organization_id", field="team_id")

    if project_id:
        proj_row = principals_by_id.get(project_id)
        if not proj_row:
            _log_call(404, "NOT_FOUND")
            return _err("NOT_FOUND", "project_id not found", field="project_id")
        if proj_row.get("principal_type") != "project":
            _log_call(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id must refer to a project principal", field="project_id")
        if team_id and proj_row.get("parent_principal_id") and proj_row.get("parent_principal_id") != team_id:
            _log_call(409, "CONFLICT")
            return _err("CONFLICT", "project_id is not under team_id", field="project_id")

    # ---- ambient auth resolution ----
    # Choose a user principal context that is active; prefer one in the specified org/team/project if possible.
    def _principal_chain(pid):
        chain = []
        seen = set()
        while pid and pid not in seen:
            seen.add(pid)
            p = principals_by_id.get(pid)
            if not p:
                break
            chain.append(p)
            pid = p.get("parent_principal_id")
        return chain

    # candidate users: active user principals
    user_principals = [p for p in principals if isinstance(p, dict) and p.get("principal_type") == "user" and p.get("status") == "active" and isinstance(p.get("id"), str)]
    caller_user_id = None

    # If org/team/project specified, pick a user whose ancestor chain contains that principal.
    target_ids = [x for x in (project_id, team_id, organization_id) if x]
    if target_ids:
        for u in user_principals:
            chain_ids = {c.get("id") for c in _principal_chain(u.get("parent_principal_id")) if isinstance(c, dict)}
            if all(t in chain_ids or t == u.get("id") for t in target_ids):
                caller_user_id = u["id"]
                break

    # Otherwise, pick any active user
    if caller_user_id is None and user_principals:
        caller_user_id = user_principals[0]["id"]

    if caller_user_id is None:
        _log_call(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated user context available")

    # If organization_id provided, enforce requesting principal is in that organization (enterprise rule generalized)
    if organization_id:
        # user must have organization in ancestry
        chain_ids = {c.get("id") for c in _principal_chain(principals_by_id.get(caller_user_id, {}).get("parent_principal_id")) if isinstance(c, dict)}
        if organization_id not in chain_ids:
            _log_call(401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Requesting principal is not in the specified organization")

    # ---- generate ids ----
    def _new_id(prefix):
        return prefix + hashlib.sha256(f"{prefix}:{time.time_ns()}:{os.getpid()}".encode("utf-8")).hexdigest()[:18].upper()

    new_board_id = _new_id("mir_brd_")
    # external_miro_board_id must be unique when set; create new synthetic one
    existing_ext = {b.get("external_miro_board_id") for b in boards if isinstance(b, dict)}
    ext_id = "miro_" + hashlib.sha256(f"board:{new_board_id}".encode("utf-8")).hexdigest()[:18]
    while ext_id in existing_ext:
        ext_id = "miro_" + hashlib.sha256(f"board:{new_board_id}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18]

    # If not specified, attempt to infer org/team/project from caller chain (best-effort)
    if organization_id is None:
        # find first org in ancestry
        chain = _principal_chain(principals_by_id.get(caller_user_id, {}).get("parent_principal_id"))
        for p in chain:
            if p.get("principal_type") == "organization":
                organization_id = p.get("id")
                break

    # ---- create board row ----
    board_row = {
        "id": new_board_id,
        "external_miro_board_id": ext_id,
        "organization_id": organization_id,
        "team_id": team_id,
        "project_id": project_id,
        "name": name,
        "description": description,
        "sharing_policy": sharing_policy,
        "status": "active",
        "trashed_at": None,
        "purge_after": None,
        "classification": classification,
        "created_by_user_id": caller_user_id,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # enforce constraints: unique external_miro_board_id
    for b in boards:
        if isinstance(b, dict) and b.get("external_miro_board_id") == board_row["external_miro_board_id"] and board_row["external_miro_board_id"] is not None:
            _log_call(409, "CONFLICT")
            return _err("CONFLICT", "external_miro_board_id must be unique")

    # enforce container principal types when set (already validated existence/types; also ensure board org/team/project fields refer correctly)
    if organization_id:
        org = principals_by_id.get(organization_id)
        if not org or org.get("principal_type") != "organization":
            _log_call(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "organization_id must refer to an organization principal", field="organization_id")
    if team_id:
        team = principals_by_id.get(team_id)
        if not team or team.get("principal_type") != "team":
            _log_call(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "team_id must refer to a team principal", field="team_id")
    if project_id:
        proj = principals_by_id.get(project_id)
        if not proj or proj.get("principal_type") != "project":
            _log_call(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id must refer to a project principal", field="project_id")

    # ---- persist board and owner membership ----
    boards.append(board_row)

    # create owner membership for creator if not already active/invited (shouldn't exist for new board)
    mem_id = _new_id("mir_bm_")
    membership_row = {
        "id": mem_id,
        "board_id": new_board_id,
        "member_principal_id": caller_user_id,
        "role": "owner",
        "status": "active",
        "invited_by_user_id": None,
        "team_assignment_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    memberships.append(membership_row)

    try:
        _save("boards.json", boards)
        _save("board_memberships.json", memberships)
    except Exception:
        _log_call(500, "CONFLICT")
        return _err("CONFLICT", "Failed to persist board")

    _log_call(201, None, {"caller_principal_id": caller_user_id, "board_id": new_board_id})
    return {"board": board_row}

def update_board(board_id=None, name=None, description=None, sharing_policy=None, classification=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update-board"
    requests_file = "request_logs.json"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, error_code=None):
        logs = _load(requests_file)
        row = {
            "id": "req_" + hashlib.sha1((endpoint + _now_iso() + str(time.time())).encode("utf-8")).hexdigest()[:18].upper(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save(requests_file, logs)

    def _rate_limit_check():
        logs = _load(requests_file)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        c = 0
        for r in logs[-2000:]:
            if r.get("endpoint") != endpoint:
                continue
            ca = r.get("created_at")
            if isinstance(ca, str):
                s = ca[:-1] if ca.endswith("Z") else ca
                try:
                    dt = datetime.datetime.fromisoformat(s)
                except Exception:
                    dt = None
                if dt and dt >= window_start:
                    c += 1
        if c >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=60)
        return None

    rl = _rate_limit_check()
    if rl:
        _log(429, error_code=rl["error"]["code"])
        return rl

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18}$", board_id):
        e = _err("VALIDATION_ERROR", "Invalid board_id.", field="board_id")
        _log(400, error_code=e["error"]["code"])
        return e

    if name is not None:
        if not isinstance(name, str) or len(name.strip()) < 1:
            e = _err("VALIDATION_ERROR", "Invalid name.", field="name")
            _log(400, error_code=e["error"]["code"])
            return e
        name = name.strip()

    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "Invalid description.", field="description")
        _log(400, error_code=e["error"]["code"])
        return e

    if sharing_policy is not None and not isinstance(sharing_policy, dict):
        e = _err("VALIDATION_ERROR", "Invalid sharing_policy; must be an object.", field="sharing_policy")
        _log(400, error_code=e["error"]["code"])
        return e

    if classification is not None and not isinstance(classification, dict):
        e = _err("VALIDATION_ERROR", "Invalid classification; must be an object.", field="classification")
        _log(400, error_code=e["error"]["code"])
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "trashed", "deleted"):
            e = _err("VALIDATION_ERROR", "Invalid status.", field="status")
            _log(400, error_code=e["error"]["code"])
            return e

    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")

    principals_by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and isinstance(p.get("id"), str)}

    board = None
    idx = None
    if isinstance(boards, list):
        for i, b in enumerate(boards):
            if isinstance(b, dict) and b.get("id") == board_id:
                board = b
                idx = i
                break
    if board is None:
        e = _err("NOT_FOUND", "Board not found.", board_id=board_id)
        _log(404, error_code=e["error"]["code"])
        return e

    # Resolve ambient caller: require they have an active membership on this board with role owner/editor
    caller_user_id = None
    caller_role = None
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") != "active":
            continue
        uid = m.get("member_principal_id")
        p = principals_by_id.get(uid)
        if p and p.get("principal_type") == "user" and p.get("status") == "active":
            # Choose an owner/editor if possible
            if m.get("role") in ("owner", "editor"):
                caller_user_id = uid
                caller_role = m.get("role")
                break
            if caller_user_id is None:
                caller_user_id = uid
                caller_role = m.get("role")
    if caller_user_id is None or caller_role not in ("owner", "editor"):
        e = _err("UNAUTHORIZED", "You do not have permission to modify this board.")
        _log(401, error_code=e["error"]["code"])
        return e

    mutated = False
    now = _now_iso()

    if name is not None and name != board.get("name"):
        board["name"] = name
        mutated = True
    if description is not None and description != board.get("description"):
        board["description"] = description
        mutated = True
    if sharing_policy is not None and sharing_policy != board.get("sharing_policy"):
        board["sharing_policy"] = sharing_policy
        mutated = True
    if classification is not None and classification != board.get("classification"):
        board["classification"] = classification
        mutated = True

    if status is not None and status != board.get("status"):
        current = board.get("status")
        transitions = {"active": ["trashed", "deleted"], "trashed": ["active", "deleted"], "deleted": []}
        if current not in transitions or status not in transitions[current]:
            e = _err("INVALID_TRANSITION", f"Cannot transition board status from {current} to {status}.", from_status=current, to_status=status)
            _log(409, error_code=e["error"]["code"])
            return e

        # Governance rule: hard delete to 'deleted' only allowed after purge_after or privileged operations.
        if status == "deleted":
            purge_after = board.get("purge_after")
            trashed_at = board.get("trashed_at")
            # Allow delete if already trashed and purge_after passed, or if board currently active and purge_after is None => not allowed.
            if current != "trashed":
                e = _err("CONFLICT", "Hard deletion is restricted; board must be trashed and eligible for purge.", board_id=board_id)
                _log(409, error_code=e["error"]["code"])
                return e
            if purge_after is None:
                e = _err("CONFLICT", "Hard deletion is restricted; purge_after is not set.", board_id=board_id)
                _log(409, error_code=e["error"]["code"])
                return e
            try:
                pa = purge_after[:-1] if isinstance(purge_after, str) and purge_after.endswith("Z") else purge_after
                pa_dt = datetime.datetime.fromisoformat(pa) if isinstance(pa, str) else None
            except Exception:
                pa_dt = None
            if pa_dt is None or pa_dt > datetime.datetime.utcnow():
                e = _err("CONFLICT", "Hard deletion is not yet allowed; purge_after has not been reached.", board_id=board_id, purge_after=purge_after)
                _log(409, error_code=e["error"]["code"])
                return e

        if status == "trashed":
            board["trashed_at"] = now
            # Default retention: 90 days after trash
            board["purge_after"] = (datetime.datetime.utcnow() + datetime.timedelta(days=90)).replace(microsecond=0).isoformat() + "Z"
        elif status == "active":
            board["trashed_at"] = None
            board["purge_after"] = None
        elif status == "deleted":
            # keep trashed_at/purge_after as historical
            pass

        board["status"] = status
        mutated = True

    if not mutated:
        # No success without effect
        e = _err("CONFLICT", "No changes were applied.", board_id=board_id)
        _log(409, error_code=e["error"]["code"])
        return e

    board["updated_at"] = now
    boards[idx] = board
    _save("boards.json", boards)

    _log(200)
    return {"board": board}

def delete_board(board_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-board"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- observable dynamics: request log + rate limit (if request_logs.json exists or can be created) ----
    def _ensure_logfile():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(status, error_code=None, meta=None):
        if not _ensure_logfile():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mir_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _rate_limited():
        if not _ensure_logfile():
            return False
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
            if cnt >= 120:
                return True
        return False

    # Validate inputs (relax over-strict previous check: accept >=18 chars as per tool schema elsewhere)
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid board_id.", field="board_id")

    if _rate_limited():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=60)

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []

    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    # If already deleted: server would treat as not found for normal surfaces
    if board.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    now = _now_iso()

    # Business rule: delete-board moves to trash; hard delete only privileged/after purge_after (not exposed here)
    if board.get("status") == "trashed":
        # idempotent: return current state (still an effect happened in past)
        _log("ok")
        return {"board": board, "action": "trashed", "idempotent": True}

    if board.get("status") != "active":
        # lifecycle guard
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Board cannot be trashed from current status.", board_id=board_id, status=board.get("status"))

    board["status"] = "trashed"
    board["trashed_at"] = now
    # Default retention: 90 days after trash unless already set
    try:
        if not board.get("purge_after"):
            dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
            purge = (dt + datetime.timedelta(days=90)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            board["purge_after"] = purge
    except Exception:
        # If datetime parsing fails, leave purge_after unset rather than erroring
        pass
    board["updated_at"] = now

    _save("boards.json", boards)
    _log("ok")
    return {"board": board}

def copy_board(board_id, name=None, description=None, team_id=None, project_id=None, sharing_policy=None, classification=None, **_extra):
    import json, os, datetime, re, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "copy-board"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logfile():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(status, error_code=None, meta=None):
        if not _ensure_logfile():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _rate_limited():
        if not _ensure_logfile():
            return False
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
            if cnt >= 120:
                return True
        return False

    # Validate input
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    if name is not None and not isinstance(name, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a string.", field="name")
    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")
    if team_id is not None:
        if not isinstance(team_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", team_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "team_id is malformed.", field="team_id")
    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", project_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
    if sharing_policy is not None and not isinstance(sharing_policy, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sharing_policy must be an object.", field="sharing_policy")
    if classification is not None and not isinstance(classification, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "classification must be an object.", field="classification")

    if _rate_limited():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=60)

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []

    src = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not src or src.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Source board not found.", board_id=board_id)

    # Validate destination containers (if provided)
    prn_by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and isinstance(p.get("id"), str)}
    if team_id is not None:
        t = prn_by_id.get(team_id)
        if not t:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Destination team not found.", team_id=team_id)
        if t.get("principal_type") != "team":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "team_id must refer to a team principal.", field="team_id")
    if project_id is not None:
        p = prn_by_id.get(project_id)
        if not p:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Destination project not found.", project_id=project_id)
        if p.get("principal_type") != "project":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "project_id must refer to a project principal.", field="project_id")

    # If both given, ensure project is under team (parent_principal_id == team_id)
    if team_id is not None and project_id is not None:
        p = prn_by_id.get(project_id)
        if p and p.get("parent_principal_id") != team_id:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "project_id is not under the provided team_id.", team_id=team_id, project_id=project_id)

    now = _now_iso()

    # Generate new board id
    def _new_board_id():
        return "mir_brd_" + uuid.uuid4().hex[:18].upper()

    existing_board_ids = {b.get("id") for b in boards if isinstance(b, dict)}
    new_board_id = _new_board_id()
    while new_board_id in existing_board_ids:
        new_board_id = _new_board_id()

    # external_miro_board_id must be unique when present; if src has one, copy must use new value
    existing_ext = {b.get("external_miro_board_id") for b in boards if isinstance(b, dict) and b.get("external_miro_board_id")}
    new_ext = None
    if src.get("external_miro_board_id"):
        new_ext = "ext_" + uuid.uuid4().hex.upper()
        while new_ext in existing_ext:
            new_ext = "ext_" + uuid.uuid4().hex.upper()

    new_board = {
        "id": new_board_id,
        "external_miro_board_id": new_ext,
        "organization_id": src.get("organization_id"),
        "team_id": team_id if team_id is not None else src.get("team_id"),
        "project_id": project_id if project_id is not None else src.get("project_id"),
        "name": name if name is not None else src.get("name"),
        "description": description if description is not None else src.get("description"),
        "sharing_policy": sharing_policy if sharing_policy is not None else copy.deepcopy(src.get("sharing_policy")),
        "status": "active",
        "trashed_at": None,
        "purge_after": None,
        "classification": classification if classification is not None else copy.deepcopy(src.get("classification")),
        "created_by_user_id": src.get("created_by_user_id"),
        "created_at": now,
        "updated_at": now
    }

    if not new_board.get("name"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required for the copied board.")

    # Duplicate objects and links
    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []
    links = _load("object_links.json")
    if not isinstance(links, list):
        links = []

    src_objs = [o for o in objs if isinstance(o, dict) and o.get("board_id") == board_id and o.get("status") != "deleted"]
    src_links = [l for l in links if isinstance(l, dict) and l.get("board_id") == board_id]

    def _new_obj_id():
        return "mir_obj_" + uuid.uuid4().hex[:18].upper()

    existing_obj_ids = {o.get("id") for o in objs if isinstance(o, dict)}
    id_map = {}

    # First pass: allocate ids
    for o in src_objs:
        nid = _new_obj_id()
        while nid in existing_obj_ids or nid in id_map.values():
            nid = _new_obj_id()
        id_map[o["id"]] = nid

    # Second pass: copy objects with remapped references
    copied_objs = []
    for o in src_objs:
        no = copy.deepcopy(o)
        no["id"] = id_map[o["id"]]
        no["board_id"] = new_board_id
        no["external_miro_object_id"] = None  # enforce uniqueness: new provider id not known
        no["created_at"] = now
        no["updated_at"] = now

        # Remap intra-board references
        if no.get("parent_object_id") in id_map:
            no["parent_object_id"] = id_map[no["parent_object_id"]]
        if no.get("group_id") in id_map:
            no["group_id"] = id_map[no["group_id"]]
        if no.get("object_type") == "connector":
            if no.get("connector_from_object_id") in id_map:
                no["connector_from_object_id"] = id_map[no["connector_from_object_id"]]
            if no.get("connector_to_object_id") in id_map:
                no["connector_to_object_id"] = id_map[no["connector_to_object_id"]]
        else:
            # keep connectors fields null for non-connectors (schema constraint)
            no["connector_from_object_id"] = None
            no["connector_to_object_id"] = None

        copied_objs.append(no)

    # Copy links; drop links that point to deleted/un-copied objects
    copied_links = []
    def _new_link_id():
        return "mir_lnk_" + uuid.uuid4().hex[:18].upper()

    existing_link_ids = {l.get("id") for l in links if isinstance(l, dict)}
    existing_link_keys = {(l.get("board_id"), l.get("link_type"), l.get("from_object_id"), l.get("to_object_id"))
                          for l in links if isinstance(l, dict)}

    for l in src_links:
        frm = l.get("from_object_id")
        to = l.get("to_object_id")
        if frm not in id_map or to not in id_map:
            continue
        nl = copy.deepcopy(l)
        nl["board_id"] = new_board_id
        nl["from_object_id"] = id_map[frm]
        nl["to_object_id"] = id_map[to]
        # new id
        nid = _new_link_id()
        while nid in existing_link_ids:
            nid = _new_link_id()
        nl["id"] = nid
        nl["created_at"] = now
        nl["updated_at"] = now

        key = (nl["board_id"], nl.get("link_type"), nl.get("from_object_id"), nl.get("to_object_id"))
        if key in existing_link_keys:
            # should not happen across different board_id, but keep uniqueness safe
            continue
        existing_link_keys.add(key)
        copied_links.append(nl)

    # Persist
    boards.append(new_board)
    objs.extend(copied_objs)
    links.extend(copied_links)

    _save("boards.json", boards)
    _save("board_objects.json", objs)
    _save("object_links.json", links)

    _log("ok", meta={"copied_objects": len(copied_objs), "copied_links": len(copied_links)})
