        latency_ms = None
        if start_monotonic is not None:
            try:
                latency_ms = int(round((time.monotonic() - start_monotonic) * 1000))
            except Exception:
                latency_ms = None
        row = {
            "id": "mir_req_" + hashlib.sha1((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:18].upper(),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status_code,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _rate_limit_check(endpoint):
        # If request logs exist, enforce a simple per-endpoint rolling limit.
        # Since vendor quotas/rates are not specified in schema, we apply a conservative default:
        # 120 requests/minute across all callers per endpoint, if logs exist.
        fn = _find_logs_collection()
        if not fn:
            return None
        logs = _load(fn)
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_sec = 60
        limit = 120
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_sec:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded", limit=limit, window_seconds=window_sec)
            else:
                # logs are not guaranteed sorted; cannot break early reliably
                continue
        return None

    start = time.monotonic()
    endpoint = "get-specific-board"

    rl = _rate_limit_check(endpoint)
    if rl:
        _log_request(endpoint, 429, start_monotonic=start)
        return rl

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18}$", board_id):
        _log_request(endpoint, 400, start_monotonic=start)
        return _err("VALIDATION_ERROR", "Invalid board_id", field="board_id")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []

    board = None
    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break

    if not board:
        _log_request(endpoint, 404, start_monotonic=start)
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Server-side rule: deleted boards are not returned unless explicitly requested (not in this tool surface).
    if board.get("status") == "deleted":
        _log_request(endpoint, 404, start_monotonic=start)
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Ambient auth: resolve some principal that has access via board_memberships.
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []

    accessible = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("invited", "active"):
            continue
        # membership must reference an existing principal
        member_id = m.get("member_principal_id")
        if isinstance(member_id, str) and member_id:
            accessible = True
            break

    # If no membership is present, treat as forbidden (caller not in ACL).
    if not accessible:
        _log_request(endpoint, 403, start_monotonic=start)
        return _err("UNAUTHORIZED", "You do not have access to the board", board_id=board_id)

    resp = {
        "board": board,
        "metadata": {
            "retrieved_at": _now_iso()
        }
    }
    _log_request(endpoint, 200, start_monotonic=start)
    return resp

