    ]:
        if val is not None:
            if not isinstance(val, str) or not re.match(pat, val):
                _log_request(endpoint, 400, start_monotonic=start)
                return _err("VALIDATION_ERROR", f"Invalid {fid}", field=fid)

    if limit is None:
        limit = 100
