        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        _log_request(endpoint, 400, start_monotonic=start)
        return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

    offset = _decode_cursor(cursor)
    if offset is None:
        _log_request(endpoint, 400, start_monotonic=start)
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = None
    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break
    if not board or board.get("status") == "deleted":
        _log_request(endpoint, 404, start_monotonic=start)
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Access check via memberships (ambient auth).
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []
    accessible = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") in ("invited", "active"):
            accessible = True
            break
    if not accessible:
        _log_request(endpoint, 403, start_monotonic=start)
        return _err("UNAUTHORIZED", "You do not have access to the board", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []

    links = _load("object_links.json")
    if not isinstance(links, list):
        links = []

    # Filter objects by board_id and provided filters.
    filtered = []
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("board_id") != board_id:
            continue

        # Default read behavior: exclude deleted unless explicitly requested.
        if status is None:
            if o.get("status") != "active":
                continue
        else:
            if o.get("status") != status:
                continue

        if object_type is not None and o.get("object_type") != object_type:
            continue
        if parent_object_id is not None and o.get("parent_object_id") != parent_object_id:
            continue
        if group_id is not None and o.get("group_id") != group_id:
            continue
        if created_by_user_id is not None and o.get("created_by_user_id") != created_by_user_id:
            continue

        filtered.append(o)

    # Ignore links referencing deleted objects in reads: not directly returned here, but enforce integrity for group_id/parent filters.
    # (No-op beyond ensuring we don't crash; object_links are not included in this endpoint response.)

    def _sort_key(o):
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_dt(o.get(sort_by))
            # Put unparsable at end for asc, beginning for desc
            if not dt:
                return datetime.datetime.min if sort_order == "desc" else datetime.datetime.max
            return dt
        if sort_by == "object_type":
            v = o.get("object_type")
            return v if isinstance(v, str) else ""
        return ""

    reverse = (sort_order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "metadata": {
            "board_id": board_id,
            "retrieved_at": _now_iso(),
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }
    _log_request(endpoint, 200, meta={"returned": len(page)}, start_monotonic=start)
    return resp

def get_specific_item(board_id, object_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / rate limiting helpers (best-effort; if no collections exist, still proceed) ----
    def _find_log_collection():
        candidates = [
            ("request_logs.json", "request_logs"),
            ("requests.json", "requests"),
            ("api_requests.json", "api_requests"),
            ("audit.json", "audit"),
            ("usage.json", "usage"),
        ]
        for fn, nm in candidates:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                return fn
        return None

    def _append_log(status, credential_id=None, error_code=None):
        fn = _find_log_collection()
        if not fn:
            return
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get-specific-item",
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save(fn, logs)

    def _rate_limited():
        fn = _find_log_collection()
        if not fn:
            return False
        logs = _load(fn)
        if not isinstance(logs, list):
            return False
        # Simple global rate limit: 120 requests/minute across service
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= 120

    # ---- validate ----
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18}$", board_id or ""):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is malformed", field="board_id")
    if not isinstance(object_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18}$", object_id or ""):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "object_id is malformed", field="object_id")

    if _rate_limited():
        _append_log("error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    principals = _load("principals.json")
    boards = _load("boards.json")
    memberships = _load("board_memberships.json")
    objects = _load("board_objects.json")

    # ---- locate board ----
    board = None
    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break
    if not board:
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Server-side rule: deleted boards generally not readable via normal tools
    if board.get("status") == "deleted":
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # ---- ambient auth resolution / access check ----
    # Caller is authenticated; we must find some principal that can access the board.
    # Access rule: any active/invited membership for this board makes the call authorized.
    accessible_member_ids = set()
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("active", "invited"):
            continue
        pid = m.get("member_principal_id")
        if isinstance(pid, str):
            accessible_member_ids.add(pid)

    # Only treat as unauthorized if there is no possible accessor in datastore
    if not accessible_member_ids:
        _append_log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to access this board")

    # ---- locate object ----
    obj = None
    for o in objects:
        if not isinstance(o, dict):
            continue
        if o.get("id") == object_id and o.get("board_id") == board_id:
            obj = o
            break
    if not obj:
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Object not found on this board", board_id=board_id, object_id=object_id)

    # Exclude deleted objects from this surface
    if obj.get("status") == "deleted":
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Object not found on this board", board_id=board_id, object_id=object_id)

    # Optionally ensure created_by_user_id refers to existing principal if set (integrity sanity)
    cby = obj.get("created_by_user_id")
    if cby is not None and isinstance(cby, str):
        if not any(isinstance(p, dict) and p.get("id") == cby for p in principals):
            # Do not fail: historical rows might exist; still return object.
            pass

    _append_log("ok")
    return {
        "object": obj,
        "board_id": board_id,
        "object_id": object_id,
    }

