            if not isinstance(m, dict):
                continue
            if m.get("board_id") != board_id_:
                continue
            if m.get("status") not in ("active", "invited"):
                continue
            pid = m.get("member_principal_id")
            p = principal_by_id.get(pid)
            if p and p.get("principal_type") == "user" and p.get("status") == "active":
                return pid
        return None

    def _container_supports(parent_obj):
        # Application logic: only frames and documents can contain items in this simplified model.
        # (Real Miro has more nuance.)
        return parent_obj.get("object_type") in ("item_frame", "item_document")

    # ---- input validation ----
    if not _valid_id(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is malformed.")
    if not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", item_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "item_id is malformed.")
    if geometry is not None and not isinstance(geometry, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "geometry must be an object when provided.")
    if parent_object_id is not None and not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", parent_object_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_object_id is malformed.")
    if group_id is not None and not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "group_id is malformed.")

    if geometry is not None:
        # enforce geometry.x and geometry.y finite numbers when provided
        if "x" in geometry and geometry["x"] is not None and not _finite_number(geometry["x"]):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry.x must be a finite number when provided.")
        if "y" in geometry and geometry["y"] is not None and not _finite_number(geometry["y"]):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry.y must be a finite number when provided.")

    # ---- load store ----
    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    objects = _load("board_objects.json")
    links = _load("object_links.json")

    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")
    if board.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")

    acting_user_id = _board_accessible(board, principals, memberships)
    if acting_user_id is None:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible principal found for this operation.")

    obj = next((o for o in objects if isinstance(o, dict) and o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Item not found on this board.")

    if not (isinstance(obj.get("object_type"), str) and obj["object_type"].startswith("item_")):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "item_id must refer to an item object (object_type like 'item_%').")

    # ---- validate parent/group references ----
    if parent_object_id is not None:
        parent = next((o for o in objects if isinstance(o, dict) and o.get("id") == parent_object_id and o.get("board_id") == board_id), None)
        if not parent or parent.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Parent object not found on this board.")
        if not _container_supports(parent):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Referenced parent_object_id does not support containing items.")
        # prevent direct self-parenting
        if parent_object_id == item_id:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_object_id cannot be the item itself.")

    if group_id is not None:
        grp = next((o for o in objects if isinstance(o, dict) and o.get("id") == group_id and o.get("board_id") == board_id), None)
        if not grp or grp.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Group not found on this board.")
        if grp.get("object_type") != "group":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "group_id must refer to an object of type 'group'.")

    # ---- apply changes (must have effect) ----
    changed = False

    if geometry is not None:
        obj["geometry"] = geometry
        changed = True

    if parent_object_id is not None:
        if obj.get("parent_object_id") != parent_object_id:
            obj["parent_object_id"] = parent_object_id
            changed = True

    if group_id is not None:
        # Set convenience pointer
        if obj.get("group_id") != group_id:
            obj["group_id"] = group_id
            changed = True

        # Maintain object_links group_membership: replace membership for this item (to_object_id=item_id) to point to this group.
        # First, remove existing group_membership links for this item on this board.
        if isinstance(links, list):
            before = len(links)
            links = [l for l in links if not (isinstance(l, dict) and l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("to_object_id") == item_id)]
            removed = before - len(links)
            if removed:
                changed = True

            # If group_id is a real id, create link (unless already exists after filtering)
            exists = any(isinstance(l, dict) and l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("from_object_id") == group_id and l.get("to_object_id") == item_id for l in links)
            if not exists:
                lid = "mir_lnk_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
                links.append({
                    "id": lid,
                    "board_id": board_id,
                    "link_type": "group_membership",
                    "from_object_id": group_id,
                    "to_object_id": item_id,
                    "position_index": None,
                    "created_at": now,
                    "updated_at": now
                })
                changed = True

    # If group_id is explicitly provided as None in API, it would mean ungroup; but schema makes it optional.
    # Here: omit keeps unchanged; provide group_id sets it. No explicit ungroup parameter exists.

    if not changed:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "No changes to apply.")

    obj["updated_at"] = now
    # Write through
    _save("board_objects.json", objects)
    _save("object_links.json", links)

    # Add enterprise content log if enterprise board
    if board.get("organization_id"):
        ent = _load("enterprise_ops.json")
        if isinstance(ent, list):
            ent_id = "mir_ent_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
            ent.append({
                "id": ent_id,
                "record_type": "board_content_log",
                "organization_id": board.get("organization_id"),
                "board_id": board_id,
                "case_id": None,
                "legal_hold_id": None,
                "object_id": item_id,
                "status": "immutable",
                "payload": {
                    "action": "update-item-position",
                    "actor_user_id": acting_user_id,
                    "changes": {
                        "geometry": geometry if geometry is not None else None,
                        "parent_object_id": parent_object_id if parent_object_id is not None else None,
                        "group_id": group_id if group_id is not None else None
                    }
                },
                "occurred_at": now,
                "expires_at": None,
                "created_at": now,
                "updated_at": now
            })
            _save("enterprise_ops.json", ent)

    _log("ok")
    return {"item": obj}

def delete_item(board_id, item_id, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-item"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dt_parse(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "mir_req_" + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(18)),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        limits = _load("service_limits.json")
        limit = None
        if isinstance(limits, list):
            for r in limits:
                if isinstance(r, dict) and r.get("service") == "miro":
                    limit = r
                    break
        if not limit:
            return None
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rpm = limit.get("requests_per_minute")
        rpd = limit.get("requests_per_day")
        if isinstance(rpm, int) and rpm >= 0:
            cut = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _dt_parse(r.get("timestamp"))
                if ts and ts >= cut:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(rpd, int) and rpd >= 0:
            cut = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _dt_parse(r.get("timestamp"))
                if ts and ts >= cut:
                    c += 1
            if c >= rpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", error_code=lim_err["error"]["code"])
        return lim_err

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        e = _err("VALIDATION_ERROR", "board_id is malformed")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", item_id or ""):
        e = _err("VALIDATION_ERROR", "item_id is malformed")
        _log("error", error_code=e["error"]["code"])
        return e

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found")
        _log("error", error_code=e["error"]["code"])
        return e

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []
    item = next((o for o in objs if isinstance(o, dict) and o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not item:
        e = _err("NOT_FOUND", "Item not found on board")
        _log("error", error_code=e["error"]["code"])
        return e

    if not (isinstance(item.get("object_type"), str) and item.get("object_type", "").startswith("item_")):
        e = _err("VALIDATION_ERROR", "item_id does not refer to an item object")
        _log("error", error_code=e["error"]["code"])
        return e

    if item.get("status") == "deleted":
        e = _err("CONFLICT", "Item is already deleted")
        _log("error", error_code=e["error"]["code"])
        return e

    # Transition active -> deleted only
    if item.get("status") != "active":
        e = _err("INVALID_TRANSITION", "Cannot delete item from current status", from_status=item.get("status"), to_status="deleted")
        _log("error", error_code=e["error"]["code"])
        return e

    now = _iso_now()
    item["status"] = "deleted"
    item["updated_at"] = now

    # Persist item
    for i, o in enumerate(objs):
        if isinstance(o, dict) and o.get("id") == item_id:
            objs[i] = item
            break
    _save("board_objects.json", objs)

    # Remove/ignore links referencing deleted objects -> enforce by deleting those rows
    links = _load("object_links.json")
    if not isinstance(links, list):
        links = []
    new_links = []
    removed_any = False
    for r in links:
        if not isinstance(r, dict):
            continue
        if r.get("board_id") != board_id:
            new_links.append(r)
            continue
        if r.get("from_object_id") == item_id or r.get("to_object_id") == item_id:
            removed_any = True
            continue
        new_links.append(r)
    if removed_any:
        _save("object_links.json", new_links)

    _log("ok")
    return {"item": item}

