            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso_now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        limits = _load("service_limits.json")
        limit = None
        if isinstance(limits, list):
            for r in limits:
                if isinstance(r, dict) and r.get("service") == "miro":
                    limit = r
                    break
        if not limit:
            return None
        now = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rpm = limit.get("requests_per_minute")
        rpd = limit.get("requests_per_day")
        if isinstance(rpm, int) and rpm >= 0:
            cut = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = _dt_parse(r.get("timestamp"))
                if ts and ts >= cut:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(rpd, int) and rpd >= 0:
            cut = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = _dt_parse(r.get("timestamp"))
                if ts and ts >= cut:
                    c += 1
            if c >= rpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log("error", error_code=lim_err["error"]["code"])
        return lim_err

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        e = _err("VALIDATION_ERROR", "board_id is malformed")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", item_id or ""):
        e = _err("VALIDATION_ERROR", "item_id is malformed")
        _log("error", error_code=e["error"]["code"])
        return e

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found")
        _log("error", error_code=e["error"]["code"])
        return e

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []
    item = next((o for o in objs if isinstance(o, dict) and o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not item:
        e = _err("NOT_FOUND", "Item not found on board")
        _log("error", error_code=e["error"]["code"])
        return e

    if item.get("object_type") != "item_app_card":
        e = _err("NOT_FOUND", "Item is not an app card on this board")
        _log("error", error_code=e["error"]["code"])
        return e

    if item.get("status") == "deleted":
        e = _err("NOT_FOUND", "Item not found")
        _log("error", error_code=e["error"]["code"])
        return e

    _log("ok")
    return {"item": item}

def update_app_card_item(board_id, item_id, title=None, text_content=None, data=None, style=None, geometry=None, parent_object_id=None, group_id=None, **_extra):
    import json, os, datetime, re, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update-app-card-item"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None):
        logs = _load("request_logs.json")
        row = {
            "id": "mir_req_" + uuid.uuid4().hex.upper(),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if code:
            row["error_code"] = code
        if message:
            row["error_message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _validate_id(val, pat, field):
        if not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string", field=field)
        if not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"{field} is malformed", field=field)
        return None

    def _validate_obj(val, field):
        if val is None:
            return None
        if not isinstance(val, dict):
            return _err("VALIDATION_ERROR", f"{field} must be an object", field=field)
        return None

    def _validate_str(val, field):
        if val is None:
            return None
        if not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string", field=field)
        return None

    # Input validation
    e = _validate_id(board_id, r"^mir_brd_[0-9A-Z]{18,}$", "board_id")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    e = _validate_id(item_id, r"^mir_obj_[0-9A-Z]{18,}$", "item_id")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    for val, field in [(parent_object_id, "parent_object_id"), (group_id, "group_id")]:
        if val is not None:
            e = _validate_id(val, r"^mir_obj_[0-9A-Z]{18,}$", field)
            if e:
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    for val, field in [(title, "title"), (text_content, "text_content")]:
        e = _validate_str(val, field)
        if e:
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    for val, field in [(data, "data"), (style, "style"), (geometry, "geometry")]:
        e = _validate_obj(val, field)
        if e:
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    if geometry is not None:
        # Enforce finite numbers when geometry provided (x,y only per constraints; tolerate missing)
        for k in ("x", "y"):
            if k in geometry and geometry[k] is not None:
                v = geometry[k]
                if not isinstance(v, (int, float)) or isinstance(v, bool) or (isinstance(v, float) and (math.isinf(v) or math.isnan(v))):
                    e = _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number", field=f"geometry.{k}")
                    _log("error", e["error"]["code"], e["error"]["message"])
                    return e

    boards = _load("boards.json")
    objs = _load("board_objects.json")
    links = _load("object_links.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found", board_id=board_id)
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    item = next((o for o in objs if o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not item or item.get("object_type") != "item_app_card":
        e = _err("NOT_FOUND", "App card item not found on board", board_id=board_id, item_id=item_id)
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if item.get("status") != "active":
        e = _err("NOT_FOUND", "App card item not found on board", board_id=board_id, item_id=item_id)
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Validate parent/group references and containment rules.
    def _find_obj(oid):
        return next((o for o in objs if o.get("id") == oid), None)

    if parent_object_id is not None:
        if parent_object_id == item_id:
            e = _err("CONFLICT", "parent_object_id cannot reference the item itself", field="parent_object_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        p = _find_obj(parent_object_id)
        if not p or p.get("board_id") != board_id or p.get("status") != "active":
            e = _err("NOT_FOUND", "parent_object_id not found on board", parent_object_id=parent_object_id)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        # "can contain items" enforced by application logic: allow frames/documents/groups only.
        if p.get("object_type") not in ("item_frame", "item_document", "group"):
            e = _err("CONFLICT", "parent_object_id refers to an object that cannot contain items", parent_object_id=parent_object_id)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    if group_id is not None:
        if group_id == item_id:
            e = _err("CONFLICT", "group_id cannot reference the item itself", field="group_id")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        g = _find_obj(group_id)
        if not g or g.get("board_id") != board_id or g.get("status") != "active":
            e = _err("NOT_FOUND", "group_id not found on board", group_id=group_id)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        if g.get("object_type") != "group":
            e = _err("CONFLICT", "group_id must refer to a group object", group_id=group_id)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    # Apply updates
    changed = False
    for field, val in [("title", title), ("text_content", text_content), ("data", data), ("style", style), ("geometry", geometry)]:
        if val is not None:
            item[field] = val
            changed = True

    if parent_object_id is not None:
        item["parent_object_id"] = parent_object_id
        changed = True

    if group_id is not None:
        # Maintain both the convenience pointer and membership link row.
        item["group_id"] = group_id
        changed = True

        # Ensure group membership link exists and unique.
        existing = next((l for l in links if l.get("board_id") == board_id and l.get("link_type") == "group_membership"
                         and l.get("from_object_id") == group_id and l.get("to_object_id") == item_id), None)
        if existing is None:
            # Remove any other group_membership links for this item (moving between groups).
            links = [l for l in links if not (l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("to_object_id") == item_id)]
            links.append({
                "id": "mir_lnk_" + uuid.uuid4().hex.upper(),
                "board_id": board_id,
                "link_type": "group_membership",
                "from_object_id": group_id,
                "to_object_id": item_id,
                "position_index": None,
                "created_at": _now(),
                "updated_at": _now(),
            })
        else:
            # touch timestamp
            existing["updated_at"] = _now()

    # If group_id explicitly provided as None is not possible via signature; no "remove group" option here.

    if not changed:
        # Still "real": return current item without pretending mutation.
        out = {"id": item.get("id"), "item": item, "board_id": board_id}
        _log("ok")
        return out

    item["updated_at"] = _now()
    _save("board_objects.json", objs)
    _save("object_links.json", links)

    out = {"id": item.get("id"), "item": item, "board_id": board_id}
    _log("ok")
    return out

def delete_app_card_item(board_id, item_id, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "delete-app-card-item"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # validate
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    if not isinstance(item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", item_id):
        _log("error", "VALIDATION_ERROR", {"field": "item_id"})
        return _err("VALIDATION_ERROR", "item_id is malformed.", field="item_id")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    # ambient auth: require any active membership with edit capability (owner/editor)
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_edit = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_edit:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to edit the board.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")
    obj = next((o for o in objs if isinstance(o, dict) and o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("status") == "deleted" or obj.get("object_type") != "item_app_card":
        _log("error", "NOT_FOUND", {"board_id": board_id, "item_id": item_id})
        return _err("NOT_FOUND", "App card item not found on this board.", board_id=board_id, item_id=item_id)

    # soft delete + remove links referencing the deleted object
    obj["status"] = "deleted"
    obj["updated_at"] = now

    links = _load("object_links.json")
    if isinstance(links, list):
        new_links = []
        changed = False
        for r in links:
            if not isinstance(r, dict):
                new_links.append(r)
                continue
            if r.get("board_id") == board_id and (r.get("from_object_id") == item_id or r.get("to_object_id") == item_id):
                changed = True
                continue
            new_links.append(r)
        if changed:
            _save("object_links.json", new_links)

    _save("board_objects.json", objs)
    _log("success")
    return {"board_id": board_id, "item_id": item_id, "status": "deleted", "deleted": True}

