def update_card_item(board_id, card_item_id, title=None, text_content=None, data=None, style=None, geometry=None, group_id=None, parent_object_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "update-card-item"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _validate_id(val, pat, field):
        if not isinstance(val, str) or not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"{field} is malformed", field=field)
        return None

    def _finite_number(x):
        try:
            v = float(x)
            if v != v or v in (float("inf"), float("-inf")):
                return False
            return True
        except Exception:
            return False

    # Input validation
    e = _validate_id(board_id, r"^mir_brd_[0-9A-Z]{19,}$", "board_id")
    if e:
        _log("error", meta={"code": e["error"]["code"]})
        return e
    e = _validate_id(card_item_id, r"^mir_obj_[0-9A-Z]{19,}$", "card_item_id")
    if e:
        _log("error", meta={"code": e["error"]["code"]})
