        _log("error", meta={"code": e["error"]["code"]})
        return e
    if style is not None and not isinstance(style, dict):
        e = _err("VALIDATION_ERROR", "style must be an object", field="style")
        _log("error", meta={"code": e["error"]["code"]})
        return e
    if geometry is not None:
        if not isinstance(geometry, dict):
            e = _err("VALIDATION_ERROR", "geometry must be an object", field="geometry")
            _log("error", meta={"code": e["error"]["code"]})
            return e
        # enforce finite x/y if provided
        for k in ("x", "y"):
            if k in geometry and geometry[k] is not None and not _finite_number(geometry[k]):
                e = _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number", field=f"geometry.{k}")
                _log("error", meta={"code": e["error"]["code"]})
                return e

    if group_id is not None:
        e = _validate_id(group_id, r"^mir_obj_[0-9A-Z]{19,}$", "group_id")
        if e:
            _log("error", meta={"code": e["error"]["code"]})
            return e
    if parent_object_id is not None:
        e = _validate_id(parent_object_id, r"^mir_obj_[0-9A-Z]{19,}$", "parent_object_id")
        if e:
            _log("error", meta={"code": e["error"]["code"]})
            return e

    # Resolve board and item
    boards = _load("boards.json")
    if not isinstance(boards, list): boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
