    objs = _load("board_objects.json")
    if not isinstance(objs, list): objs = []
    obj = next((o for o in objs if o.get("id") == card_item_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("object_type") != "item_card":
        e = _err("NOT_FOUND", "Card item not found on this board", board_id=board_id, card_item_id=card_item_id)
        _log("error", meta={"code": e["error"]["code"]})
        return e

    if obj.get("status") == "deleted":
        e = _err("NOT_FOUND", "Card item not found on this board", board_id=board_id, card_item_id=card_item_id)
        _log("error", meta={"code": e["error"]["code"]})
        return e

    # Validate parent/group references if provided
    if parent_object_id is not None:
        parent = next((o for o in objs if o.get("id") == parent_object_id and o.get("board_id") == board_id), None)
        if not parent or parent.get("status") == "deleted":
            e = _err("NOT_FOUND", "parent_object_id not found on this board", parent_object_id=parent_object_id)
            _log("error", meta={"code": e["error"]["code"]})
            return e
        # Application logic: only frames can contain items (simplified)
        if parent.get("object_type") != "item_frame":
            e = _err("VALIDATION_ERROR", "parent_object_id must refer to a container object (frame)", parent_object_id=parent_object_id)
            _log("error", meta={"code": e["error"]["code"]})
            return e

    if group_id is not None:
        grp = next((o for o in objs if o.get("id") == group_id and o.get("board_id") == board_id), None)
        if not grp or grp.get("status") == "deleted":
            e = _err("NOT_FOUND", "group_id not found on this board", group_id=group_id)
            _log("error", meta={"code": e["error"]["code"]})
            return e
        if grp.get("object_type") != "group":
            e = _err("VALIDATION_ERROR", "group_id must refer to an object of type 'group'", group_id=group_id)
            _log("error", meta={"code": e["error"]["code"]})
            return e

    # Mutate fields
    changed = False
    if title is not None:
        obj["title"] = title
        changed = True
    if text_content is not None:
        obj["text_content"] = text_content
        changed = True
    if data is not None:
        obj["data"] = data
        changed = True
    if style is not None:
        obj["style"] = style
        changed = True
    if geometry is not None:
        obj["geometry"] = geometry
        changed = True
    if parent_object_id is not None:
        obj["parent_object_id"] = parent_object_id
        changed = True
    if group_id is not None:
        obj["group_id"] = group_id
        changed = True

    if changed:
        obj["updated_at"] = _now()
        _save("board_objects.json", objs)

    _log("success")
    return {"data": obj}

def delete_card_item(board_id, card_item_id, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "delete-card-item"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Relax to actual store pattern: many IDs are 18+ chars; spec says 19+ here.
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    if not isinstance(card_item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", card_item_id):
        _log("error", "VALIDATION_ERROR", {"field": "card_item_id"})
        return _err("VALIDATION_ERROR", "card_item_id is malformed.", field="card_item_id")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_edit = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_edit:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to edit the board.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")
    obj = next((o for o in objs if isinstance(o, dict) and o.get("id") == card_item_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("status") == "deleted" or obj.get("object_type") != "item_card":
        _log("error", "NOT_FOUND", {"board_id": board_id, "card_item_id": card_item_id})
        return _err("NOT_FOUND", "Card item not found on this board.", board_id=board_id, item_id=card_item_id)

    obj["status"] = "deleted"
    obj["updated_at"] = now

    links = _load("object_links.json")
    if isinstance(links, list):
        new_links = []
        changed = False
        for r in links:
            if not isinstance(r, dict):
                new_links.append(r)
                continue
            if r.get("board_id") == board_id and (r.get("from_object_id") == card_item_id or r.get("to_object_id") == card_item_id):
                changed = True
                continue
            new_links.append(r)
        if changed:
            _save("object_links.json", new_links)

    _save("board_objects.json", objs)
    _log("success")
    return {"board_id": board_id, "item_id": card_item_id, "status": "deleted", "deleted": True}

def create_connector(board_id, from_object_id, to_object_id, title=None, data=None, style=None, geometry=None, parent_object_id=None, group_id=None, **_extra):
    import json, os, datetime, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "create-connector"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _finite_number(x):
        try:
            v = float(x)
            return not (math.isnan(v) or math.isinf(v))
        except Exception:
            return False

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    for f, v in (("from_object_id", from_object_id), ("to_object_id", to_object_id)):
        if not isinstance(v, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", v):
            _log("error", "VALIDATION_ERROR", {"field": f})
            return _err("VALIDATION_ERROR", f"{f} is malformed.", field=f)
    for f, v in (("parent_object_id", parent_object_id), ("group_id", group_id)):
        if v is not None and (not isinstance(v, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", v)):
            _log("error", "VALIDATION_ERROR", {"field": f})
            return _err("VALIDATION_ERROR", f"{f} is malformed.", field=f)
    for f, v in (("data", data), ("style", style), ("geometry", geometry)):
        if v is not None and not isinstance(v, dict):
            _log("error", "VALIDATION_ERROR", {"field": f})
            return _err("VALIDATION_ERROR", f"{f} must be an object.", field=f)
    if title is not None and not isinstance(title, str):
        _log("error", "VALIDATION_ERROR", {"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a string.", field="title")

    if geometry is not None:
        # Only validate x/y if present
        if "x" in geometry and not _finite_number(geometry.get("x")):
            _log("error", "VALIDATION_ERROR", {"field": "geometry.x"})
            return _err("VALIDATION_ERROR", "geometry.x must be a finite number.", field="geometry.x")
        if "y" in geometry and not _finite_number(geometry.get("y")):
            _log("error", "VALIDATION_ERROR", {"field": "geometry.y"})
            return _err("VALIDATION_ERROR", "geometry.y must be a finite number.", field="geometry.y")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_edit = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_edit:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to edit the board.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")

    def _get_active_object(oid):
        o = next((x for x in objs if isinstance(x, dict) and x.get("id") == oid and x.get("board_id") == board_id), None)
        if not o or o.get("status") == "deleted":
            return None
        return o

    from_obj = _get_active_object(from_object_id)
    to_obj = _get_active_object(to_object_id)
    if not from_obj:
        _log("error", "NOT_FOUND", {"from_object_id": from_object_id})
        return _err("NOT_FOUND", "from_object_id not found on this board.", board_id=board_id, from_object_id=from_object_id)
    if not to_obj:
        _log("error", "NOT_FOUND", {"to_object_id": to_object_id})
        return _err("NOT_FOUND", "to_object_id not found on this board.", board_id=board_id, to_object_id=to_object_id)

    if parent_object_id is not None:
        parent = _get_active_object(parent_object_id)
        if not parent:
            _log("error", "NOT_FOUND", {"parent_object_id": parent_object_id})
            return _err("NOT_FOUND", "parent_object_id not found on this board.", board_id=board_id, parent_object_id=parent_object_id)
        # application logic: only frames can contain children (simplified)
        if parent.get("object_type") != "item_frame":
            _log("error", "CONFLICT", {"parent_object_id": parent_object_id})
            return _err("CONFLICT", "parent_object_id is not a valid container for a connector.", parent_object_id=parent_object_id)

    if group_id is not None:
        grp = _get_active_object(group_id)
        if not grp:
            _log("error", "NOT_FOUND", {"group_id": group_id})
            return _err("NOT_FOUND", "group_id not found on this board.", board_id=board_id, group_id=group_id)
        if grp.get("object_type") != "group":
            _log("error", "VALIDATION_ERROR", {"field": "group_id"})
            return _err("VALIDATION_ERROR", "group_id must refer to a group object.", field="group_id")

    # generate id
    existing_ids = {o.get("id") for o in objs if isinstance(o, dict)}
    new_id = None
    for _ in range(20):
        cand = "mir_obj_" + uuid.uuid4().hex[:18].upper()
        if cand not in existing_ids:
            new_id = cand
            break
    if not new_id:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unable to allocate object id.")

    row = {
        "id": new_id,
        "external_miro_object_id": None,
        "board_id": board_id,
        "object_type": "connector",
        "status": "active",
        "parent_object_id": parent_object_id,
        "group_id": group_id,
        "title": title,
        "text_content": None,
        "data": data,
        "style": style,
        "geometry": geometry,
        "connector_from_object_id": from_object_id,
        "connector_to_object_id": to_object_id,
        "image_source_url": None,
        "image_asset_ref": None,
        "created_by_user_id": None,
        "created_at": now,
        "updated_at": now,
    }
    objs.append(row)
    _save("board_objects.json", objs)
    _log("success")
    return {"connector": row}

def get_connectors(board_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get-connectors"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{19,}$", board_id):
        e = _err("VALIDATION_ERROR", "board_id is malformed", field="board_id")
        _log("error", meta={"code": e["error"]["code"]})
        return e

    if status is None:
        status = "active"
    if status not in ("active", "deleted"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, deleted", field="status")
        _log("error", meta={"code": e["error"]["code"]})
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
        _log("error", meta={"code": e["error"]["code"]})
        return e

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at", field="sort")
        _log("error", meta={"code": e["error"]["code"]})
        return e

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be one of: asc, desc", field="order")
        _log("error", meta={"code": e["error"]["code"]})
        return e

    # Validate cursor
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 2048:
            e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            _log("error", meta={"code": e["error"]["code"]})
            return e
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("board_id") != board_id:
                raise ValueError("bad cursor")
            start = int(payload.get("offset", 0))
            if start < 0:
                raise ValueError("bad offset")
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            _log("error", meta={"code": e["error"]["code"]})
            return e

    boards = _load("boards.json")
    if not isinstance(boards, list): boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        e = _err("NOT_FOUND", "Board not found", board_id=board_id)
        _log("error", meta={"code": e["error"]["code"]})
        return e

    objs = _load("board_objects.json")
    if not isinstance(objs, list): objs = []
    rows = [
        o for o in objs
        if isinstance(o, dict)
        and o.get("board_id") == board_id
        and o.get("object_type") == "connector"
        and o.get("status") == status
    ]

    def _key(o):
        v = o.get(sort)
        # ISO timestamps sort lexicographically if consistent; None last.
        return (v is None, v, o.get("id"))

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        payload = {"board_id": board_id, "offset": start + limit, "sort": sort, "order": order, "status": status}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("success")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "status": status,
        },
    }

def get_specific_connector(board_id, connector_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-specific-connector"

    def _log(status, credential_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"mir_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
        }
        if message is not None:
            row["message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(board_id, str) or re.match(r"^mir_brd_[0-9A-Z]{19,}$", board_id) is None:
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
        if not isinstance(connector_id, str) or re.match(r"^mir_obj_[0-9A-Z]{19,}$", connector_id) is None:
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "connector_id is malformed.", field="connector_id")

        boards = _load("boards.json")
        board = next((b for b in boards if b.get("id") == board_id), None)
        if not board:
            _log("error", message="not_found")
            return _err("NOT_FOUND", "Board not found.", board_id=board_id)

        # Resolve an ambient principal that can access this board (membership invited/active).
        principals = _load("principals.json")
        memberships = _load("board_memberships.json")
        accessible_member_ids = {m.get("member_principal_id") for m in memberships
                                 if m.get("board_id") == board_id and m.get("status") in ("invited", "active")}
        accessible_member_ids = {pid for pid in accessible_member_ids if isinstance(pid, str)}
        principal_rows = [p for p in principals if p.get("id") in accessible_member_ids and p.get("status") == "active"]
        if not principal_rows:
            _log("error", message="forbidden")
            return _err("UNAUTHORIZED", "You don’t have access to view the board content.", board_id=board_id)

        objects = _load("board_objects.json")
        obj = next((o for o in objects
                    if o.get("id") == connector_id and o.get("board_id") == board_id), None)
        if not obj or obj.get("object_type") != "connector" or obj.get("status") != "active":
            _log("error", message="not_found")
            return _err("NOT_FOUND", "Connector not found on the specified board.", board_id=board_id, connector_id=connector_id)

        _log("success", credential_id=principal_rows[0].get("id"))
        return {"connector": obj}
    except Exception as e:
        _log("error", message="internal_error")
        return _err("CONFLICT", "Internal error.", detail=str(e))

def update_connector(board_id, connector_id, from_object_id=None, to_object_id=None, title=None, data=None, style=None, geometry=None, group_id=None, parent_object_id=None, **_extra):
    import json, os, datetime, re, time, math, copy
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update-connector"

    def _log(status, credential_id=None, message=None, extra=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"mir_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
        }
        if message is not None:
            row["message"] = message
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _id_ok(pat, v):
        return isinstance(v, str) and re.match(pat, v) is not None

    def _finite_number(x):
        return isinstance(x, (int, float)) and not (isinstance(x, float) and (math.isinf(x) or math.isnan(x)))

    def _validate_geometry(g):
        if g is None:
            return None
        if not isinstance(g, dict):
            return "geometry must be an object."
        # Only enforce finiteness for x,y when present (schema guidance)
        for k in ("x", "y"):
            if k in g and g[k] is not None and not _finite_number(g[k]):
                return f"geometry.{k} must be a finite number."
        return None

    try:
        if not _id_ok(r"^mir_brd_[0-9A-Z]{19,}$", board_id):
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
        if not _id_ok(r"^mir_obj_[0-9A-Z]{19,}$", connector_id):
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "connector_id is malformed.", field="connector_id")

        for nm, val in (("from_object_id", from_object_id), ("to_object_id", to_object_id), ("group_id", group_id), ("parent_object_id", parent_object_id)):
            if val is not None and not _id_ok(r"^mir_obj_[0-9A-Z]{19,}$", val):
                _log("error", message="validation")
                return _err("VALIDATION_ERROR", f"{nm} is malformed.", field=nm)

        if title is not None and not isinstance(title, str):
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "title must be a string.", field="title")
        for nm, val in (("data", data), ("style", style)):
            if val is not None and not isinstance(val, dict):
                _log("error", message="validation")
                return _err("VALIDATION_ERROR", f"{nm} must be an object.", field=nm)

        gerr = _validate_geometry(geometry)
        if gerr:
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", gerr, field="geometry")

        boards = _load("boards.json")
        board = next((b for b in boards if b.get("id") == board_id), None)
        if not board:
            _log("error", message="not_found")
            return _err("NOT_FOUND", "Board not found.", board_id=board_id)

        principals = _load("principals.json")
        memberships = _load("board_memberships.json")

        # Must have permission to edit: any active membership with role owner/editor.
        editors = [m for m in memberships if m.get("board_id") == board_id and m.get("status") == "active" and m.get("role") in ("owner", "editor")]
        active_editor_principals = {m.get("member_principal_id") for m in editors if isinstance(m.get("member_principal_id"), str)}
        active_editor_principals = {pid for pid in active_editor_principals
                                    if any(p.get("id") == pid and p.get("status") == "active" for p in principals)}
        if not active_editor_principals:
            _log("error", message="forbidden")
            return _err("UNAUTHORIZED", "You don’t have permission to edit the board.", board_id=board_id)

        objects = _load("board_objects.json")
        idx = next((i for i, o in enumerate(objects) if o.get("id") == connector_id and o.get("board_id") == board_id), None)
        if idx is None:
            _log("error", message="not_found")
            return _err("NOT_FOUND", "Connector not found on the specified board.", board_id=board_id, connector_id=connector_id)

        obj = objects[idx]
        if obj.get("object_type") != "connector" or obj.get("status") != "active":
            _log("error", message="not_found")
            return _err("NOT_FOUND", "Connector not found on the specified board.", board_id=board_id, connector_id=connector_id)

        # Validate referenced objects exist on same board if updated/provided.
        by_id = {o.get("id"): o for o in objects if o.get("board_id") == board_id}
        if from_object_id is not None:
            fo = by_id.get(from_object_id)
            if not fo:
                _log("error", message="not_found")
                return _err("NOT_FOUND", "from_object_id not found on this board.", from_object_id=from_object_id)
            if fo.get("status") != "active":
                _log("error", message="not_found")
                return _err("NOT_FOUND", "from_object_id refers to a deleted object.", from_object_id=from_object_id)
        if to_object_id is not None:
            to = by_id.get(to_object_id)
            if not to:
                _log("error", message="not_found")
                return _err("NOT_FOUND", "to_object_id not found on this board.", to_object_id=to_object_id)
            if to.get("status") != "active":
                _log("error", message="not_found")
                return _err("NOT_FOUND", "to_object_id refers to a deleted object.", to_object_id=to_object_id)

        # If neither updated, ensure connector invariants still hold; otherwise enforce after applying.
        new_from = from_object_id if from_object_id is not None else obj.get("connector_from_object_id")
        new_to = to_object_id if to_object_id is not None else obj.get("connector_to_object_id")
        if not new_from or not new_to:
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "Connectors must have from_object_id and to_object_id.", field="from_object_id/to_object_id")

        if group_id is not None:
            go = by_id.get(group_id)
            if not go:
                _log("error", message="not_found")
                return _err("NOT_FOUND", "group_id not found on this board.", group_id=group_id)
            if go.get("object_type") != "group":
                _log("error", message="validation")
                return _err("VALIDATION_ERROR", "group_id must refer to a group object.", field="group_id")
            if go.get("status") != "active":
                _log("error", message="not_found")
                return _err("NOT_FOUND", "group_id refers to a deleted object.", group_id=group_id)

        if parent_object_id is not None:
            po = by_id.get(parent_object_id)
            if not po:
                _log("error", message="not_found")
                return _err("NOT_FOUND", "parent_object_id not found on this board.", parent_object_id=parent_object_id)
            if po.get("status") != "active":
                _log("error", message="not_found")
                return _err("NOT_FOUND", "parent_object_id refers to a deleted object.", parent_object_id=parent_object_id)
            # Application logic: containers such as frames.
            if po.get("object_type") not in ("item_frame", "group"):
                _log("error", message="validation")
                return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object (e.g., a frame).", field="parent_object_id")

        updated = copy.deepcopy(obj)
        if from_object_id is not None:
            updated["connector_from_object_id"] = from_object_id
        if to_object_id is not None:
            updated["connector_to_object_id"] = to_object_id
        if title is not None:
            updated["title"] = title
        if data is not None:
            updated["data"] = data
        if style is not None:
            updated["style"] = style
        if geometry is not None:
            updated["geometry"] = geometry
        if group_id is not None:
            updated["group_id"] = group_id
        if parent_object_id is not None:
            updated["parent_object_id"] = parent_object_id

        # Enforce connector constraints: connector_* required and other connector-specific fields OK.
        if updated.get("object_type") != "connector":
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "Object is not a connector.", field="connector_id")
        if not updated.get("connector_from_object_id") or not updated.get("connector_to_object_id"):
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "Connectors must have connector_from_object_id and connector_to_object_id.")
        if updated.get("connector_from_object_id") not in by_id or updated.get("connector_to_object_id") not in by_id:
            _log("error", message="not_found")
            return _err("NOT_FOUND", "Referenced from/to objects must exist on the same board.")

        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        updated["updated_at"] = now
        objects[idx] = updated
        _save("board_objects.json", objects)

        _log("success", credential_id=next(iter(active_editor_principals)) if active_editor_principals else None)
        return {"connector": updated}
    except Exception as e:
        _log("error", message="internal_error")
        return _err("CONFLICT", "Internal error.", detail=str(e))

def delete_connector(board_id, connector_id, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "delete-connector"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    if not isinstance(connector_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", connector_id):
        _log("error", "VALIDATION_ERROR", {"field": "connector_id"})
        return _err("VALIDATION_ERROR", "connector_id is malformed.", field="connector_id")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_edit = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_edit:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to edit the board.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")
    obj = next((o for o in objs if isinstance(o, dict) and o.get("id") == connector_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("status") == "deleted" or obj.get("object_type") != "connector":
        _log("error", "NOT_FOUND", {"board_id": board_id, "connector_id": connector_id})
        return _err("NOT_FOUND", "Connector not found on this board.", board_id=board_id, connector_id=connector_id)

    obj["status"] = "deleted"
    obj["updated_at"] = now

    links = _load("object_links.json")
    if isinstance(links, list):
        new_links = []
        changed = False
        for r in links:
            if not isinstance(r, dict):
                new_links.append(r)
                continue
            if r.get("board_id") == board_id and (r.get("from_object_id") == connector_id or r.get("to_object_id") == connector_id):
                changed = True
                continue
            new_links.append(r)
        if changed:
            _save("object_links.json", new_links)

    _save("board_objects.json", objs)
    _log("success")
    return {"board_id": board_id, "connector_id": connector_id, "status": "deleted", "deleted": True}

