    def _id_ok(pat, v):
        return isinstance(v, str) and re.match(pat, v) is not None

    def _finite_number(x):
        return isinstance(x, (int, float)) and not (isinstance(x, float) and (math.isinf(x) or math.isnan(x)))

    def _validate_geometry(g):
        if g is None:
            return None
        if not isinstance(g, dict):
            return "geometry must be an object."
        for k in ("x", "y"):
            if k in g and g[k] is not None and not _finite_number(g[k]):
                return f"geometry.{k} must be a finite number."
        return None

    def _gen_id(prefix, rows):
        # 19+ chars uppercase base36-like
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = int(time.time() * 1000)
        x = n
        s = ""
        while x > 0:
            s = alphabet[x % 36] + s
            x //= 36
        s = (s or "0").rjust(19, "0")
        # avoid collisions
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        cand = f"{prefix}_{s}"
        if cand not in existing:
            return cand
        for i in range(1, 10000):
            cand2 = f"{prefix}_{s}{alphabet[i % 36]}"
            if cand2 not in existing:
                return cand2
        return f"{prefix}_{int(time.time()*1000000)}_{len(existing)+1}"

    try:
        if not _id_ok(r"^mir_brd_[0-9A-Z]{19,}$", board_id):
            _log("error", message="validation")
            return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")

        if not isinstance(text_content, str) or text_content.strip() == "":
            _log("error", message="validation")
