            if val is not None and not isinstance(val, dict):
                _log("error", message="validation")
                return _err("VALIDATION_ERROR", f"{nm} must be an object.", field=nm)

        gerr = _validate_geometry(geometry)
        if gerr:
            _log("error", message="validation")
