        for nm, val in (("group_id", group_id), ("parent_object_id", parent_object_id)):
            if val is not None and not _id_ok(r"^mir_obj_[0-9A-Z]{19,}$", val):
                _log("error", message="validation")
                return _err("VALIDATION_ERROR", f"{nm} is malformed.", field=nm)

        boards = _load("boards.json")
        board = next((b for b in boards if b.get("id") == board_id), None)
        if not board:
            _log("error", message="not_found")
            return _err("NOT_FOUND", "Board not found.", board_id=board_id)

        principals = _load("principals.json")
        memberships = _load("board_memberships.json")
        # Need permission to edit: active owner/editor membership.
        editors = [m for m in memberships if m.get("board_id") == board_id and m.get("status") == "active" and m.get("role") in ("owner", "editor")]
        active_editor_principals = {m.get("member_principal_id") for m in editors if isinstance(m.get("member_principal_id"), str)}
