            if po.get("object_type") not in ("item_frame", "group"):
                _log("error", message="validation")
                return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object (e.g., a frame).", field="parent_object_id")

        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        new_id = _gen_id("mir_obj", objects)

        item = {
            "id": new_id,
            "external_miro_object_id": None,
            "board_id": board_id,
            "object_type": "item_sticky_note",
            "status": "active",
            "parent_object_id": parent_object_id,
