    def _board_accessible_to_user(user_id, board, memberships):
        bid = board.get("id")
        if not bid:
            return False
        for m in memberships:
            if m.get("board_id") == bid and m.get("member_principal_id") == user_id and m.get("status") in ("invited", "active"):
                return True
        return False

    def _board_editable_to_user(user_id, board, memberships):
        bid = board.get("id")
        if not bid:
            return False
        for m in memberships:
            if m.get("board_id") == bid and m.get("member_principal_id") == user_id and m.get("status") == "active":
                if m.get("role") in ("owner", "editor"):
                    return True
        return False

    def _finite_number(x):
        return isinstance(x, (int, float)) and not (isinstance(x, float) and (math.isinf(x) or math.isnan(x)))

    def _validate_geometry(g):
        if g is None:
            return None
        if not isinstance(g, dict):
            return "geometry must be an object"
        # only validate x/y if provided
        for k in ("x", "y"):
            if k in g and g[k] is not None and not _finite_number(g[k]):
                return f"geometry.{k} must be a finite number"
        for k in ("width", "height", "rotation"):
            if k in g and g[k] is not None and not _finite_number(g[k]):
                return f"geometry.{k} must be a finite number"
        return None

    # ---- validate inputs ----
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", reason="validation board_id")
        return _err("VALIDATION_ERROR", "Malformed board_id.")
    if not isinstance(item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", item_id):
