        _log("error", reason="validation data type")
        return _err("VALIDATION_ERROR", "data must be an object.")
    if style is not None and not isinstance(style, dict):
        _log("error", reason="validation style type")
        return _err("VALIDATION_ERROR", "style must be an object.")
    geom_err = _validate_geometry(geometry)
    if geom_err:
        _log("error", reason="validation geometry")
        return _err("VALIDATION_ERROR", geom_err)
    if group_id is not None:
        if not isinstance(group_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
            _log("error", reason="validation group_id")
            return _err("VALIDATION_ERROR", "Malformed group_id.")
    if parent_object_id is not None:
        if not isinstance(parent_object_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", parent_object_id):
            _log("error", reason="validation parent_object_id")
            return _err("VALIDATION_ERROR", "Malformed parent_object_id.")

    principals = _load("principals.json")
    boards = _load("boards.json")
    memberships = _load("board_memberships.json")
    objects = _load("board_objects.json")
    links = _load("object_links.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", reason="board not found")
        return _err("NOT_FOUND", "Board not found.")
    if board.get("status") == "deleted":
        _log("error", reason="board deleted")
        return _err("NOT_FOUND", "Board not found.")

    # ambient auth: must be able to edit
    authed_user = None
    for p in principals:
        if not _is_allowed_principal(p):
            continue
        if _board_accessible_to_user(p.get("id"), board, memberships) and _board_editable_to_user(p.get("id"), board, memberships):
            authed_user = p
            break
    if not authed_user:
        _log("error", reason="no editable principal")
        return _err("UNAUTHORIZED", "You don’t have permission to edit the board.")

    idx = None
    obj = None
    for i, o in enumerate(objects):
        if o.get("id") == item_id and o.get("board_id") == board_id:
            idx, obj = i, o
            break
    if not obj or obj.get("object_type") != "item_sticky_note" or obj.get("status") != "active":
        _log("error", principal_id=authed_user.get("id"), reason="item not found or not sticky note")
        return _err("NOT_FOUND", "Sticky note item not found on this board.")

    # validate referenced objects exist on same board
    by_id = {o.get("id"): o for o in objects if o.get("board_id") == board_id}
    if group_id is not None:
        g = by_id.get(group_id)
        if not g or g.get("status") != "active" or g.get("object_type") != "group":
            _log("error", principal_id=authed_user.get("id"), reason="group ref not found")
            return _err("NOT_FOUND", "Referenced group_id not found on this board.")
    if parent_object_id is not None:
        p = by_id.get(parent_object_id)
        if not p or p.get("status") != "active":
            _log("error", principal_id=authed_user.get("id"), reason="parent ref not found")
            return _err("NOT_FOUND", "Referenced parent_object_id not found on this board.")
        # application logic: can contain items (e.g., frame)
        if p.get("object_type") not in ("item_frame",):
            _log("error", principal_id=authed_user.get("id"), reason="parent cannot contain items")
            return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object (e.g., a frame).")

    # Apply updates
    changed = False
    new_obj = dict(obj)

    if title is not None and title != new_obj.get("title"):
        new_obj["title"] = title
        changed = True
    if text_content is not None and text_content != new_obj.get("text_content"):
        new_obj["text_content"] = text_content
        changed = True
    if data is not None:
        # replace for simplicity (vendor says merge/replace; accept as replace)
        if data != new_obj.get("data"):
            new_obj["data"] = data
            changed = True
    if style is not None:
        if style != new_obj.get("style"):
            new_obj["style"] = style
            changed = True
    if geometry is not None:
        # merge patch semantics for geometry dict
        g = new_obj.get("geometry") if isinstance(new_obj.get("geometry"), dict) else {}
        ng = dict(g)
        for k, v in geometry.items():
            ng[k] = v
        if ng != g:
            new_obj["geometry"] = ng
            changed = True
    if group_id is not None and group_id != new_obj.get("group_id"):
        new_obj["group_id"] = group_id
        changed = True
    if parent_object_id is not None and parent_object_id != new_obj.get("parent_object_id"):
        new_obj["parent_object_id"] = parent_object_id
        changed = True

    if not changed:
        # No success without effect: treat as conflict-like validation (idempotent update is not specified)
        _log("error", principal_id=authed_user.get("id"), reason="no changes")
        return _err("CONFLICT", "Update request made no changes.")

    new_obj["updated_at"] = now

    # Remove/ignore object_links referencing deleted objects: no-op here (we didn't delete), but ensure links integrity if group_id set:
    # This API stores group_id on object, but also object_links may exist. We will keep object_links unchanged.

    objects[idx] = new_obj
    _save("board_objects.json", objects)

    _log("ok", principal_id=authed_user.get("id"))
    return {"data": new_obj}

