            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-frame"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logfile():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(status, error_code=None, meta=None):
        if not _ensure_logfile():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _finite_number(x):
        try:
            v = float(x)
            if math.isnan(v) or math.isinf(v):
                return False
            return True
        except Exception:
            return False

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    if not isinstance(title, str) or not title.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required.", field="title")
    if data is not None and not isinstance(data, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "data must be an object.", field="data")
    if style is not None and not isinstance(style, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "style must be an object.", field="style")
    if geometry is not None:
        if not isinstance(geometry, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry must be an object.", field="geometry")
        if "x" in geometry and geometry["x"] is not None and not _finite_number(geometry["x"]):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry.x must be a finite number.", field="geometry.x")
        if "y" in geometry and geometry["y"] is not None and not _finite_number(geometry["y"]):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry.y must be a finite number.", field="geometry.y")

    for opt_field, opt_val in (("group_id", group_id), ("parent_object_id", parent_object_id)):
        if opt_val is not None and (not isinstance(opt_val, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", opt_val)):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{opt_field} is malformed.", field=opt_field)

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []

    def _get_active_obj(oid):
        return next((o for o in objs if isinstance(o, dict) and o.get("id") == oid and o.get("board_id") == board_id and o.get("status") == "active"), None)

    if group_id is not None:
        g = _get_active_obj(group_id)
        if not g:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "group_id not found on board.", group_id=group_id)
        if g.get("object_type") != "group":
            _log("error", "VALIDATION_ERROR")
