        if not p:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "parent_object_id not found on board.", parent_object_id=parent_object_id)
        # Application logic: only frames can contain items (simplified). Allow nesting under frames.
        if p.get("object_type") != "item_frame":
            _log("error", "CONFLICT")
            return _err("CONFLICT", "parent_object_id is not a valid container for a frame.", parent_object_id=parent_object_id, parent_object_type=p.get("object_type"))

    now = _now_iso()
    existing_ids = {o.get("id") for o in objs if isinstance(o, dict)}
    new_id = "mir_obj_" + uuid.uuid4().hex[:18].upper()
    while new_id in existing_ids:
        new_id = "mir_obj_" + uuid.uuid4().hex[:18].upper()

    frame = {
        "id": new_id,
        "external_miro_object_id": None,
        "board_id": board_id,
