    if title is not None and not isinstance(title, str):
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title must be a string")
    for nm, val in (("data", data), ("style", style), ("geometry", geometry)):
        if val is not None and not isinstance(val, dict):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{nm} must be an object")
    for nm, val in (("group_id", group_id), ("parent_object_id", parent_object_id)):
        if val is not None:
            if not isinstance(val, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", val):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"{nm} is malformed")

    # geometry finite checks when provided
    if isinstance(geometry, dict):
        for k in ("x", "y"):
            if k in geometry and geometry[k] is not None:
                if not isinstance(geometry[k], (int, float)) or not math.isfinite(float(geometry[k])):
                    _log("error", {"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number")

    boards = _load("boards.json")
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Board not found")

    memberships = _load("board_memberships.json")
    principals = _load("principals.json")

    def _principal_ok(pid):
        p = next((x for x in principals if x.get("id") == pid), None)
        return p is not None and p.get("status") == "active"

    # Need edit permission: active membership role owner/editor
    editable = [
        m for m in memberships
        if m.get("board_id") == board_id and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        and _principal_ok(m.get("member_principal_id"))
    ]
    if not editable:
        _log("error", {"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "You don’t have permission to edit the board")

    objs = _load("board_objects.json")
    idx = next((i for i, o in enumerate(objs) if o.get("id") == item_id and o.get("board_id") == board_id), None)
    if idx is None:
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Frame item not found on this board")
    obj = objs[idx]
    if obj.get("status") == "deleted" or obj.get("object_type") != "item_frame":
        _log("error", {"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Frame item not found on this board")

    # Validate referenced objects (must exist, same board, not deleted, and type rules)
    def _get_obj(oid):
        return next((o for o in objs if o.get("id") == oid and o.get("board_id") == board_id), None)

    if group_id is not None:
        g = _get_obj(group_id)
        if not g or g.get("status") == "deleted" or g.get("object_type") != "group":
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Referenced group_id not found on this board")

    if parent_object_id is not None:
        p = _get_obj(parent_object_id)
        if not p or p.get("status") == "deleted":
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Referenced parent_object_id not found on this board")
        # application logic: only frames can contain items in this simplified model
        if p.get("object_type") not in ("item_frame",):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object (frame)")

    updated = copy.deepcopy(obj)
    changed = False

    if title is not None:
        updated["title"] = title
        changed = True
    if data is not None:
        updated["data"] = data
        changed = True
    if style is not None:
        updated["style"] = style
        changed = True
    if geometry is not None:
        updated["geometry"] = geometry
        changed = True
    if group_id is not None:
        updated["group_id"] = group_id
        changed = True
    if parent_object_id is not None:
        updated["parent_object_id"] = parent_object_id
        changed = True

    if not changed:
        # Realistic: treat as validation error for empty patch
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No supported fields provided to update")

    updated["updated_at"] = now
    objs[idx] = updated
    _save("board_objects.json", objs)

    _log("ok")
    return {"item": updated}

