    if not isinstance(objects, list):
        objects = []
    obj = next((o for o in objects if o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not obj:
        _log("error", message="NOT_FOUND")
        return _err("NOT_FOUND", "Item not found on this board", board_id=board_id, item_id=item_id)

    if obj.get("object_type") != "item_document":
        _log("error", message="NOT_FOUND")
        return _err("NOT_FOUND", "Item is not a document on this board", board_id=board_id, item_id=item_id)

    if obj.get("status") == "deleted":
        _log("error", message="NOT_FOUND")
        return _err("NOT_FOUND", "Item not found on this board", board_id=board_id, item_id=item_id)

