            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    objects = _load("board_objects.json")
    reqlog = _load("request_logs.json")

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = {
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "get-text-item",
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "timestamp": now,
            "latency_ms": latency_ms,
        }
        reqlog.append(req)
        _save("request_logs.json", reqlog)

    # Validation
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is missing or malformed", field="board_id")
    if not isinstance(item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", item_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "item_id is missing or malformed", field="item_id")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Access: ambient auth. Choose any active/invited membership on this board where member principal is active.
    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict)}
    accessible = False
    for m in memberships:
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("invited", "active"):
            continue
        mp = principal_by_id.get(m.get("member_principal_id"))
        if not mp or mp.get("status") != "active":
            continue
        accessible = True
        break
    if not accessible:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to view this board")

    obj = next((o for o in objects if o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("object_type") != "item_text" or obj.get("status") != "active":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Text item not found on this board", board_id=board_id, item_id=item_id)

    _log("ok")
    return {"item": obj}

