        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "geometry must be an object", field="geometry")
    if parent_object_id is not None:
        if not isinstance(parent_object_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", parent_object_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_object_id is malformed", field="parent_object_id")
    if group_id is not None:
        if not isinstance(group_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "group_id is malformed", field="group_id")

    # Geometry sanity: x/y finite numbers when provided
    if geometry is not None:
        for k in ("x", "y"):
            if k in geometry and geometry[k] is not None:
                v = geometry[k]
                if not isinstance(v, (int, float)) or (isinstance(v, float) and (math.isinf(v) or math.isnan(v))):
                    _log("error", error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number", field=f"geometry.{k}")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Access: require active membership to edit (editor/owner). Ambient auth -> choose any eligible membership.
    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict)}
    can_edit = False
    for m in memberships:
        if m.get("board_id") != board_id:
            continue
        if m.get("status") != "active":
            continue
        if m.get("role") not in ("owner", "editor"):
            continue
        mp = principal_by_id.get(m.get("member_principal_id"))
        if not mp or mp.get("status") != "active":
            continue
        can_edit = True
        break
    if not can_edit:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have permission to update items on this board")

    idx = None
    for i, o in enumerate(objects):
        if o.get("id") == item_id and o.get("board_id") == board_id:
            idx = i
            break
    if idx is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Item not found on this board", board_id=board_id, item_id=item_id)

    obj = objects[idx]
    if obj.get("object_type") != "item_text" or obj.get("status") != "active":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Text item not found on this board", board_id=board_id, item_id=item_id)

    # Validate parent within same board and is a container (frame) per business rule enforcement.
    if parent_object_id is not None:
        parent = next((o for o in objects if o.get("id") == parent_object_id), None)
        if not parent or parent.get("board_id") != board_id or parent.get("status") != "active":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "parent_object_id not found on this board", parent_object_id=parent_object_id)
        # container rule: only frame allowed here
        if parent.get("object_type") not in ("item_frame",):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object", allowed_containers=["item_frame"])

    # Validate group within same board and is group object
    if group_id is not None:
        grp = next((o for o in objects if o.get("id") == group_id), None)
        if not grp or grp.get("board_id") != board_id or grp.get("status") != "active":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "group_id not found on this board", group_id=group_id)
        if grp.get("object_type") != "group":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "group_id must refer to a group object", field="group_id")

    # Apply updates (only provided fields)
    changed = False
    if title is not None:
        obj["title"] = title
        changed = True
    if text_content is not None:
        obj["text_content"] = text_content
        changed = True
    if data is not None:
        obj["data"] = data
        changed = True
    if style is not None:
        obj["style"] = style
        changed = True
    if geometry is not None:
        obj["geometry"] = geometry
        changed = True
    if parent_object_id is not None:
        obj["parent_object_id"] = parent_object_id
        changed = True
    if group_id is not None:
        obj["group_id"] = group_id
        changed = True

    if not changed:
        # No-op update: real APIs usually still return current resource; but "no success without effect" is for mutations matching no row.
        _log("ok")
        return {"item": obj}

    obj["updated_at"] = now
    objects[idx] = obj

    # If group_id changed/assigned, reflect via object_links group_membership uniqueness semantics are handled by update-group tool,
    # but we keep reads consistent by ensuring a link exists when group_id is set.
    # We will not delete/replace other group links here; only ensure link for this group_id and item exists if provided.
    if group_id is not None:
        exists = False
        for l in links:
            if l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("from_object_id") == group_id and l.get("to_object_id") == item_id:
                exists = True
                l["updated_at"] = now
                break
        if not exists:
            links.append({
                "id": f"mir_lnk_{int(time.time()*1000)}",
                "board_id": board_id,
                "link_type": "group_membership",
                "from_object_id": group_id,
                "to_object_id": item_id,
                "position_index": None,
                "created_at": now,
                "updated_at": now
            })

    _save("board_objects.json", objects)
    _save("object_links.json", links)

    _log("ok")
    return {"item": obj}

