def create_items_in_bulk(board_id, items, **_extra):
    import json, os, datetime, re, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    objects = _load("board_objects.json")
    links = _load("object_links.json")
    reqlog = _load("request_logs.json")

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = {
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "create-items-in-bulk",
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "timestamp": now,
            "latency_ms": latency_ms,
        }
        reqlog.append(req)
        _save("request_logs.json", reqlog)

    # Validate board_id and items
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is missing or malformed", field="board_id")
    if not isinstance(items, list) or len(items) < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "items must be a non-empty array", field="items")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Access: require active membership role owner/editor
    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict)}
    can_create = False
    for m in memberships:
        if m.get("board_id") != board_id:
            continue
        if m.get("status") != "active":
            continue
        if m.get("role") not in ("owner", "editor"):
            continue
        mp = principal_by_id.get(m.get("member_principal_id"))
        if not mp or mp.get("status") != "active":
            continue
        can_create = True
        break
    if not can_create:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have permission to create items on this board")

    supported = {
        "item_app_card", "item_card", "item_sticky_note", "item_frame", "item_document",
        "item_text", "item_image", "item_shape", "item_embed", "item_mindmap_node"
    }

    # Build id generator
    def _new_id(prefix):
        # 18+ chars uppercase/digits
        base = int(time.time() * 1000000)
        s = base
        chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        out = ""
        while s > 0 and len(out) < 22:
            s, r = divmod(s, 36)
            out = chars[r] + out
        out = (out or "0").rjust(18, "0")
        return f"{prefix}_{out}"

    # Pre-index existing objects on this board
    objs_by_id = {o.get("id"): o for o in objects if isinstance(o, dict)}
    # Transactional/atomic: validate everything first, then persist once.
    pending = []
    pending_links = []

    for idx, it in enumerate(items):
        if not isinstance(it, dict):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each item must be an object", index=idx)
        if "object_type" not in it:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each item must include object_type", index=idx, field="object_type")
        ot = it.get("object_type")
        if not isinstance(ot, str) or ot not in supported:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported object_type", index=idx, field="object_type", allowed=sorted(supported))

        # Type checks for known fields
        for f in ("title", "text_content", "image_source_url", "image_asset_ref"):
            if f in it and it[f] is not None and not isinstance(it[f], str):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{f} must be a string", index=idx, field=f)
        for f in ("data", "style", "geometry"):
            if f in it and it[f] is not None and not isinstance(it[f], dict):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"{f} must be an object", index=idx, field=f)

        po = it.get("parent_object_id")
        if po is not None:
            if not isinstance(po, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", po):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "parent_object_id is malformed", index=idx, field="parent_object_id")
            parent = objs_by_id.get(po)
            if not parent or parent.get("board_id") != board_id or parent.get("status") != "active":
                _log("error", error_code="NOT_FOUND")
                return _err("NOT_FOUND", "parent_object_id not found on this board", index=idx, parent_object_id=po)
            if parent.get("object_type") not in ("item_frame",):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object", index=idx, allowed_containers=["item_frame"])

        gid = it.get("group_id")
        if gid is not None:
            if not isinstance(gid, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", gid):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "group_id is malformed", index=idx, field="group_id")
            grp = objs_by_id.get(gid)
            if not grp or grp.get("board_id") != board_id or grp.get("status") != "active":
                _log("error", error_code="NOT_FOUND")
                return _err("NOT_FOUND", "group_id not found on this board", index=idx, group_id=gid)
            if grp.get("object_type") != "group":
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "group_id must refer to a group object", index=idx, field="group_id")

        geo = it.get("geometry")
        if isinstance(geo, dict):
            for k in ("x", "y"):
                if k in geo and geo[k] is not None:
                    v = geo[k]
                    if not isinstance(v, (int, float)) or (isinstance(v, float) and (math.isinf(v) or math.isnan(v))):
                        _log("error", error_code="VALIDATION_ERROR")
                        return _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number", index=idx, field=f"geometry.{k}")

        # Image XOR rule for item_image
        if ot == "item_image":
            src = it.get("image_source_url")
            aref = it.get("image_asset_ref")
            if (src is None or src == "") and (aref is None or aref == ""):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "item_image requires image_source_url or image_asset_ref", index=idx)
            if src and aref:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Provide only one of image_source_url or image_asset_ref", index=idx)
        else:
            # Non-image must not include image fields (unsupported properties semantics)
            if it.get("image_source_url") is not None or it.get("image_asset_ref") is not None:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "image_* fields are only supported for item_image", index=idx)

        new_obj_id = _new_id("mir_obj")
        # Ensure uniqueness vs existing
        while new_obj_id in objs_by_id:
            new_obj_id = _new_id("mir_obj")

        new_obj = {
            "id": new_obj_id,
            "external_miro_object_id": None,
            "board_id": board_id,
            "object_type": ot,
            "status": "active",
            "parent_object_id": it.get("parent_object_id"),
            "group_id": it.get("group_id"),
            "title": it.get("title"),
            "text_content": it.get("text_content"),
            "data": it.get("data"),
            "style": it.get("style"),
            "geometry": it.get("geometry"),
            "connector_from_object_id": None,
            "connector_to_object_id": None,
            "image_source_url": it.get("image_source_url") if ot == "item_image" else None,
            "image_asset_ref": it.get("image_asset_ref") if ot == "item_image" else None,
            "created_by_user_id": None,
            "created_at": now,
            "updated_at": now,
        }
        pending.append(new_obj)
        objs_by_id[new_obj_id] = new_obj

        # If group_id provided, create group_membership link to keep link table consistent with reads.
        if it.get("group_id") is not None:
            pending_links.append({
                "id": _new_id("mir_lnk"),
                "board_id": board_id,
                "link_type": "group_membership",
                "from_object_id": it.get("group_id"),
                "to_object_id": new_obj_id,
                "position_index": None,
                "created_at": now,
                "updated_at": now
            })

    # Persist atomically (single write after full validation)
    objects2 = list(objects) + pending
    links2 = list(links) + pending_links
    _save("board_objects.json", objects2)
    _save("object_links.json", links2)

    _log("ok")
    return {"items": pending, "count": len(pending)}

def create_image_item_using_url(board_id, image_url, title=None, geometry=None, style=None, parent_object_id=None, group_id=None, data=None, **_extra):
    import json, os, datetime
    import re, time, base64
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        reqs.append({
            "id": f"req_{int(time.time()*1000)}_{len(reqs)+1}",
            "endpoint": "create-image-item-using-url",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", reqs)

    def _rate_limit_check():
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        # Best-effort: 120 req/min global if logs exist; otherwise no enforcement.
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in reqs:
            if isinstance(r, dict) and r.get("created_at"):
                try:
                    ts = datetime.datetime.fromisoformat(str(r["created_at"]).replace("Z", "+00:00")).replace(tzinfo=None)
                    if ts >= cutoff:
                        c += 1
                except Exception:
                    continue
        if c >= 120:
            return False
        return True

    def _valid_id(pat, s):
        return isinstance(s, str) and re.match(pat, s or "") is not None

    def _valid_uri(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            pr = urlparse(u)
        except Exception:
            return False
        if pr.scheme not in ("http", "https"):
            return False
        if not pr.netloc:
            return False
        return True

    def _finite_number(x):
        if not isinstance(x, (int, float)):
            return False
        if x != x:
            return False
        if x in (float("inf"), float("-inf")):
            return False
        return True

    def _validate_geometry(g):
        if g is None:
            return None
        if not isinstance(g, dict):
            return "geometry must be an object"
        # Enforce x/y finite if present
        if "x" in g and g["x"] is not None and not _finite_number(g["x"]):
            return "geometry.x must be a finite number"
        if "y" in g and g["y"] is not None and not _finite_number(g["y"]):
            return "geometry.y must be a finite number"
        return None

    # Rate limit check (if applicable)
    if not _rate_limit_check():
        _log("error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Validate inputs
    if not _valid_id(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is malformed")
    if not _valid_uri(image_url):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image_url is not a valid URI")
    if title is not None and not isinstance(title, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a string")
    if geometry is not None and not isinstance(geometry, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "geometry must be an object")
    if style is not None and not isinstance(style, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "style must be an object")
    if data is not None and not isinstance(data, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "data must be an object")
    if parent_object_id is not None and not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", parent_object_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_object_id is malformed")
    if group_id is not None and not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "group_id is malformed")

    gerr = _validate_geometry(geometry)
    if gerr:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", gerr)

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found")
    if board.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found")

    # Ambient auth: require that some active/invited membership exists for this board
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []
    accessible = any(isinstance(m, dict) and m.get("board_id") == board_id and m.get("status") in ("active", "invited") for m in memberships)
    if not accessible:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized for this board")

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []

    obj_by_id = {o.get("id"): o for o in objs if isinstance(o, dict) and o.get("id")}

    def _ensure_same_board_object(oid, what):
        o = obj_by_id.get(oid)
        if not o or o.get("board_id") != board_id:
            return None, _err("NOT_FOUND", f"{what} not found on board")
        if o.get("status") == "deleted":
            return None, _err("NOT_FOUND", f"{what} not found on board")
        return o, None

    if parent_object_id is not None:
        parent, e = _ensure_same_board_object(parent_object_id, "parent_object_id")
        if e:
            _log("error", error_code=e["error"]["code"])
            return e
        # Application logic: only frames can contain items (minimal enforcement)
        if parent.get("object_type") != "item_frame":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object (frame)")
    if group_id is not None:
        grp, e = _ensure_same_board_object(group_id, "group_id")
        if e:
            _log("error", error_code=e["error"]["code"])
            return e
        if grp.get("object_type") != "group":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "group_id must refer to an object of type 'group'")

    # Generate new object id
    import secrets, string
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    def _new_obj_id():
        while True:
            suffix = "".join(secrets.choice(alphabet) for _ in range(18))
            nid = "mir_obj_" + suffix
            if nid not in obj_by_id:
                return nid

    new_id = _new_obj_id()
    created_by_user_id = None
    # Best effort: pick any active user principal referenced by an active membership as creator
    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and p.get("id")}
    for m in memberships:
        if isinstance(m, dict) and m.get("board_id") == board_id and m.get("status") == "active":
            pid = m.get("member_principal_id")
            p = principal_by_id.get(pid)
            if p and p.get("principal_type") == "user" and p.get("status") == "active":
                created_by_user_id = pid
                break

    new_obj = {
        "id": new_id,
        "external_miro_object_id": None,
        "board_id": board_id,
        "object_type": "item_image",
        "status": "active",
        "parent_object_id": parent_object_id,
        "group_id": group_id,
        "title": title,
        "text_content": None,
        "data": data,
        "style": style,
        "geometry": geometry,
        "connector_from_object_id": None,
        "connector_to_object_id": None,
        "image_source_url": image_url,
        "image_asset_ref": None,
        "created_by_user_id": created_by_user_id,
        "created_at": now,
        "updated_at": now
    }

    # Enforce image_source_url XOR image_asset_ref (here: url set, asset_ref must be null)
    if new_obj["image_asset_ref"] is not None or not new_obj["image_source_url"]:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "For URL-created image item, image_source_url must be set and image_asset_ref must be null")

    # Persist
    objs.append(new_obj)
    _save("board_objects.json", objs)

    _log("success")
    return {"data": new_obj}

def create_image_item_using_file(board_id, file_name, file_content_base64, title=None, geometry=None, style=None, parent_object_id=None, group_id=None, data=None, **_extra):
    import json, os, datetime, re, math, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "create-image-item-using-file"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _finite_number(x):
        try:
            v = float(x)
            return not (math.isnan(v) or math.isinf(v))
        except Exception:
            return False

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    if not isinstance(file_name, str) or not file_name.strip():
        _log("error", "VALIDATION_ERROR", {"field": "file_name"})
        return _err("VALIDATION_ERROR", "file_name is required.", field="file_name")
    if not isinstance(file_content_base64, str) or not file_content_base64.strip():
        _log("error", "VALIDATION_ERROR", {"field": "file_content_base64"})
        return _err("VALIDATION_ERROR", "file_content_base64 is required.", field="file_content_base64")
    if title is not None and not isinstance(title, str):
        _log("error", "VALIDATION_ERROR", {"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a string.", field="title")
    for f, v in (("geometry", geometry), ("style", style), ("data", data)):
        if v is not None and not isinstance(v, dict):
            _log("error", "VALIDATION_ERROR", {"field": f})
            return _err("VALIDATION_ERROR", f"{f} must be an object.", field=f)
    for f, v in (("parent_object_id", parent_object_id), ("group_id", group_id)):
        if v is not None and (not isinstance(v, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", v)):
            _log("error", "VALIDATION_ERROR", {"field": f})
            return _err("VALIDATION_ERROR", f"{f} is malformed.", field=f)

    if geometry is not None:
        if "x" in geometry and not _finite_number(geometry.get("x")):
            _log("error", "VALIDATION_ERROR", {"field": "geometry.x"})
            return _err("VALIDATION_ERROR", "geometry.x must be a finite number.", field="geometry.x")
        if "y" in geometry and not _finite_number(geometry.get("y")):
            _log("error", "VALIDATION_ERROR", {"field": "geometry.y"})
            return _err("VALIDATION_ERROR", "geometry.y must be a finite number.", field="geometry.y")

    # validate base64
    try:
        raw = base64.b64decode(file_content_base64, validate=True)
    except Exception:
        _log("error", "VALIDATION_ERROR", {"field": "file_content_base64"})
        return _err("VALIDATION_ERROR", "file_content_base64 is not valid base64.", field="file_content_base64")
    if len(raw) == 0:
        _log("error", "VALIDATION_ERROR", {"field": "file_content_base64"})
        return _err("VALIDATION_ERROR", "file_content_base64 decodes to empty content.", field="file_content_base64")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_edit = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_edit:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to create items on the board.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")

    def _find_active(oid):
        o = next((x for x in objs if isinstance(x, dict) and x.get("id") == oid and x.get("board_id") == board_id), None)
        if not o or o.get("status") == "deleted":
            return None
        return o

    if parent_object_id is not None:
        parent = _find_active(parent_object_id)
        if not parent:
            _log("error", "NOT_FOUND", {"parent_object_id": parent_object_id})
            return _err("NOT_FOUND", "parent_object_id not found on this board.", board_id=board_id, parent_object_id=parent_object_id)
        # application logic: only frames can contain children (simplified)
        if parent.get("object_type") != "item_frame":
            _log("error", "CONFLICT", {"parent_object_id": parent_object_id})
            return _err("CONFLICT", "parent_object_id is not a valid container.", parent_object_id=parent_object_id)

    if group_id is not None:
        grp = _find_active(group_id)
        if not grp:
            _log("error", "NOT_FOUND", {"group_id": group_id})
            return _err("NOT_FOUND", "group_id not found on this board.", board_id=board_id, group_id=group_id)
        if grp.get("object_type") != "group":
            _log("error", "VALIDATION_ERROR", {"field": "group_id"})
            return _err("VALIDATION_ERROR", "group_id must refer to a group object.", field="group_id")

    existing_ids = {o.get("id") for o in objs if isinstance(o, dict)}
    new_id = None
    for _ in range(20):
        cand = "mir_obj_" + uuid.uuid4().hex[:18].upper()
        if cand not in existing_ids:
            new_id = cand
            break
    if not new_id:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unable to allocate object id.")

    # must store image_asset_ref and not image_source_url
    asset_hash = hashlib.sha256(raw).hexdigest()
    asset_ref = f"asset_sha256:{asset_hash}"

    row = {
        "id": new_id,
        "external_miro_object_id": None,
        "board_id": board_id,
        "object_type": "item_image",
        "status": "active",
        "parent_object_id": parent_object_id,
        "group_id": group_id,
        "title": title,
        "text_content": None,
        "data": dict(data) if isinstance(data, dict) else None,
        "style": style,
        "geometry": geometry,
        "connector_from_object_id": None,
        "connector_to_object_id": None,
        "image_source_url": None,
        "image_asset_ref": asset_ref,
        "created_by_user_id": None,
        "created_at": now,
        "updated_at": now,
    }
    # store file metadata in data payload (opaque)
    if row["data"] is None:
        row["data"] = {}
    row["data"].setdefault("file_name", file_name)
    row["data"].setdefault("content_length", len(raw))

    objs.append(row)
    _save("board_objects.json", objs)
    _log("success")
    return {"item": row}

