        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized for this board")

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []
    obj = next((o for o in objs if isinstance(o, dict) and o.get("id") == image_item_id and o.get("board_id") == board_id), None)
    if not obj:
        _log("error", error_code="NOT_FOUND")
