    if obj.get("status") == "deleted" or obj.get("object_type") != "item_image":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Image item not found on board")

    obj_by_id = {o.get("id"): o for o in objs if isinstance(o, dict) and o.get("id")}

    def _ensure_same_board_object(oid, what):
        o = obj_by_id.get(oid)
        if not o or o.get("board_id") != board_id:
            return None, _err("NOT_FOUND", f"{what} not found on board")
        if o.get("status") == "deleted":
            return None, _err("NOT_FOUND", f"{what} not found on board")
        return o, None

    if parent_object_id is not None:
        parent, e = _ensure_same_board_object(parent_object_id, "parent_object_id")
        if e:
            _log("error", error_code=e["error"]["code"])
            return e
        if parent.get("object_type") != "item_frame":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_object_id must refer to a container object (frame)")
    if group_id is not None:
        grp, e = _ensure_same_board_object(group_id, "group_id")
        if e:
            _log("error", error_code=e["error"]["code"])
            return e
        if grp.get("object_type") != "group":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "group_id must refer to an object of type 'group'")

    # Update mutable fields only if provided
    updated = dict(obj)
    if title is not None:
        updated["title"] = title
    if geometry is not None:
        updated["geometry"] = geometry
    if style is not None:
        updated["style"] = style
    if data is not None:
        updated["data"] = data
    if parent_object_id is not None:
        updated["parent_object_id"] = parent_object_id
    if group_id is not None:
        updated["group_id"] = group_id

    # Maintain XOR invariant for image item source fields (cannot set via this tool, but must remain consistent)
    src = updated.get("image_source_url")
    aref = updated.get("image_asset_ref")
    if (src and aref) or (not src and not aref):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Image item is in an inconsistent state (image_source_url vs image_asset_ref)")

    updated["updated_at"] = now
    objs[idx] = updated
    _save("board_objects.json", objs)

    _log("success")
    return {"data": updated}

def update_image_item_using_file(board_id, image_item_id, file_name, file_content_base64, title=None, geometry=None, style=None, parent_object_id=None, group_id=None, data=None, **_extra):
    import json, os, datetime, re, time, math, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        rid = "mir_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": rid,
            "service": "miro",
            "endpoint": "update-image-item-using-file",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    def _valid_id(pat, s):
        return isinstance(s, str) and re.match(pat, s) is not None

    def _finite_number(x):
        return isinstance(x, (int, float)) and math.isfinite(float(x))

    def _board_accessible(board, principals, memberships):
        board_id_ = board.get("id")
        if not board_id_:
            return None
        if not isinstance(memberships, list):
            return None
        principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict)}
        for m in memberships:
            if not isinstance(m, dict):
                continue
            if m.get("board_id") != board_id_:
                continue
            if m.get("status") not in ("active", "invited"):
                continue
            pid = m.get("member_principal_id")
            p = principal_by_id.get(pid)
            if p and p.get("principal_type") == "user" and p.get("status") == "active":
                return pid
        return None

    def _container_supports(parent_obj):
        return parent_obj.get("object_type") in ("item_frame", "item_document")

    # ---- validation ----
    if not _valid_id(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is malformed.")
    if not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", image_item_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image_item_id is malformed.")
    if not isinstance(file_name, str) or not file_name.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "file_name is required.")
    if not isinstance(file_content_base64, str) or not file_content_base64.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "file_content_base64 is required.")
    if title is not None and not isinstance(title, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a string when provided.")
    if geometry is not None and not isinstance(geometry, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "geometry must be an object when provided.")
    if style is not None and not isinstance(style, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "style must be an object when provided.")
    if data is not None and not isinstance(data, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "data must be an object when provided.")
    if parent_object_id is not None and not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", parent_object_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_object_id is malformed.")
    if group_id is not None and not _valid_id(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "group_id is malformed.")

    if geometry is not None:
        if "x" in geometry and geometry["x"] is not None and not _finite_number(geometry["x"]):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry.x must be a finite number when provided.")
        if "y" in geometry and geometry["y"] is not None and not _finite_number(geometry["y"]):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry.y must be a finite number when provided.")

    # base64 decode validation
    try:
        file_bytes = base64.b64decode(file_content_base64, validate=True)
    except Exception:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "file_content_base64 is not valid base64.")
    if len(file_bytes) == 0:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Uploaded file is empty.")

    # ---- load store ----
    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    objects = _load("board_objects.json")
    links = _load("object_links.json")

    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")

    acting_user_id = _board_accessible(board, principals, memberships)
    if acting_user_id is None:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible principal found for this operation.")

    obj = next((o for o in objects if isinstance(o, dict) and o.get("id") == image_item_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Image item not found on this board.")
    if obj.get("object_type") != "item_image":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image_item_id must refer to an object of type 'item_image'.")

    # validate parent/group if provided
    if parent_object_id is not None:
        parent = next((o for o in objects if isinstance(o, dict) and o.get("id") == parent_object_id and o.get("board_id") == board_id), None)
        if not parent or parent.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Parent object not found on this board.")
        if not _container_supports(parent):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Referenced parent_object_id does not support containing items.")
        if parent_object_id == image_item_id:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_object_id cannot be the item itself.")

    if group_id is not None:
        grp = next((o for o in objects if isinstance(o, dict) and o.get("id") == group_id and o.get("board_id") == board_id), None)
        if not grp or grp.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Group not found on this board.")
        if grp.get("object_type") != "group":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "group_id must refer to an object of type 'group'.")

    # ---- apply updates (must have effect) ----
    changed = False

    # Store file-backed ref, must not store source url
    digest = hashlib.sha256(file_bytes).hexdigest()[:32]
    asset_ref = "mir_asset_" + digest
    # If already same asset, still allow other metadata changes; otherwise update asset.
    if obj.get("image_asset_ref") != asset_ref:
        obj["image_asset_ref"] = asset_ref
        changed = True
    if obj.get("image_source_url") is not None:
        obj["image_source_url"] = None
        changed = True

    # Store/merge some data about file in obj.data (allowed)
    if obj.get("data") is None:
        obj["data"] = {}
    if isinstance(obj.get("data"), dict):
        # keep existing, update with provided data (if any), and record filename
        if obj["data"].get("file_name") != file_name:
            obj["data"]["file_name"] = file_name
            changed = True

    if title is not None and obj.get("title") != title:
        obj["title"] = title
        changed = True
    if geometry is not None:
        obj["geometry"] = geometry
        changed = True
    if style is not None:
        obj["style"] = style
        changed = True
    if data is not None:
        # replace/overlay semantics: store as-is (replace)
        obj["data"] = data
        # ensure file_name retained
        if isinstance(obj["data"], dict) and obj["data"].get("file_name") != file_name:
            obj["data"]["file_name"] = file_name
        changed = True
    if parent_object_id is not None and obj.get("parent_object_id") != parent_object_id:
        obj["parent_object_id"] = parent_object_id
        changed = True
    if group_id is not None and obj.get("group_id") != group_id:
        obj["group_id"] = group_id
        changed = True

    # Maintain group membership links if group_id provided
    if group_id is not None and isinstance(links, list):
        before = len(links)
        links = [l for l in links if not (isinstance(l, dict) and l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("to_object_id") == image_item_id)]
        if len(links) != before:
            changed = True
        exists = any(isinstance(l, dict) and l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("from_object_id") == group_id and l.get("to_object_id") == image_item_id for l in links)
        if not exists:
            lid = "mir_lnk_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
            links.append({
                "id": lid,
                "board_id": board_id,
                "link_type": "group_membership",
                "from_object_id": group_id,
                "to_object_id": image_item_id,
                "position_index": None,
                "created_at": now,
                "updated_at": now
            })
            changed = True

    if not changed:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "No changes to apply.")

    obj["updated_at"] = now
    _save("board_objects.json", objects)
    _save("object_links.json", links)

    # Add enterprise content log if enterprise board
    if board.get("organization_id"):
        ent = _load("enterprise_ops.json")
        if isinstance(ent, list):
            ent_id = "mir_ent_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
            ent.append({
                "id": ent_id,
                "record_type": "board_content_log",
                "organization_id": board.get("organization_id"),
                "board_id": board_id,
                "case_id": None,
                "legal_hold_id": None,
                "object_id": image_item_id,
                "status": "immutable",
                "payload": {
                    "action": "update-image-item-using-file",
                    "actor_user_id": acting_user_id,
                    "file_name": file_name,
                    "image_asset_ref": obj.get("image_asset_ref"),
                    "changes": {
                        "title": title if title is not None else None,
                        "geometry": geometry if geometry is not None else None,
                        "style": style if style is not None else None,
                        "parent_object_id": parent_object_id if parent_object_id is not None else None,
                        "group_id": group_id if group_id is not None else None,
                        "data": data if data is not None else None
                    }
                },
                "occurred_at": now,
                "expires_at": None,
                "created_at": now,
                "updated_at": now
            })
            _save("enterprise_ops.json", ent)

    _log("ok")
    return {"image_item": obj}

