            _log_request(reqlog, None, "error", err["error"]["code"]); _save("request_logs.json", reqlog)
            return err
        if data is not None and not isinstance(data, dict):
            err = _err("VALIDATION_ERROR", "data must be an object when provided.")
            _log_request(reqlog, None, "error", err["error"]["code"]); _save("request_logs.json", reqlog)
            return err
        if parent_object_id is not None:
            if not isinstance(parent_object_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", parent_object_id):
                err = _err("VALIDATION_ERROR", "parent_object_id is malformed.")
