            if not parent:
                err = _err("NOT_FOUND", "parent_object_id not found on this board.")
                _log_request(reqlog, None, "error", err["error"]["code"]); _save("request_logs.json", reqlog)
                return err
            if parent.get("object_type") not in ("item_frame", "group", "item_document"):
                err = _err("VALIDATION_ERROR", "parent_object_id refers to an object that cannot contain items.")
                _log_request(reqlog, None, "error", err["error"]["code"]); _save("request_logs.json", reqlog)
                return err

        if group_id is not None:
            grp = next((o for o in objects if isinstance(o, dict) and o.get("id") == group_id and o.get("board_id") == board_id and o.get("status") == "active"), None)
            if not grp:
                err = _err("NOT_FOUND", "group_id not found on this board.")
