            if grp.get("object_type") != "group":
                err = _err("VALIDATION_ERROR", "group_id must refer to a group object.")
                _log_request(reqlog, None, "error", err["error"]["code"]); _save("request_logs.json", reqlog)
                return err

        now = _iso_now()
        new_id = f"mir_obj_{secrets.token_hex(10).upper()}"
        # ensure uniqueness
        existing_ids = {o.get("id") for o in objects if isinstance(o, dict)}
        while new_id in existing_ids:
            new_id = f"mir_obj_{secrets.token_hex(10).upper()}"

        row = {
            "id": new_id,
            "external_miro_object_id": None,
            "board_id": board_id,
