            "created_by_user_id": None,
            "created_at": now,
            "updated_at": now
        }

        objects.append(row)
        _save("board_objects.json", objects)

        _log_request(reqlog, None, "success", None); _save("request_logs.json", reqlog)
        return {"shape_item": row}
    except Exception as e:
        err = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        _log_request(reqlog, None, "error", err["error"]["code"]); _save("request_logs.json", reqlog)
        return err

def update_shape_item(board_id, shape_item_id, title=None, text_content=None, data=None, style=None, geometry=None, parent_object_id=None, group_id=None, **_extra):
    import json, os, datetime, re, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers ---
    BRD_RE = re.compile(r"^mir_brd_[0-9A-Z]{18,}$")
    OBJ_RE = re.compile(r"^mir_obj_[0-9A-Z]{18,}$")

    def _is_finite_number(v):
        try:
            if isinstance(v, bool):  # bool is int subclass
                return False
            if isinstance(v, (int, float)):
                return math.isfinite(float(v))
            return False
        except Exception:
            return False

    def _validate_geometry(g):
        if g is None:
            return None
        if not isinstance(g, dict):
            return "geometry must be an object"
        # enforce finite x/y if provided
        if "x" in g and g["x"] is not None and not _is_finite_number(g["x"]):
            return "geometry.x must be a finite number"
        if "y" in g and g["y"] is not None and not _is_finite_number(g["y"]):
            return "geometry.y must be a finite number"
        return None

    def _can_container_be_parent(obj_row):
        # application logic: frames (and possibly groups) can contain items; enforce at least frame
        return obj_row.get("object_type") in ("item_frame",)

    def _log(endpoint, status, credential_id=None, meta=None):
        # Best-effort request logging if a collection exists; do not fail the call if logging fails.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    endpoint = "update-shape-item"

    # --- validation ---
    if not isinstance(board_id, str) or not BRD_RE.match(board_id):
        res = _err("VALIDATION_ERROR", "board_id is malformed", field="board_id")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    if not isinstance(shape_item_id, str) or not OBJ_RE.match(shape_item_id):
        res = _err("VALIDATION_ERROR", "shape_item_id is malformed", field="shape_item_id")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res

    if title is not None and not isinstance(title, str):
        res = _err("VALIDATION_ERROR", "title must be a string", field="title")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    if text_content is not None and not isinstance(text_content, str):
        res = _err("VALIDATION_ERROR", "text_content must be a string", field="text_content")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    if data is not None and not isinstance(data, dict):
        res = _err("VALIDATION_ERROR", "data must be an object", field="data")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    if style is not None and not isinstance(style, dict):
        res = _err("VALIDATION_ERROR", "style must be an object", field="style")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    geo_err = _validate_geometry(geometry)
    if geo_err:
        res = _err("VALIDATION_ERROR", geo_err, field="geometry")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res

    if parent_object_id is not None:
        if not isinstance(parent_object_id, str) or not OBJ_RE.match(parent_object_id):
            res = _err("VALIDATION_ERROR", "parent_object_id is malformed", field="parent_object_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
            except Exception: pass
            return res
    if group_id is not None:
        if not isinstance(group_id, str) or not OBJ_RE.match(group_id):
            res = _err("VALIDATION_ERROR", "group_id is malformed", field="group_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
            except Exception: pass
            return res

    # --- load state ---
    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        res = _err("NOT_FOUND", "Board not found", board_id=board_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []

    obj = next((o for o in objs if o.get("id") == shape_item_id and o.get("board_id") == board_id), None)
    if not obj:
        res = _err("NOT_FOUND", "Shape item not found on this board", board_id=board_id, shape_item_id=shape_item_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    if obj.get("object_type") != "item_shape":
        res = _err("VALIDATION_ERROR", "Object is not a shape item", shape_item_id=shape_item_id, object_type=obj.get("object_type"))
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    if obj.get("status") == "deleted":
        res = _err("NOT_FOUND", "Shape item not found (deleted)", board_id=board_id, shape_item_id=shape_item_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    # Ambient auth: pick any plausible active membership granting edit rights.
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []
    allowed_roles = {"owner", "editor"}
    has_access = any(
        m.get("board_id") == board_id and m.get("status") == "active" and m.get("role") in allowed_roles
        for m in memberships
    )
    if not has_access:
        # Per contract: use UNAUTHORIZED (vendor mentions FORBIDDEN; not allowed here)
        res = _err("UNAUTHORIZED", "Not permitted to edit this board/item", board_id=board_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    # validate references / constraints for parent/group within same board
    id_to_obj = {o.get("id"): o for o in objs if o.get("board_id") == board_id}

    if parent_object_id is not None:
        if parent_object_id == shape_item_id:
            res = _err("CONFLICT", "parent_object_id cannot be the item itself", field="parent_object_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        parent = id_to_obj.get(parent_object_id)
        if not parent or parent.get("status") == "deleted":
            res = _err("NOT_FOUND", "parent_object_id not found on this board", parent_object_id=parent_object_id)
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        if not _can_container_be_parent(parent):
            res = _err("CONFLICT", "Requested parent cannot contain items", parent_object_id=parent_object_id, parent_object_type=parent.get("object_type"))
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res

    if group_id is not None:
        if group_id == shape_item_id:
            res = _err("CONFLICT", "group_id cannot be the item itself", field="group_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        grp = id_to_obj.get(group_id)
        if not grp or grp.get("status") == "deleted":
            res = _err("NOT_FOUND", "group_id not found on this board", group_id=group_id)
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        if grp.get("object_type") != "group":
            res = _err("CONFLICT", "group_id must refer to a group object", group_id=group_id, object_type=grp.get("object_type"))
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res

    # --- apply patch ---
    changed = False
    for k, v in (("title", title), ("text_content", text_content), ("data", data), ("style", style), ("geometry", geometry),
                 ("parent_object_id", parent_object_id), ("group_id", group_id)):
        if v is not None:
            if obj.get(k) != v:
                obj[k] = v
                changed = True

    if not changed:
        # Idempotent: still "success", but must be a real row return.
        try: _log(endpoint, "success", meta={"board_id": board_id, "shape_item_id": shape_item_id, "idempotent": True})
        except Exception: pass
        return {"data": obj, "meta": {"board_id": board_id}}

    obj["updated_at"] = now
    _save("board_objects.json", objs)

    # remove any object_links that now reference deleted objects (cleanup rule)
    links = _load("object_links.json")
    if isinstance(links, list):
        active_obj_ids = {o.get("id") for o in objs if o.get("board_id") == board_id and o.get("status") != "deleted"}
        new_links = []
        pruned = 0
        for l in links:
            if l.get("board_id") != board_id:
                new_links.append(l)
                continue
            if l.get("from_object_id") in active_obj_ids and l.get("to_object_id") in active_obj_ids:
                new_links.append(l)
            else:
                pruned += 1
        if pruned:
            _save("object_links.json", new_links)

    try: _log(endpoint, "success", meta={"board_id": board_id, "shape_item_id": shape_item_id})
    except Exception: pass
    return {"data": obj, "meta": {"board_id": board_id}}

