        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete-shape-item"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    try:
        if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "board_id is malformed")
        if not isinstance(shape_item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", shape_item_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "shape_item_id is malformed")

        boards = _load("boards.json")
        if not isinstance(boards, list): boards = []
        board = next((b for b in boards if b.get("id") == board_id), None)
        if not board or board.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Board not found")

        objs = _load("board_objects.json")
        if not isinstance(objs, list): objs = []

        obj = next((o for o in objs if o.get("id") == shape_item_id and o.get("board_id") == board_id), None)
        if not obj:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Shape item not found on this board")

        if obj.get("object_type") != "item_shape":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Object is not a shape item")

        if obj.get("status") == "deleted":
            # idempotent soft-delete
            _log("ok")
            return {"shape_item": obj}

        # lifecycle transition: active -> deleted only
        if obj.get("status") != "active":
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot delete item from current status", current_status=obj.get("status"))

        obj["status"] = "deleted"
        obj["updated_at"] = now

        # remove links referencing this deleted object
        links = _load("object_links.json")
        if not isinstance(links, list): links = []
        new_links = [l for l in links if not (l.get("board_id") == board_id and (l.get("from_object_id") == shape_item_id or l.get("to_object_id") == shape_item_id))]
        if len(new_links) != len(links):
            _save("object_links.json", new_links)

        _save("board_objects.json", objs)
        _log("ok")
        return {"shape_item": obj}
    except Exception as e:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def create_embed_item(board_id, geometry, data, title=None, style=None, parent_object_id=None, group_id=None, **_extra):
    import json, os, datetime, re, time, math, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-embed-item"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now,
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    try:
        if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "board_id is malformed")
        if not isinstance(geometry, dict):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "geometry must be an object")
        if not isinstance(data, dict):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "data must be an object")
        if title is not None and not isinstance(title, str):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title must be a string")
        if style is not None and not isinstance(style, dict):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "style must be an object")
        for nm, v in [("parent_object_id", parent_object_id), ("group_id", group_id)]:
            if v is not None:
                if not isinstance(v, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", v):
                    _log("error", error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"{nm} is malformed")

        for k in ("x", "y"):
            if k in geometry and geometry[k] is not None:
                val = geometry[k]
                if not isinstance(val, (int, float)) or not math.isfinite(float(val)):
                    _log("error", error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number")

        boards = _load("boards.json")
        if not isinstance(boards, list): boards = []
        board = next((b for b in boards if b.get("id") == board_id), None)
        if not board or board.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Board not found")

        objs = _load("board_objects.json")
        if not isinstance(objs, list): objs = []
        id_to_obj = {o.get("id"): o for o in objs if o.get("board_id") == board_id}

        if parent_object_id is not None:
            parent = id_to_obj.get(parent_object_id)
            if not parent or parent.get("status") == "deleted":
                _log("error", error_code="NOT_FOUND")
                return _err("NOT_FOUND", "parent_object_id does not exist on this board")
            if parent.get("object_type") not in ("item_frame",):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "parent_object_id does not refer to a valid container object")

        if group_id is not None:
            grp = id_to_obj.get(group_id)
            if not grp or grp.get("status") == "deleted":
                _log("error", error_code="NOT_FOUND")
                return _err("NOT_FOUND", "group_id does not exist on this board")
            if grp.get("object_type") != "group":
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "group_id must refer to an object of type 'group'")

        # create object
        existing_ids = {o.get("id") for o in objs}
        new_id = _gen_id("mir_obj_")
        while new_id in existing_ids:
            new_id = _gen_id("mir_obj_")

        # external_miro_object_id must be unique within board if set; here we generate a provider-like id
        existing_ext = {(o.get("external_miro_object_id"), o.get("board_id")) for o in objs if o.get("external_miro_object_id")}
        new_ext = _gen_id("ext_obj_")
        while (new_ext, board_id) in existing_ext:
            new_ext = _gen_id("ext_obj_")

        row = {
            "id": new_id,
            "external_miro_object_id": new_ext,
            "board_id": board_id,
            "object_type": "item_embed",
            "status": "active",
            "parent_object_id": parent_object_id,
            "group_id": group_id,
            "title": title,
            "text_content": None,
            "data": data,
            "style": style,
            "geometry": geometry,
            "connector_from_object_id": None,
            "connector_to_object_id": None,
            "image_source_url": None,
            "image_asset_ref": None,
            "created_by_user_id": None,
            "created_at": now,
            "updated_at": now,
        }

        objs.append(row)
        _save("board_objects.json", objs)

        _log("ok")
        return {"embed_item": row}
    except Exception as e:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

