def update_embed_item(board_id, embed_item_id, title=None, data=None, style=None, geometry=None, parent_object_id=None, group_id=None, **_extra):
    import json, os, datetime, re, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    BRD_RE = re.compile(r"^mir_brd_[0-9A-Z]{18,}$")
    OBJ_RE = re.compile(r"^mir_obj_[0-9A-Z]{18,}$")

    def _is_finite_number(v):
        try:
            if isinstance(v, bool):
                return False
            if isinstance(v, (int, float)):
                return math.isfinite(float(v))
            return False
        except Exception:
            return False

    def _validate_geometry(g):
        if g is None:
            return None
        if not isinstance(g, dict):
            return "geometry must be an object"
        if "x" in g and g["x"] is not None and not _is_finite_number(g["x"]):
            return "geometry.x must be a finite number"
        if "y" in g and g["y"] is not None and not _is_finite_number(g["y"]):
            return "geometry.y must be a finite number"
        return None

    def _can_container_be_parent(obj_row):
        return obj_row.get("object_type") in ("item_frame",)

    def _log(endpoint, status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    endpoint = "update-embed-item"

    if not isinstance(board_id, str) or not BRD_RE.match(board_id):
        res = _err("VALIDATION_ERROR", "board_id is malformed", field="board_id")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    if not isinstance(embed_item_id, str) or not OBJ_RE.match(embed_item_id):
        res = _err("VALIDATION_ERROR", "embed_item_id is malformed", field="embed_item_id")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res

    if title is not None and not isinstance(title, str):
        res = _err("VALIDATION_ERROR", "title must be a string", field="title")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    if data is not None and not isinstance(data, dict):
        res = _err("VALIDATION_ERROR", "data must be an object", field="data")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    if style is not None and not isinstance(style, dict):
        res = _err("VALIDATION_ERROR", "style must be an object", field="style")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res
    geo_err = _validate_geometry(geometry)
    if geo_err:
        res = _err("VALIDATION_ERROR", geo_err, field="geometry")
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
        except Exception: pass
        return res

    if parent_object_id is not None:
        if not isinstance(parent_object_id, str) or not OBJ_RE.match(parent_object_id):
            res = _err("VALIDATION_ERROR", "parent_object_id is malformed", field="parent_object_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
            except Exception: pass
            return res
    if group_id is not None:
        if not isinstance(group_id, str) or not OBJ_RE.match(group_id):
            res = _err("VALIDATION_ERROR", "group_id is malformed", field="group_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"]})
            except Exception: pass
            return res

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        res = _err("NOT_FOUND", "Board not found", board_id=board_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []
    obj = next((o for o in objs if o.get("id") == embed_item_id and o.get("board_id") == board_id), None)
    if not obj:
        res = _err("NOT_FOUND", "Embed item not found on this board", board_id=board_id, embed_item_id=embed_item_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    if obj.get("object_type") != "item_embed":
        res = _err("VALIDATION_ERROR", "Object is not an embed item", embed_item_id=embed_item_id, object_type=obj.get("object_type"))
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    if obj.get("status") == "deleted":
        res = _err("NOT_FOUND", "Embed item not found (deleted)", board_id=board_id, embed_item_id=embed_item_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []
    allowed_roles = {"owner", "editor"}
    has_access = any(
        m.get("board_id") == board_id and m.get("status") == "active" and m.get("role") in allowed_roles
        for m in memberships
    )
    if not has_access:
        res = _err("UNAUTHORIZED", "Not permitted to edit this board/item", board_id=board_id)
        try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
        except Exception: pass
        return res

    id_to_obj = {o.get("id"): o for o in objs if o.get("board_id") == board_id}

    if parent_object_id is not None:
        if parent_object_id == embed_item_id:
            res = _err("CONFLICT", "parent_object_id cannot be the item itself", field="parent_object_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        parent = id_to_obj.get(parent_object_id)
        if not parent or parent.get("status") == "deleted":
            res = _err("NOT_FOUND", "parent_object_id not found on this board", parent_object_id=parent_object_id)
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        if not _can_container_be_parent(parent):
            res = _err("CONFLICT", "Requested parent cannot contain items", parent_object_id=parent_object_id, parent_object_type=parent.get("object_type"))
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res

    if group_id is not None:
        if group_id == embed_item_id:
            res = _err("CONFLICT", "group_id cannot be the item itself", field="group_id")
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        grp = id_to_obj.get(group_id)
        if not grp or grp.get("status") == "deleted":
            res = _err("NOT_FOUND", "group_id not found on this board", group_id=group_id)
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res
        if grp.get("object_type") != "group":
            res = _err("CONFLICT", "group_id must refer to a group object", group_id=group_id, object_type=grp.get("object_type"))
            try: _log(endpoint, "error", meta={"error_code": res["error"]["code"], "board_id": board_id})
            except Exception: pass
            return res

    changed = False
    for k, v in (("title", title), ("data", data), ("style", style), ("geometry", geometry),
                 ("parent_object_id", parent_object_id), ("group_id", group_id)):
        if v is not None:
            if obj.get(k) != v:
                obj[k] = v
                changed = True

    if not changed:
        try: _log(endpoint, "success", meta={"board_id": board_id, "embed_item_id": embed_item_id, "idempotent": True})
        except Exception: pass
        return {"data": obj, "meta": {"board_id": board_id}}

    obj["updated_at"] = now
    _save("board_objects.json", objs)

    links = _load("object_links.json")
    if isinstance(links, list):
        active_obj_ids = {o.get("id") for o in objs if o.get("board_id") == board_id and o.get("status") != "deleted"}
        new_links = []
        pruned = 0
        for l in links:
            if l.get("board_id") != board_id:
                new_links.append(l)
                continue
            if l.get("from_object_id") in active_obj_ids and l.get("to_object_id") in active_obj_ids:
                new_links.append(l)
            else:
                pruned += 1
        if pruned:
            _save("object_links.json", new_links)

    try: _log(endpoint, "success", meta={"board_id": board_id, "embed_item_id": embed_item_id})
    except Exception: pass
    return {"data": obj, "meta": {"board_id": board_id}}

def delete_embed_item(board_id, embed_item_id, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "delete-embed-item"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is malformed.", field="board_id")
    if not isinstance(embed_item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", embed_item_id):
        _log("error", "VALIDATION_ERROR", {"field": "embed_item_id"})
        return _err("VALIDATION_ERROR", "embed_item_id is malformed.", field="embed_item_id")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_edit = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_edit:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to edit the board.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")
    obj = next((o for o in objs if isinstance(o, dict) and o.get("id") == embed_item_id and o.get("board_id") == board_id), None)
    if not obj or obj.get("status") == "deleted" or obj.get("object_type") != "item_embed":
        _log("error", "NOT_FOUND", {"board_id": board_id, "embed_item_id": embed_item_id})
        return _err("NOT_FOUND", "Embed item not found on this board.", board_id=board_id, embed_item_id=embed_item_id)

    obj["status"] = "deleted"
    obj["updated_at"] = now

    links = _load("object_links.json")
    if isinstance(links, list):
        new_links = []
        changed = False
        for r in links:
            if not isinstance(r, dict):
                new_links.append(r)
                continue
            if r.get("board_id") == board_id and (r.get("from_object_id") == embed_item_id or r.get("to_object_id") == embed_item_id):
                changed = True
                continue
            new_links.append(r)
        if changed:
            _save("object_links.json", new_links)

    _save("board_objects.json", objs)
    _log("success")
    return {"board_id": board_id, "embed_item_id": embed_item_id, "status": "deleted", "deleted": True}

def get_all_tags(board_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        return _err("VALIDATION_ERROR", "Invalid board_id.", field="board_id")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            return _err("VALIDATION_ERROR", "Unsupported status.", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "title"):
        return _err("VALIDATION_ERROR", "Unsupported sort.", field="sort")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Unsupported order.", field="order")

    # Load store
    boards = _load("boards.json")
    board_objects = _load("board_objects.json")
    object_links = _load("object_links.json")

    # Find board
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    # Permission (ambient auth): require at least one non-removed membership exists for this board in store.
    memberships = _load("board_memberships.json")
    accessible = any(m.get("board_id") == board_id and m.get("status") in ("invited", "active") for m in memberships)
    if not accessible:
        # Spec says FORBIDDEN; allowed codes list doesn't include it; map to UNAUTHORIZED as service behaviour.
        return _err("UNAUTHORIZED", "Not authorized to access this board.", board_id=board_id)

    # Enforce "deleted objects excluded unless explicitly requested deleted"; tool supports status filter.
    want_status = status if status is not None else "active"

    # Cursor decode: opaque base64 json {"offset": int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Prepare tag list
    tags = [o for o in board_objects
            if o.get("board_id") == board_id and o.get("object_type") == "tag" and o.get("status") == want_status]

    # If returning active tags, ignore tags that are effectively orphaned by deletion links? Not necessary.
    # But ignore links referencing deleted objects in reads; not used here.

    def _k(v):
        if v is None:
            return ""
        if isinstance(v, str):
            return v.lower()
        return str(v)

    rev = (order == "desc")
    if sort in ("created_at", "updated_at"):
        # ISO timestamps sort lexicographically
        tags.sort(key=lambda x: (_k(x.get(sort)), _k(x.get("id"))), reverse=rev)
    else:
        tags.sort(key=lambda x: (_k(x.get("title")), _k(x.get("id"))), reverse=rev)

    total = len(tags)
    page = tags[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        payload = json.dumps({"offset": offset + limit}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Log call dynamics (enterprise_ops as audit_event surrogate)
    # Determine org if possible via board.organization_id else via team/project parent chain.
    principals = _load("principals.json")
    def _principal(pid):
        return next((p for p in principals if p.get("id") == pid), None)
    org_id = board.get("organization_id")
    if not org_id:
        # Try resolve via team -> organization
        tid = board.get("team_id")
        if tid:
            team = _principal(tid)
            if team and team.get("parent_principal_id"):
                par = _principal(team.get("parent_principal_id"))
                if par and par.get("principal_type") == "organization":
                    org_id = par.get("id")
        # Try via project -> team -> organization
        if not org_id and board.get("project_id"):
            proj = _principal(board.get("project_id"))
            if proj and proj.get("parent_principal_id"):
                team = _principal(proj.get("parent_principal_id"))
                if team and team.get("parent_principal_id"):
                    par = _principal(team.get("parent_principal_id"))
                    if par and par.get("principal_type") == "organization":
                        org_id = par.get("id")
    # If no org in store, pick any organization to satisfy required field (best-effort logging)
    if not org_id:
        org = next((p for p in principals if p.get("principal_type") == "organization" and p.get("status") == "active"), None)
        org_id = org.get("id") if org else None

    enterprise_ops = _load("enterprise_ops.json")
    if org_id:
        rid = "mir_eop_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        latency_ms = int((time.time() - t0) * 1000)
        enterprise_ops.append({
            "id": rid,
            "record_type": "audit_event",
            "organization_id": org_id,
            "board_id": board_id,
            "case_id": None,
            "legal_hold_id": None,
            "object_id": None,
            "status": "immutable",
            "payload": {
                "endpoint": "get-all-tags",
                "board_id": board_id,
                "http_status": 200,
                "latency_ms": latency_ms,
                "filters": {"status": want_status, "sort": sort, "order": order, "limit": limit},
                "cursor_used": bool(cursor)
            },
            "occurred_at": now,
            "expires_at": (datetime.datetime.utcnow() + datetime.timedelta(days=90)).replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": now
        })
        _save("enterprise_ops.json", enterprise_ops)

    return {
        "data": page,
        "pagination": {"limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    }

def update_tag(board_id, tag_id, tag, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        return _err("VALIDATION_ERROR", "Invalid board_id.", field="board_id")
    if not isinstance(tag_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", tag_id):
        return _err("VALIDATION_ERROR", "Invalid tag_id.", field="tag_id")
    if not isinstance(tag, dict):
        return _err("VALIDATION_ERROR", "tag must be an object.", field="tag")
    allowed = {"title", "style", "data"}
    extra = set(tag.keys()) - allowed
    if extra:
        return _err("VALIDATION_ERROR", "Unsupported fields in tag payload.", fields=sorted(extra))
    if "title" in tag and tag["title"] is not None and not isinstance(tag["title"], str):
        return _err("VALIDATION_ERROR", "title must be a string.", field="tag.title")
    if "style" in tag and tag["style"] is not None and not isinstance(tag["style"], dict):
        return _err("VALIDATION_ERROR", "style must be an object.", field="tag.style")
    if "data" in tag and tag["data"] is not None and not isinstance(tag["data"], dict):
        return _err("VALIDATION_ERROR", "data must be an object.", field="tag.data")

    boards = _load("boards.json")
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    accessible = any(m.get("board_id") == board_id and m.get("status") in ("invited", "active") for m in memberships)
    if not accessible:
        return _err("UNAUTHORIZED", "Not authorized to manage tags on this board.", board_id=board_id)

    board_objects = _load("board_objects.json")
    obj_idx = None
    for i, o in enumerate(board_objects):
        if o.get("id") == tag_id and o.get("board_id") == board_id and o.get("object_type") == "tag":
            obj_idx = i
            break
    if obj_idx is None:
        return _err("NOT_FOUND", "Tag not found on this board.", board_id=board_id, tag_id=tag_id)

    obj = board_objects[obj_idx]
    if obj.get("status") == "deleted":
        return _err("CONFLICT", "Cannot update a deleted tag.", tag_id=tag_id)

    # Idempotent: if no fields provided, treat as validation error (real APIs usually require at least one)
    if not tag:
        return _err("VALIDATION_ERROR", "No fields provided to update.", field="tag")

    changed = False
    if "title" in tag and tag["title"] != obj.get("title"):
        obj["title"] = tag["title"]
        changed = True
    if "style" in tag and tag["style"] != obj.get("style"):
        obj["style"] = tag["style"]
        changed = True
    if "data" in tag and tag["data"] != obj.get("data"):
        obj["data"] = tag["data"]
        changed = True

    if not changed:
        # No success without effect: but update endpoints are often idempotent. We'll return the current object.
        # Still write updated_at only if changed.
        pass
    else:
        obj["updated_at"] = now
        board_objects[obj_idx] = obj
        _save("board_objects.json", board_objects)

    # Log audit_event surrogate
    principals = _load("principals.json")
    def _principal(pid):
        return next((p for p in principals if p.get("id") == pid), None)
    org_id = board.get("organization_id")
    if not org_id:
        tid = board.get("team_id")
        if tid:
            team = _principal(tid)
            if team and team.get("parent_principal_id"):
                par = _principal(team.get("parent_principal_id"))
                if par and par.get("principal_type") == "organization":
                    org_id = par.get("id")
    if not org_id:
        org = next((p for p in principals if p.get("principal_type") == "organization" and p.get("status") == "active"), None)
