def delete_tag(board_id, tag_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        return _err("VALIDATION_ERROR", "Invalid board_id.", field="board_id")
    if not isinstance(tag_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", tag_id):
        return _err("VALIDATION_ERROR", "Invalid tag_id.", field="tag_id")

    boards = _load("boards.json")
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    accessible = any(m.get("board_id") == board_id and m.get("status") in ("invited", "active") for m in memberships)
    if not accessible:
        return _err("UNAUTHORIZED", "Not authorized to manage tags on this board.", board_id=board_id)

    board_objects = _load("board_objects.json")
    obj_idx = None
    for i, o in enumerate(board_objects):
        if o.get("id") == tag_id and o.get("board_id") == board_id and o.get("object_type") == "tag":
            obj_idx = i
            break
    if obj_idx is None:
        return _err("NOT_FOUND", "Tag not found on this board.", board_id=board_id, tag_id=tag_id)

    obj = board_objects[obj_idx]
    if obj.get("status") == "deleted":
        # Idempotent delete: treat as conflict? Spec says CONFLICT if cannot be deleted; but soft-deleted is already deleted.
        # Return the existing state as successful effect already applied.
        deleted_obj = obj
    else:
        # Transition active->deleted only
        if obj.get("status") != "active":
            return _err("INVALID_TRANSITION", "Tag cannot be deleted from its current state.", from_status=obj.get("status"), to_status="deleted")
        obj["status"] = "deleted"
        obj["updated_at"] = now
        board_objects[obj_idx] = obj
        _save("board_objects.json", board_objects)
        deleted_obj = obj

        # Remove object_links referencing this tag (rule: referencing deleted objects must be removed or ignored in reads)
        object_links = _load("object_links.json")
        new_links = [l for l in object_links if not (l.get("board_id") == board_id and (l.get("from_object_id") == tag_id or l.get("to_object_id") == tag_id))]
        if len(new_links) != len(object_links):
            _save("object_links.json", new_links)

    # Log audit_event surrogate
    principals = _load("principals.json")
    def _principal(pid):
        return next((p for p in principals if p.get("id") == pid), None)
    org_id = board.get("organization_id")
    if not org_id:
        tid = board.get("team_id")
        if tid:
            team = _principal(tid)
            if team and team.get("parent_principal_id"):
                par = _principal(team.get("parent_principal_id"))
                if par and par.get("principal_type") == "organization":
                    org_id = par.get("id")
    if not org_id:
        org = next((p for p in principals if p.get("principal_type") == "organization" and p.get("status") == "active"), None)
        org_id = org.get("id") if org else None

    enterprise_ops = _load("enterprise_ops.json")
    if org_id:
        rid = "mir_eop_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        latency_ms = int((time.time() - t0) * 1000)
        enterprise_ops.append({
            "id": rid,
            "record_type": "audit_event",
            "organization_id": org_id,
            "board_id": board_id,
            "case_id": None,
            "legal_hold_id": None,
            "object_id": tag_id,
            "status": "immutable",
            "payload": {
                "endpoint": "delete-tag",
                "board_id": board_id,
                "tag_id": tag_id,
                "http_status": 200,
                "latency_ms": latency_ms
            },
            "occurred_at": now,
            "expires_at": (datetime.datetime.utcnow() + datetime.timedelta(days=90)).replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": now
        })
        _save("enterprise_ops.json", enterprise_ops)

    return {"data": {"deleted": True, "tag": deleted_obj}}

def attach_tag(board_id, tag_id, item_id, position_index=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "attach-tag"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "Invalid board_id.", field="board_id")
    for fid, val in (("tag_id", tag_id), ("item_id", item_id)):
        if not isinstance(val, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", val):
            _log("error", "VALIDATION_ERROR", {"field": fid})
            return _err("VALIDATION_ERROR", f"Invalid {fid}.", field=fid)
    if position_index is not None and (not isinstance(position_index, int) or position_index < 0):
        _log("error", "VALIDATION_ERROR", {"field": "position_index"})
        return _err("VALIDATION_ERROR", "position_index must be an integer >= 0.", field="position_index")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    # permissions: must be able to edit items
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_edit = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_edit:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to edit the item.", board_id=board_id)

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")

    tag_obj = next((o for o in objs if isinstance(o, dict) and o.get("id") == tag_id and o.get("board_id") == board_id and o.get("status") == "active"), None)
    if not tag_obj or tag_obj.get("object_type") != "tag":
        _log("error", "NOT_FOUND", {"tag_id": tag_id})
        return _err("NOT_FOUND", "Tag not found on this board.", board_id=board_id, tag_id=tag_id)

    item_obj = next((o for o in objs if isinstance(o, dict) and o.get("id") == item_id and o.get("board_id") == board_id and o.get("status") == "active"), None)
    if not item_obj or not (isinstance(item_obj.get("object_type"), str) and item_obj.get("object_type", "").startswith("item_")):
        _log("error", "NOT_FOUND", {"item_id": item_id})
        return _err("NOT_FOUND", "Item not found on this board.", board_id=board_id, item_id=item_id)

    links = _load("object_links.json")
    if not isinstance(links, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for object_links.")

    # uniqueness: unique(board_id, link_type, from_object_id, to_object_id)
    exists = any(
        isinstance(r, dict)
        and r.get("board_id") == board_id
        and r.get("link_type") == "tag_attachment"
        and r.get("from_object_id") == tag_id
        and r.get("to_object_id") == item_id
        for r in links
    )
    if exists:
        _log("error", "CONFLICT", {"tag_id": tag_id, "item_id": item_id})
        return _err("CONFLICT", "Tag is already attached to this item.", board_id=board_id, tag_id=tag_id, item_id=item_id)

    if position_index is not None and position_index < 0:
        _log("error", "VALIDATION_ERROR", {"field": "position_index"})
        return _err("VALIDATION_ERROR", "position_index must be >= 0.", field="position_index")

    new_id = "mir_lnk_" + uuid.uuid4().hex[:18].upper()
    row = {
        "id": new_id,
        "board_id": board_id,
        "link_type": "tag_attachment",
        "from_object_id": tag_id,
        "to_object_id": item_id,
        "position_index": position_index,
        "created_at": now,
        "updated_at": now,
    }
    links.append(row)
    _save("object_links.json", links)
    _log("success")
    return {"attachment": row}

def detach_tag(board_id, tag_id, item_id, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, credential_id=None, meta=None, started=None):
        # Best-effort request logging if a request log collection exists.
        for fname in ("request_logs.json", "usage.json", "api_requests.json", "audit_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                ended = time.time()
                latency_ms = None
                if started is not None:
                    latency_ms = int(round((ended - started) * 1000))
                row = {
                    "id": "mir_req_" + base64.urlsafe_b64encode(os.urandom(18)).decode("ascii").rstrip("="),
                    "endpoint": endpoint,
                    "status": status,
                    "credential_id": credential_id,
                    "timestamp": _now(),
                    "latency_ms": latency_ms,
                    "meta": meta or {},
                }
                logs.append(row)
                _save(fname, logs)
                break

    started = time.time()
    endpoint = "detach-tag"

    # Validate inputs
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log(endpoint, "error", meta={"field": "board_id"}, started=started)
        return _err("VALIDATION_ERROR", "board_id is malformed", field="board_id")
    if not isinstance(tag_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", tag_id):
        _log(endpoint, "error", meta={"field": "tag_id"}, started=started)
        return _err("VALIDATION_ERROR", "tag_id is malformed", field="tag_id")
    if not isinstance(item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", item_id):
        _log(endpoint, "error", meta={"field": "item_id"}, started=started)
        return _err("VALIDATION_ERROR", "item_id is malformed", field="item_id")

    boards = _load("boards.json")
    objs = _load("board_objects.json")
    links = _load("object_links.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log(endpoint, "error", meta={"reason": "board_not_found"}, started=started)
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # Server-side rule: deleted boards generally not accessible
    if board.get("status") == "deleted":
        _log(endpoint, "error", meta={"reason": "board_deleted"}, started=started)
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    tag = next((o for o in objs if o.get("id") == tag_id and o.get("board_id") == board_id), None)
    if not tag or tag.get("status") == "deleted" or tag.get("object_type") != "tag":
        _log(endpoint, "error", meta={"reason": "tag_not_found"}, started=started)
        return _err("NOT_FOUND", "Tag not found on board", board_id=board_id, tag_id=tag_id)

    item = next((o for o in objs if o.get("id") == item_id and o.get("board_id") == board_id), None)
    if not item or item.get("status") == "deleted" or not (isinstance(item.get("object_type"), str) and item["object_type"].startswith("item_")):
        _log(endpoint, "error", meta={"reason": "item_not_found"}, started=started)
        return _err("NOT_FOUND", "Item not found on board", board_id=board_id, item_id=item_id)

    # Remove link row if exists; uniqueness constraint implies at most one
    idx = None
    for i, l in enumerate(links):
        if (
            l.get("board_id") == board_id
            and l.get("link_type") == "tag_attachment"
            and l.get("from_object_id") == tag_id
            and l.get("to_object_id") == item_id
        ):
            idx = i
            break

    if idx is None:
        _log(endpoint, "error", meta={"reason": "not_attached"}, started=started)
        return _err("CONFLICT", "Tag is not attached to the specified item", board_id=board_id, tag_id=tag_id, item_id=item_id)

    # Delete the attachment
    links.pop(idx)

    # Also remove/ignore any object_links that reference deleted objects in general; enforce cleanup for this mutation
    live_obj_ids = {o.get("id") for o in objs if o.get("board_id") == board_id and o.get("status") != "deleted"}
    cleaned = []
    removed_extra = 0
    for l in links:
        if l.get("board_id") != board_id:
            cleaned.append(l)
            continue
        fo = l.get("from_object_id")
        to = l.get("to_object_id")
        if fo in live_obj_ids and to in live_obj_ids:
            cleaned.append(l)
        else:
            removed_extra += 1
    links = cleaned

    _save("object_links.json", links)

    # Return updated attachment state for that item/tag relationship
    remaining = any(
        l.get("board_id") == board_id
        and l.get("link_type") == "tag_attachment"
        and l.get("from_object_id") == tag_id
        and l.get("to_object_id") == item_id
        for l in links
    )

    resp = {
        "board_id": board_id,
        "tag_id": tag_id,
        "item_id": item_id,
        "attached": bool(remaining),
    }
    _log(endpoint, "ok", meta={"removed_links": 1, "removed_extra_links": removed_extra}, started=started)
    return resp

def get_item_tags(board_id, item_id, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / rate-limit (best-effort, schema not provided) ----
    def _log(status_code, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        # Try common filenames; if none exist, do nothing (no schema declared here).
        candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "api_requests.json"]
        existing = None
        for fn in candidates:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                existing = fn
                break
        if not existing:
            return
        rows = _load(existing)
        row_id = "mir_req_" + hashlib.sha1(f"{now}:{latency_ms}:{board_id}:{item_id}".encode("utf-8")).hexdigest()[:20].upper()
        rows.append({
            "id": row_id,
            "endpoint": "get-item-tags",
            "timestamp": now,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": latency_ms,
            "credential_id": credential_id
        })
        _save(existing, rows)

    # ---- validation ----
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid board_id.")
    if not isinstance(item_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", item_id or ""):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid item_id.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 200.")
    if sort is None:
        sort = "created_at"
    if order is None:
        order = "asc"
    if sort not in ("created_at", "updated_at", "title"):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order not in ("asc", "desc"):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.")

    # cursor: opaque base64url encoding of {"offset": int, "sig": str}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
            if not isinstance(payload, dict) or "offset" not in payload or "sig" not in payload:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if not isinstance(payload["offset"], int) or payload["offset"] < 0:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            # Lightweight integrity check tied to request identity; prevents mixing cursors across different params.
            expected_sig = hashlib.sha256(f"{board_id}:{item_id}:{sort}:{order}".encode("utf-8")).hexdigest()[:16]
            if payload["sig"] != expected_sig:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = payload["offset"]
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    boards = _load("boards.json")
    board_objects = _load("board_objects.json")
    object_links = _load("object_links.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")
    # Deleted boards are not accessible by default (server-side rule)
    if board.get("status") == "deleted":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")

    item = next((o for o in board_objects if o.get("id") == item_id), None)
    if not item or item.get("board_id") != board_id:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Item not found on the specified board.")
    # Must be an item
    ot = item.get("object_type")
    if not (isinstance(ot, str) and ot.startswith("item_")):
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Item not found on the specified board.")
    # Do not surface deleted items
    if item.get("status") != "active":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Item not found on the specified board.")

    # Find tag attachments; ignore links to deleted/missing objects.
    tag_ids = []
    for l in object_links:
        if l.get("board_id") != board_id:
            continue
        if l.get("link_type") != "tag_attachment":
            continue
        if l.get("to_object_id") != item_id:
            continue
        tag_ids.append(l.get("from_object_id"))

    # Resolve tag objects
    tag_set = []
    tag_id_set = set()
    by_id = {o.get("id"): o for o in board_objects if o.get("board_id") == board_id}
    for tid in tag_ids:
        if not tid or tid in tag_id_set:
            continue
        tobj = by_id.get(tid)
        if not tobj:
            continue
        if tobj.get("status") != "active":
            continue
        if tobj.get("object_type") != "tag":
            continue
        tag_set.append(tobj)
        tag_id_set.add(tid)

    def _key(o):
        v = o.get(sort)
        if sort in ("created_at", "updated_at"):
            # ISO8601 string sort works when consistent; handle missing as empty.
            return v or ""
        if sort == "title":
            return (v or "").lower()
        return ""

    reverse = (order == "desc")
    tag_set.sort(key=_key, reverse=reverse)

    total = len(tag_set)
    page = tag_set[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        sig = hashlib.sha256(f"{board_id}:{item_id}:{sort}:{order}".encode("utf-8")).hexdigest()[:16]
        payload = {"offset": offset + limit, "sig": sig}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "data": page,
        "pagination": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "sort": {"field": sort, "order": order}
    }

def get_all_board_members(board_id, role=None, status=None, member_principal_id=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        candidates = ["request_logs.json", "requests.json", "usage.json", "audit.json", "api_requests.json"]
        existing = None
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                existing = fn
                break
        if not existing:
            return
        rows = _load(existing)
        row_id = "mir_req_" + hashlib.sha1(f"{now}:{latency_ms}:{board_id}".encode("utf-8")).hexdigest()[:20].upper()
        rows.append({
            "id": row_id,
            "endpoint": "get-all-board-members",
            "timestamp": now,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": latency_ms,
            "credential_id": credential_id
        })
        _save(existing, rows)

    # ---- validation ----
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid board_id.")

    if role is not None and (not isinstance(role, str) or role not in ("owner", "editor", "commenter", "viewer")):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid role filter.")
    if status is not None and (not isinstance(status, str) or status not in ("invited", "active", "removed")):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if member_principal_id is not None:
        if not isinstance(member_principal_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", member_principal_id or ""):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid member_principal_id filter.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer between 1 and 200.")
    if sort is None:
        sort = "created_at"
    if order is None:
        order = "asc"
    if sort not in ("created_at", "updated_at"):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort.")
    if order not in ("asc", "desc"):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
            if not isinstance(payload, dict) or "offset" not in payload or "sig" not in payload:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if not isinstance(payload["offset"], int) or payload["offset"] < 0:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            expected_sig = hashlib.sha256(
                f"{board_id}:{role}:{status}:{member_principal_id}:{sort}:{order}".encode("utf-8")
            ).hexdigest()[:16]
            if payload["sig"] != expected_sig:
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            offset = payload["offset"]
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    boards = _load("boards.json")
    memberships = _load("board_memberships.json")
    principals = _load("principals.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")
    if board.get("status") == "deleted":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")

    principal_by_id = {p.get("id"): p for p in principals}

    # Server rule: get-all-board-members reads status in ('invited','active') unless explicitly filtered to removed
    def _status_allowed(mstatus):
        if status is not None:
            return mstatus == status
        return mstatus in ("invited", "active")

    rows = []
    for m in memberships:
        if m.get("board_id") != board_id:
            continue
        if role is not None and m.get("role") != role:
            continue
        if not _status_allowed(m.get("status")):
            continue
        if member_principal_id is not None and m.get("member_principal_id") != member_principal_id:
            continue
        # integrity: keep row even if principal missing? Real APIs usually keep; but schema references principal.
        # We'll keep, but include principal if available.
        out = dict(m)
        mp = principal_by_id.get(m.get("member_principal_id"))
        if mp is not None:
            out["member_principal"] = {
                "id": mp.get("id"),
                "principal_type": mp.get("principal_type"),
                "display_name": mp.get("display_name"),
                "email": mp.get("email"),
                "status": mp.get("status")
            }
        rows.append(out)

    def _key(r):
        v = r.get(sort)
        return v or ""

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        sig = hashlib.sha256(
            f"{board_id}:{role}:{status}:{member_principal_id}:{sort}:{order}".encode("utf-8")
        ).hexdigest()[:16]
        payload = {"offset": offset + limit, "sig": sig}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "data": page,
        "pagination": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        },
        "sort": {"field": sort, "order": order},
        "filters": {
            "role": role,
            "status": status,
            "member_principal_id": member_principal_id
        }
    }

def get_specific_board_member(board_id, membership_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_log_collection():
        candidates = [
            ("request_logs.json", "request_logs"),
            ("requests.json", "requests"),
            ("api_requests.json", "api_requests"),
            ("audit.json", "audit"),
            ("usage.json", "usage"),
        ]
        for fn, nm in candidates:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                return fn
        return None

    def _append_log(status, credential_id=None, error_code=None):
        fn = _find_log_collection()
        if not fn:
            return
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get-specific-board-member",
            "status": status,
            "error_code": error_code,
            "credential_id": credential_id,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save(fn, logs)

    def _rate_limited():
        fn = _find_log_collection()
        if not fn:
            return False
        logs = _load(fn)
        if not isinstance(logs, list):
            return False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= 120

    # ---- validate ----
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "board_id is malformed", field="board_id")
    if not isinstance(membership_id, str) or not re.match(r"^mir_bm_[0-9A-Z]{18,}$", membership_id or ""):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "membership_id is malformed", field="membership_id")

    if _rate_limited():
        _append_log("error", error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Too many requests")

    boards = _load("boards.json")
    memberships = _load("board_memberships.json")
    principals = _load("principals.json")

    # ---- locate board ----
    board = None
    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break
    if not board or board.get("status") == "deleted":
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found", board_id=board_id)

    # ---- ambient auth resolution / access check ----
    # Permission rule for this simplified service: must be able to access the board (any invited/active membership).
    has_any_access = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") in ("active", "invited"):
            has_any_access = True
            break
    if not has_any_access:
        _append_log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Not authorized to view board memberships")

    # ---- locate membership ----
    mem = None
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("id") == membership_id and m.get("board_id") == board_id:
            mem = m
            break
    if not mem:
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board membership not found", board_id=board_id, membership_id=membership_id)

    # Enrich with principal details (as many APIs do); do not fabricate if missing.
    principal = None
    pid = mem.get("member_principal_id")
    if isinstance(pid, str):
        for p in principals:
            if isinstance(p, dict) and p.get("id") == pid:
                principal = p
                break

    _append_log("ok")
    return {
        "membership": mem,
        "member_principal": principal,
        "board_id": board_id,
        "membership_id": membership_id,
    }

def remove_board_member(board_id, board_membership_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "remove-board-member",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed board_id.")
    if not isinstance(board_membership_id, str) or not re.match(r"^mir_bm_[0-9A-Z]{18,}$", board_membership_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed board_membership_id.")

    boards = _load("boards.json")
    memberships = _load("board_memberships.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    m = next((x for x in memberships if x.get("id") == board_membership_id and x.get("board_id") == board_id), None)
    if not m:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board membership not found on the specified board.", board_id=board_id, board_membership_id=board_membership_id)

    if m.get("status") == "removed":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Membership is already removed.", board_membership_id=board_membership_id)

    # Ownership constraint: at least one active owner per board
    if m.get("status") == "active" and m.get("role") == "owner":
        active_owners = [
            x for x in memberships
            if x.get("board_id") == board_id and x.get("status") == "active" and x.get("role") == "owner" and x.get("id") != board_membership_id
        ]
        if len(active_owners) == 0:
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Cannot remove the last remaining active owner of the board.", board_id=board_id)

    # Transition invited->removed OR active->removed allowed; removed->* not allowed
    if m.get("status") not in ("invited", "active"):
        _log("error", error_code="INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition membership status from '{m.get('status')}' to 'removed'.")

    m["status"] = "removed"
    m["updated_at"] = now
    _save("board_memberships.json", memberships)

    _log("ok")
    return {"board_membership": m}

def share_board(board_id, member_principal_id, role, team_assignment_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "share-board",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed board_id.")
    if not isinstance(member_principal_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", member_principal_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed member_principal_id.")
    if role not in ("owner", "editor", "commenter", "viewer"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid role.", allowed_roles=["owner", "editor", "commenter", "viewer"])
    if team_assignment_id is not None:
        if not isinstance(team_assignment_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", team_assignment_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed team_assignment_id.")

    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    member = next((p for p in principals if p.get("id") == member_principal_id), None)
    if not member:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Member principal not found.", member_principal_id=member_principal_id)

    if team_assignment_id is not None:
        team = next((p for p in principals if p.get("id") == team_assignment_id), None)
        if not team:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "team_assignment_id principal not found.", team_assignment_id=team_assignment_id)
        if team.get("principal_type") != "team":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "team_assignment_id must refer to a team principal.", team_assignment_id=team_assignment_id)
        # If board is in an organization, team must be under that organization (directly or via ancestors).
        org_id = board.get("organization_id")
        if org_id:
            # Walk up team parents to see if org_id is an ancestor.
            parent_map = {p.get("id"): p.get("parent_principal_id") for p in principals}
            cur = team.get("id")
            ok = False
            seen = set()
            while cur and cur not in seen:
                seen.add(cur)
                if cur == org_id:
                    ok = True
                    break
                cur = parent_map.get(cur)
            if not ok:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "team_assignment_id must be under the board's organization.", organization_id=org_id, team_assignment_id=team_assignment_id)

    # Find existing non-removed membership (unique constraint where status != removed)
    existing = next((m for m in memberships if m.get("board_id") == board_id and m.get("member_principal_id") == member_principal_id and m.get("status") != "removed"), None)

    def _count_active_owners(exclude_id=None):
        return sum(
            1 for x in memberships
            if x.get("board_id") == board_id and x.get("status") == "active" and x.get("role") == "owner" and x.get("id") != exclude_id
        )

    if existing:
        # Update membership. If active, allow role changes; if invited, allow role changes too.
        # Cannot downgrade last active owner.
        if existing.get("status") == "active" and existing.get("role") == "owner" and role != "owner":
            if _count_active_owners(exclude_id=existing.get("id")) == 0:
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "Cannot downgrade the last remaining active owner.", board_id=board_id)

        existing["role"] = role
        if team_assignment_id is not None:
            existing["team_assignment_id"] = team_assignment_id
        else:
            # leaving it unchanged matches typical share behavior; do not null it unless explicitly provided
            pass

        # Share-board may activate immediately; if previously invited, keep invited (invite flow) by default.
        # We don't have invite-flow param; preserve existing status unless it's removed (filtered out) or invalid.
        if existing.get("status") not in ("invited", "active"):
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot share-board against membership with status '{existing.get('status')}'.")

        existing["updated_at"] = now
        _save("board_memberships.json", memberships)
        _log("ok")
        return {"board_membership": existing}

    # Create new membership. Default invite flow => invited.
    # Ensure not violating unique constraint with removed rows: allowed to create new even if a removed history row exists.
