def update_board_member(board_id, board_membership_id, role=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "update-board-member",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed board_id.")
    if not isinstance(board_membership_id, str) or not re.match(r"^mir_bm_[0-9A-Z]{18,}$", board_membership_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed board_membership_id.")
    if role is not None and role not in ("owner", "editor", "commenter", "viewer"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid role.", allowed_roles=["owner", "editor", "commenter", "viewer"])
    if status is not None and status not in ("invited", "active", "removed"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", allowed_statuses=["invited", "active", "removed"])
    if role is None and status is None:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one of role or status must be provided.")

    boards = _load("boards.json")
    memberships = _load("board_memberships.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    m = next((x for x in memberships if x.get("id") == board_membership_id and x.get("board_id") == board_id), None)
    if not m:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board membership not found on the specified board.", board_id=board_id, board_membership_id=board_membership_id)

    def _count_active_owners(exclude_id=None):
        return sum(
            1 for x in memberships
            if x.get("board_id") == board_id and x.get("status") == "active" and x.get("role") == "owner" and x.get("id") != exclude_id
        )

    # Role changes only allowed when membership status='active'
    if role is not None and m.get("status") != "active":
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Role can only be changed when membership status is 'active'.", current_status=m.get("status"))

    # Prevent downgrading last active owner
    if role is not None:
        if m.get("status") == "active" and m.get("role") == "owner" and role != "owner":
            if _count_active_owners(exclude_id=m.get("id")) == 0:
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "Cannot downgrade the last remaining active owner.", board_id=board_id)

    # Status transitions must follow lifecycle rules
    if status is not None:
        cur = m.get("status")
        allowed = {"invited": ["active", "removed"], "active": ["removed"], "removed": []}.get(cur, [])
        if status != cur and status not in allowed:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition membership status from '{cur}' to '{status}'.")

        # Prevent removing last active owner
        if status == "removed" and cur == "active" and m.get("role") == "owner":
            if _count_active_owners(exclude_id=m.get("id")) == 0:
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "Cannot remove the last remaining active owner.", board_id=board_id)

    # Apply updates
    if role is not None:
        m["role"] = role
    if status is not None:
        m["status"] = status
    m["updated_at"] = now

    _save("board_memberships.json", memberships)
    _log("ok")
    return {"board_membership": m}

def create_group(board_id, title=None, geometry=None, style=None, item_ids=None, **_extra):
    import json, os, datetime, re, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "create-group",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed board_id.")
    if title is not None and not isinstance(title, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a string when provided.")
    if geometry is not None and not isinstance(geometry, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "geometry must be an object when provided.")
    if style is not None and not isinstance(style, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "style must be an object when provided.")
    if item_ids is not None:
        if not isinstance(item_ids, list):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "item_ids must be an array when provided.")
        for i, oid in enumerate(item_ids):
            if not isinstance(oid, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", oid):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Malformed item_ids[{i}].")

    # Basic geometry finite checks if x/y present
    def _is_finite_number(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(float(v))

    if isinstance(geometry, dict):
        for k in ("x", "y"):
            if k in geometry and geometry[k] is not None and not _is_finite_number(geometry[k]):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number when provided.")

    boards = _load("boards.json")
    objects = _load("board_objects.json")
    links = _load("object_links.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    # Validate referenced items exist on board and are active and item_*
    items = []
    if item_ids:
        obj_map = {o.get("id"): o for o in objects}
        for oid in item_ids:
            o = obj_map.get(oid)
            if not o or o.get("board_id") != board_id:
                _log("error", error_code="NOT_FOUND")
                return _err("NOT_FOUND", "Referenced item not found on board.", board_id=board_id, object_id=oid)
            if o.get("status") != "active":
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "Referenced item is not active.", object_id=oid, status=o.get("status"))
            ot = o.get("object_type") or ""
            if not ot.startswith("item_"):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Only item_* objects can be added to a group.", object_id=oid, object_type=ot)
            items.append(o)

    # Create group object
    new_id = f"mir_obj_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{int(time.time()*1000)%1000:03d}G"
    existing_ids = {o.get("id") for o in objects}
    seq = 0
    while new_id in existing_ids:
        seq += 1
        new_id = f"mir_obj_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{int(time.time()*1000)%1000:03d}{seq:02d}G"

    group_obj = {
        "id": new_id,
        "external_miro_object_id": None,
        "board_id": board_id,
        "object_type": "group",
        "status": "active",
        "parent_object_id": None,
        "group_id": None,
        "title": title,
        "text_content": None,
        "data": None,
        "style": style,
        "geometry": geometry,
        "connector_from_object_id": None,
        "connector_to_object_id": None,
        "image_source_url": None,
        "image_asset_ref": None,
        "created_by_user_id": None,
        "created_at": now,
        "updated_at": now,
    }

    # Replace group membership links for this group with the provided set (initial set)
    # Ensure uniqueness and integrity: from=group, to=item_*
    new_links = []
    if item_ids:
        # de-dup item_ids preserving order
        seen = set()
        dedup = []
        for oid in item_ids:
            if oid not in seen:
                seen.add(oid)
                dedup.append(oid)

        # Must not create duplicate links that already exist (shouldn't, group is new), but enforce anyway.
        existing_key = {(l.get("board_id"), l.get("link_type"), l.get("from_object_id"), l.get("to_object_id")) for l in links}
        for idx, oid in enumerate(dedup):
            key = (board_id, "group_membership", new_id, oid)
            if key in existing_key:
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "Duplicate group membership link.", from_object_id=new_id, to_object_id=oid)

            link_id = f"mir_lnk_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{int(time.time()*1000)%1000:03d}{idx:02d}"
            new_links.append({
                "id": link_id,
                "board_id": board_id,
                "link_type": "group_membership",
                "from_object_id": new_id,
                "to_object_id": oid,
                "position_index": idx,
                "created_at": now,
                "updated_at": now,
            })

    objects.append(group_obj)
    links.extend(new_links)
    _save("board_objects.json", objects)
    _save("object_links.json", links)

    _log("ok")
    return {"group": group_obj, "memberships_created": len(new_links)}

def get_all_groups(board_id, limit=None, cursor=None, status=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, message=None, **extra):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}|get-all-groups".encode()).hexdigest()[:24],
            "endpoint": "get-all-groups",
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_limits.json")
        # default: 120 req/min across service
        limit_per_min = 120
        if isinstance(cfg, dict):
            limit_per_min = int(cfg.get("requests_per_minute", limit_per_min) or limit_per_min)
        elif isinstance(cfg, list) and cfg:
            try:
                limit_per_min = int(cfg[0].get("requests_per_minute", limit_per_min) or limit_per_min)
            except Exception:
                pass

        logs = _load("request_logs.json")
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts >= cutoff:
                recent += 1
        if recent >= limit_per_min:
            _log("RATE_LIMIT", "Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        return rl

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("VALIDATION_ERROR", "Malformed board_id")
        return _err("VALIDATION_ERROR", "Malformed board_id")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "Invalid limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "Invalid cursor")
        return _err("VALIDATION_ERROR", "Invalid cursor")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log("VALIDATION_ERROR", "Unsupported status")
            return _err("VALIDATION_ERROR", "Unsupported status")

    boards = _load("boards.json")
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("NOT_FOUND", "Board not found")
        return _err("NOT_FOUND", "Board not found")

    # Ambient auth: if any principal has membership to the board (invited/active) OR created it, allow.
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    has_access = False
    member_ids = set()
    for m in memberships:
        if m.get("board_id") == board_id and m.get("status") in ("invited", "active"):
            member_ids.add(m.get("member_principal_id"))
    if member_ids:
        for pid in member_ids:
            p = next((x for x in principals if x.get("id") == pid), None)
            if p and p.get("status") == "active":
                has_access = True
                break
    if not has_access:
        cby = board.get("created_by_user_id")
        if isinstance(cby, str):
            p = next((x for x in principals if x.get("id") == cby and x.get("status") == "active"), None)
            if p:
                has_access = True
    if not has_access:
        _log("UNAUTHORIZED", "Forbidden")
        return _err("UNAUTHORIZED", "Forbidden")

    objs = _load("board_objects.json")
    groups = []
    for o in objs:
        if o.get("board_id") != board_id:
            continue
        if o.get("object_type") != "group":
            continue
        if status is not None and o.get("status") != status:
            continue
        groups.append(o)

    # stable ordering by created_at then id
    def _k(x):
        return (x.get("created_at") or "", x.get("id") or "")
    groups.sort(key=_k)

    start = 0
    if cursor:
        # cursor: base64url("start:<int>")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("start:"):
                _log("VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(groups)
    page = groups[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = base64.urlsafe_b64encode(f"start:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": bool(next_cursor),
            "next_cursor": next_cursor
        }
    }
    _log("OK")
    return resp

