            "id": "req_" + hashlib.sha256(f"{time.time_ns()}|get-group-items".encode()).hexdigest()[:24],
            "endpoint": "get-group-items",
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_limits.json")
        limit_per_min = 120
        if isinstance(cfg, dict):
            limit_per_min = int(cfg.get("requests_per_minute", limit_per_min) or limit_per_min)
        elif isinstance(cfg, list) and cfg:
            try:
                limit_per_min = int(cfg[0].get("requests_per_minute", limit_per_min) or limit_per_min)
            except Exception:
                pass
        logs = _load("request_logs.json")
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts >= cutoff:
                recent += 1
        if recent >= limit_per_min:
            _log("RATE_LIMIT", "Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        return rl

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("VALIDATION_ERROR", "Malformed board_id")
        return _err("VALIDATION_ERROR", "Malformed board_id")
    if not isinstance(group_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
        _log("VALIDATION_ERROR", "Malformed group_id")
        return _err("VALIDATION_ERROR", "Malformed group_id")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log("VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "Invalid limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "Invalid cursor")
        return _err("VALIDATION_ERROR", "Invalid cursor")

    boards = _load("boards.json")
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("NOT_FOUND", "Board not found")
        return _err("NOT_FOUND", "Board not found")

    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    has_access = False
    member_ids = set()
    for m in memberships:
        if m.get("board_id") == board_id and m.get("status") in ("invited", "active"):
            member_ids.add(m.get("member_principal_id"))
    if member_ids:
        for pid in member_ids:
            p = next((x for x in principals if x.get("id") == pid), None)
            if p and p.get("status") == "active":
                has_access = True
                break
    if not has_access:
        cby = board.get("created_by_user_id")
        if isinstance(cby, str):
            p = next((x for x in principals if x.get("id") == cby and x.get("status") == "active"), None)
            if p:
                has_access = True
    if not has_access:
        _log("UNAUTHORIZED", "Forbidden")
        return _err("UNAUTHORIZED", "Forbidden")

    objs = _load("board_objects.json")
    group_obj = next((o for o in objs if o.get("id") == group_id and o.get("board_id") == board_id and o.get("object_type") == "group"), None)
    if not group_obj:
        _log("NOT_FOUND", "Group not found")
        return _err("NOT_FOUND", "Group not found")

    links = _load("object_links.json")
    # collect group membership links
    members = []
    # index objects by id
    obj_by_id = {o.get("id"): o for o in objs if o.get("board_id") == board_id}
    # stable ordering by position_index then created_at then id
    group_links = []
    for l in links:
        if l.get("board_id") != board_id:
            continue
        if l.get("link_type") != "group_membership":
            continue
        if l.get("from_object_id") != group_id:
            continue
        to_id = l.get("to_object_id")
        o = obj_by_id.get(to_id)
        # Ignore missing/deleted objects in reads per rules.
        if not o:
            continue
        if o.get("status") != "active":
            continue
        ot = o.get("object_type")
        if not (isinstance(ot, str) and ot.startswith("item_")):
            continue
        group_links.append((l, o))

    def _lk(pair):
        l, o = pair
        pi = l.get("position_index")
        if not isinstance(pi, int) or pi < 0:
            pi = 10**9
        return (pi, l.get("created_at") or "", o.get("created_at") or "", o.get("id") or "")
    group_links.sort(key=_lk)
    members = [o for (_, o) in group_links]

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("start:"):
                _log("VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError()
        except Exception:
            _log("VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(members)
    page = members[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = base64.urlsafe_b64encode(f"start:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log("OK")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": bool(next_cursor),
            "next_cursor": next_cursor
        }
    }

def update_group(board_id, group_id, title=None, geometry=None, style=None, item_ids=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_code, message=None, **extra):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}|update-group".encode()).hexdigest()[:24],
            "endpoint": "update-group",
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        cfg = _load("service_limits.json")
        limit_per_min = 120
        if isinstance(cfg, dict):
            limit_per_min = int(cfg.get("requests_per_minute", limit_per_min) or limit_per_min)
        elif isinstance(cfg, list) and cfg:
            try:
                limit_per_min = int(cfg[0].get("requests_per_minute", limit_per_min) or limit_per_min)
            except Exception:
                pass
        logs = _load("request_logs.json")
        cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        recent = 0
        for r in logs:
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts >= cutoff:
                recent += 1
        if recent >= limit_per_min:
            _log("RATE_LIMIT", "Rate limit exceeded")
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        return rl

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("VALIDATION_ERROR", "Malformed board_id")
        return _err("VALIDATION_ERROR", "Malformed board_id")
    if not isinstance(group_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
        _log("VALIDATION_ERROR", "Malformed group_id")
        return _err("VALIDATION_ERROR", "Malformed group_id")
    if title is not None and not isinstance(title, str):
        _log("VALIDATION_ERROR", "Invalid title")
        return _err("VALIDATION_ERROR", "Invalid title")
    if geometry is not None and not isinstance(geometry, dict):
        _log("VALIDATION_ERROR", "Malformed geometry")
        return _err("VALIDATION_ERROR", "Malformed geometry")
    if style is not None and not isinstance(style, dict):
        _log("VALIDATION_ERROR", "Malformed style")
        return _err("VALIDATION_ERROR", "Malformed style")
    if item_ids is not None:
        if not isinstance(item_ids, list):
            _log("VALIDATION_ERROR", "item_ids must be an array")
            return _err("VALIDATION_ERROR", "item_ids must be an array")
        for iid in item_ids:
            if not isinstance(iid, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", iid):
                _log("VALIDATION_ERROR", "Invalid item_ids")
                return _err("VALIDATION_ERROR", "Invalid item_ids")

    boards = _load("boards.json")
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log("NOT_FOUND", "Board not found")
        return _err("NOT_FOUND", "Board not found")

    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    # For mutation, require at least one active membership (editor/owner) exists in store; otherwise unauthorized.
    # Ambient auth can't identify caller; we therefore only deny when *no* valid editor/owner membership exists.
    can_edit = False
    for m in memberships:
        if m.get("board_id") != board_id:
            continue
        if m.get("status") != "active":
            continue
        if m.get("role") not in ("owner", "editor"):
            continue
        pid = m.get("member_principal_id")
        p = next((x for x in principals if x.get("id") == pid), None)
        if p and p.get("status") == "active":
            can_edit = True
            break
    if not can_edit:
        # allow creator as fallback
        cby = board.get("created_by_user_id")
        if isinstance(cby, str):
            p = next((x for x in principals if x.get("id") == cby and x.get("status") == "active"), None)
            if p:
                can_edit = True
    if not can_edit:
        _log("UNAUTHORIZED", "Forbidden")
        return _err("UNAUTHORIZED", "Forbidden")

    objs = _load("board_objects.json")
    idx = None
    group_obj = None
    for i, o in enumerate(objs):
        if o.get("id") == group_id and o.get("board_id") == board_id and o.get("object_type") == "group":
            idx = i
            group_obj = o
            break
    if not group_obj:
        _log("NOT_FOUND", "Group not found")
        return _err("NOT_FOUND", "Group not found")

    # Validate and stage membership replacement if provided.
    links = _load("object_links.json")
    obj_by_id = {o.get("id"): o for o in objs if o.get("board_id") == board_id}

    staged_links = None
    if item_ids is not None:
        # Ensure all ids exist and are active items on same board (conflict if not on board/type mismatch)
        missing_or_wrong = []
        for iid in item_ids:
            o = obj_by_id.get(iid)
            if not o:
                missing_or_wrong.append(iid)
                continue
            if o.get("status") != "active":
                missing_or_wrong.append(iid)
                continue
            ot = o.get("object_type")
            if not (isinstance(ot, str) and ot.startswith("item_")):
                missing_or_wrong.append(iid)
        if missing_or_wrong:
            _log("CONFLICT", "Some item_ids are not active items on the board", item_ids=missing_or_wrong)
            return _err("CONFLICT", "Some item_ids are not active items on the board", item_ids=missing_or_wrong)

        # Replace links for this group.
        keep = []
        for l in links:
            if l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("from_object_id") == group_id:
                continue
            keep.append(l)

        # Build new set with uniqueness (board_id, link_type, from_object_id, to_object_id)
        seen = set()
        for l in keep:
            k = (l.get("board_id"), l.get("link_type"), l.get("from_object_id"), l.get("to_object_id"))
            seen.add(k)

        created = []
        for pos, iid in enumerate(item_ids):
            k = (board_id, "group_membership", group_id, iid)
            if k in seen:
                # idempotent: if already exists, leave existing (but we removed prior group links above),
                # so duplicates in input should be validation error rather than silently coalesce.
                _log("VALIDATION_ERROR", "Duplicate item_ids")
                return _err("VALIDATION_ERROR", "Duplicate item_ids")
            seen.add(k)
            created.append({
                "id": "lnk_" + hashlib.sha256(f"{time.time_ns()}|{board_id}|{group_id}|{iid}|{pos}".encode()).hexdigest()[:24],
                "board_id": board_id,
                "link_type": "group_membership",
                "from_object_id": group_id,
                "to_object_id": iid,
                "position_index": pos,
                "created_at": now,
                "updated_at": now
            })
        staged_links = keep + created

    mutated = False
    group_new = dict(group_obj)

    if title is not None:
        group_new["title"] = title
        mutated = True
    if geometry is not None:
        group_new["geometry"] = geometry
        mutated = True
    if style is not None:
        group_new["style"] = style
        mutated = True
    if staged_links is not None:
        mutated = True

    if not mutated:
        # no effect -> return current state (read-like but this is update endpoint; still OK with no mutation?)
        # Enforce "no success without effect" for mutations: if nothing to change, treat as idempotent success
        # only if membership list exactly matches current, and title/geometry/style omitted.
        _log("OK", "No changes")
        return {"data": group_obj}

    group_new["updated_at"] = now
    objs[idx] = group_new

    # Persist atomically-ish: save objects then links; both are required to reflect update.
    _save("board_objects.json", objs)
    if staged_links is not None:
        _save("object_links.json", staged_links)

    _log("OK")
    return {"data": group_new}

def ungroup_items(board_id, group_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- Usage / rate limit (best-effort, only if request_logs exists) ----
    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": f"mir_req_{int(time.time()*1000)}",
                "endpoint": "ungroup-items",
                "timestamp": now,
                "status": status,
                "error_code": error_code,
                "credential_id": credential_id,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                c += 1
        if c >= 120:
            return _err("RATE_LIMIT", "Too many requests. Please retry later.")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("rejected", error_code="RATE_LIMIT")
        return rl

    # ---- Validate inputs ----
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("rejected", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid board_id format.", field="board_id")
    if not isinstance(group_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
        _log("rejected", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid group_id format.", field="group_id")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Datastore corrupted: boards collection is not a list.")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("not_found", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    objects = _load("board_objects.json")
    if not isinstance(objects, list):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Datastore corrupted: board_objects collection is not a list.")

    group_obj = next((o for o in objects if o.get("id") == group_id and o.get("board_id") == board_id), None)
    if not group_obj:
        _log("not_found", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Group not found on this board.", board_id=board_id, group_id=group_id)
    if group_obj.get("object_type") != "group":
        _log("not_found", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "group_id is not a group object on this board.", board_id=board_id, group_id=group_id)
    if group_obj.get("status") != "active":
        _log("rejected", error_code="CONFLICT")
        return _err("CONFLICT", "Group cannot be ungrouped in its current state.", status=group_obj.get("status"))

    links = _load("object_links.json")
    if not isinstance(links, list):
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Datastore corrupted: object_links collection is not a list.")

    # Find group memberships
    group_membership_links = [
        l for l in links
        if l.get("board_id") == board_id
        and l.get("link_type") == "group_membership"
        and l.get("from_object_id") == group_id
    ]

    # If there are no membership links, still proceed: group removal is an effect.
    # But if the group is referenced as group_id by items, we will clear that too.
    object_index = {o.get("id"): o for o in objects if isinstance(o, dict)}
    member_item_ids = []
    for l in group_membership_links:
        to_id = l.get("to_object_id")
        if isinstance(to_id, str):
            obj = object_index.get(to_id)
            if obj and obj.get("board_id") == board_id and isinstance(obj.get("object_type"), str) and obj.get("object_type", "").startswith("item_"):
                if obj.get("status") == "active":
                    member_item_ids.append(to_id)

    # ---- Mutations: remove group links, clear items.group_id, delete the group object (soft delete) ----
    changed = False

    if group_membership_links:
        before = len(links)
        links = [l for l in links if not (l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("from_object_id") == group_id)]
        if len(links) != before:
            changed = True

    # Clear group_id pointer on any object on this board referencing this group (even if link rows absent)
    for o in objects:
        if o.get("board_id") == board_id and o.get("group_id") == group_id and o.get("status") == "active":
            o["group_id"] = None
            o["updated_at"] = now
            changed = True

    # Also clear parent_object_id if the group was used as parent (defensive integrity)
    for o in objects:
        if o.get("board_id") == board_id and o.get("parent_object_id") == group_id and o.get("status") == "active":
            o["parent_object_id"] = None
            o["updated_at"] = now
            changed = True

    # Soft-delete group object (board_objects lifecycle active->deleted)
    group_obj["status"] = "deleted"
    group_obj["updated_at"] = now
    changed = True

    # Remove any object_links that reference the deleted group (from or to), to satisfy rule
    before_links = len(links)
    links = [l for l in links if not (l.get("board_id") == board_id and (l.get("from_object_id") == group_id or l.get("to_object_id") == group_id))]
    if len(links) != before_links:
        changed = True

    if not changed:
        # Should never happen given we delete the group, but keep contract: no success without effect.
        _log("not_found", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Nothing to ungroup (no matching active group state).", board_id=board_id, group_id=group_id)

    _save("board_objects.json", objects)
    _save("object_links.json", links)

    # Return ungrouped result: group removed + remaining member items
    remaining_items = []
    for oid in member_item_ids:
        o = object_index.get(oid)
        # object_index points to same dict mutated above; ensure still active
        if o and o.get("status") == "active":
            remaining_items.append(o)

    resp = {
        "board_id": board_id,
        "group_id": group_id,
        "removed_group": {
            "id": group_obj.get("id"),
            "status": group_obj.get("status"),
            "updated_at": group_obj.get("updated_at")
        },
        "ungrouped_items": remaining_items,
        "ungrouped_item_count": len(remaining_items)
    }

    _log("ok")
    return resp

def delete_group(board_id, group_id, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- usage / rate limit logging (if collection exists) ----
    def _log(status_code, credential_id=None, extra=None):
        extra = extra or {}
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                latency_ms = int(round((time.time() - t0) * 1000))
                logs.append({
                    "id": "mir_req_" + uuid.uuid4().hex[:26].upper(),
                    "endpoint": "delete-group",
                    "credential_id": credential_id,
                    "status": status_code,
                    "latency_ms": latency_ms,
                    "timestamp": now,
                    "request": {"board_id": board_id, "group_id": group_id},
                    **({"meta": extra} if extra else {})
                })
                _save(fname, logs)
                break

    def _rate_limited():
        # Default: 120 requests/minute across all callers (since auth is ambient).
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs[::-1]:
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt < cutoff:
                        break
                    cnt += 1
                return cnt >= 120
        return False

    if _rate_limited():
        _log("RATE_LIMIT", extra={"window_s": 60, "limit": 120})
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # ---- validate inputs ----
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid board_id.", field="board_id")
    if not isinstance(group_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", group_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid group_id.", field="group_id")

    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")
    objects = _load("board_objects.json")
    links = _load("object_links.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Board not found.")

    # ---- ambient auth: must find some active membership with edit permission ----
    # Choose any active membership on this board with role owner/editor.
    editable_roles = {"owner", "editor"}
    actor_membership = None
    for m in memberships:
        if m.get("board_id") == board_id and m.get("status") == "active" and m.get("role") in editable_roles:
            # ensure principal exists and is active user/team/etc
            p = next((pp for pp in principals if pp.get("id") == m.get("member_principal_id")), None)
            if p and p.get("status") == "active":
                actor_membership = m
                break
    if not actor_membership:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You lack permission to edit board content.")

    grp = next((o for o in objects if o.get("id") == group_id and o.get("board_id") == board_id), None)
    if not grp:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Group not found on this board.")

    if grp.get("object_type") != "group":
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "The specified object is not a group.", field="group_id")

    if grp.get("status") == "deleted":
        _log("CONFLICT")
        return _err("CONFLICT", "Group is already deleted.")

    # ---- perform deletion: soft-delete group; remove group_membership links ----
    # business rule: member items are not deleted; ungroup by deleting links
    changed = False
    for o in objects:
        if o.get("id") == group_id:
            o["status"] = "deleted"
            o["updated_at"] = now
            changed = True
            break

    if not changed:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Group not found.")

    new_links = []
    removed_links = 0
    for l in links:
        if l.get("board_id") == board_id and l.get("link_type") == "group_membership" and l.get("from_object_id") == group_id:
            removed_links += 1
            continue
        # also remove any link where the deleted group appears as to_object_id (shouldn't happen, but integrity)
        if l.get("board_id") == board_id and (l.get("from_object_id") == group_id or l.get("to_object_id") == group_id):
            removed_links += 1
            continue
        new_links.append(l)

    # Also clear group_id pointers on member objects (best-effort consistency)
    for o in objects:
        if o.get("board_id") == board_id and o.get("group_id") == group_id:
            o["group_id"] = None
            o["updated_at"] = now

    _save("board_objects.json", objects)
    if removed_links:
        _save("object_links.json", new_links)

    _log("OK", credential_id=actor_membership.get("member_principal_id"), extra={"removed_links": removed_links})
    return {
        "board_id": board_id,
        "group_id": group_id,
        "deleted": True,
        "removed_group_memberships": removed_links,
        "group": next((o for o in objects if o.get("id") == group_id), None),
    }

def create_items_in_bulk_using_file(board_id, file, **_extra):
    import json, os, datetime, re, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, uuid
    endpoint = "create-items-in-bulk-using-file"
    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": f"mir_req_{uuid.uuid4().hex[:18].upper()}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limited():
        # bulk endpoint: 60/min per endpoint
        logs = _ensure_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
            if cnt >= 60:
                return True
        return False

    def _finite_number(x):
        try:
            v = float(x)
            return not (math.isnan(v) or math.isinf(v))
        except Exception:
            return False

    if _rate_limited():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log("error", "VALIDATION_ERROR", {"field": "board_id"})
        return _err("VALIDATION_ERROR", "board_id is invalid.", field="board_id")
    if not isinstance(file, str) or not file.strip():
        _log("error", "VALIDATION_ERROR", {"field": "file"})
        return _err("VALIDATION_ERROR", "file is required.", field="file")

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")
    board = next((b for b in boards if isinstance(b, dict) and b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        _log("error", "NOT_FOUND", {"board_id": board_id})
        return _err("NOT_FOUND", "Board not found.", board_id=board_id)

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    can_create = any(
        isinstance(m, dict)
        and m.get("board_id") == board_id
        and m.get("status") == "active"
        and m.get("role") in ("owner", "editor")
        for m in memberships
    )
    if not can_create:
        _log("error", "UNAUTHORIZED", {"board_id": board_id})
        return _err("UNAUTHORIZED", "You don’t have permission to create items on the board.", board_id=board_id)

    # read payload file: allow absolute path, or relative to /app/database, or treat as literal JSON
    payload_text = None
    candidate_paths = [file]
    if not os.path.isabs(file):
        candidate_paths.append(os.path.join(_DB, file))
    for p in candidate_paths:
        try:
            with open(p, encoding="utf-8") as f:
                payload_text = f.read()
                break
        except FileNotFoundError:
            continue
        except OSError:
            continue
    if payload_text is None:
        # try treating `file` as raw json content
        payload_text = file

    try:
        payload = json.loads(payload_text)
    except Exception:
        _log("error", "VALIDATION_ERROR", {"field": "file"})
        return _err("VALIDATION_ERROR", "Payload cannot be parsed as valid JSON.", field="file")

    items_in = None
    if isinstance(payload, list):
        items_in = payload
    elif isinstance(payload, dict):
        # common wrappers
        for k in ("items", "data", "objects"):
            if isinstance(payload.get(k), list):
                items_in = payload.get(k)
                break
        if items_in is None and all(k in payload for k in ("object_type",)):
            items_in = [payload]
    if items_in is None:
        _log("error", "VALIDATION_ERROR", {"field": "file"})
        return _err("VALIDATION_ERROR", "Bulk payload must be a list of items (or contain an 'items' list).", field="file")

    # transactional: validate all first, then persist all or none
    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_objects.")

    def _get_active(oid):
        o = next((x for x in objs if isinstance(x, dict) and x.get("id") == oid and x.get("board_id") == board_id), None)
        if not o or o.get("status") == "deleted":
            return None
        return o

    created = []
    failures = []
    new_rows = []
    existing_ids = {o.get("id") for o in objs if isinstance(o, dict)}

    allowed_item_types = {
        "item_app_card", "item_card", "item_sticky_note", "item_frame", "item_document", "item_text",
        "item_image", "item_shape", "item_embed", "item_mindmap_node"
    }

    # validation pass
    for idx, it in enumerate(items_in):
        if not isinstance(it, dict):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "Each item must be an object."})
            continue
        obj_type = it.get("object_type") or it.get("type")
        if not isinstance(obj_type, str) or obj_type not in allowed_item_types:
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "Unsupported or missing object_type."})
            continue
        parent_id = it.get("parent_object_id")
        group_id = it.get("group_id")
        geom = it.get("geometry")
        sty = it.get("style")
        dat = it.get("data")
        ttl = it.get("title")
        txt = it.get("text_content")

        if parent_id is not None and (not isinstance(parent_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", parent_id)):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "parent_object_id is malformed.", "field": "parent_object_id"})
            continue
        if group_id is not None and (not isinstance(group_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", group_id)):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "group_id is malformed.", "field": "group_id"})
            continue
        if geom is not None and not isinstance(geom, dict):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "geometry must be an object.", "field": "geometry"})
            continue
        if sty is not None and not isinstance(sty, dict):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "style must be an object.", "field": "style"})
            continue
        if dat is not None and not isinstance(dat, dict):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "data must be an object.", "field": "data"})
            continue
        if ttl is not None and not isinstance(ttl, str):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "title must be a string.", "field": "title"})
            continue
        if txt is not None and not isinstance(txt, str):
            failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "text_content must be a string.", "field": "text_content"})
            continue
        if geom is not None:
            if "x" in geom and not _finite_number(geom.get("x")):
                failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "geometry.x must be a finite number.", "field": "geometry.x"})
                continue
            if "y" in geom and not _finite_number(geom.get("y")):
                failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "geometry.y must be a finite number.", "field": "geometry.y"})
                continue

        if parent_id is not None:
            parent = _get_active(parent_id)
            if not parent:
                failures.append({"index": idx, "code": "NOT_FOUND", "message": "parent_object_id not found on this board.", "parent_object_id": parent_id})
                continue
            if parent.get("object_type") != "item_frame":
                failures.append({"index": idx, "code": "CONFLICT", "message": "parent_object_id is not a valid container.", "parent_object_id": parent_id})
                continue

        if group_id is not None:
            grp = _get_active(group_id)
            if not grp:
                failures.append({"index": idx, "code": "NOT_FOUND", "message": "group_id not found on this board.", "group_id": group_id})
                continue
            if grp.get("object_type") != "group":
                failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "group_id must refer to a group object.", "field": "group_id"})
                continue

        # build a row (allocate id)
        new_id = None
        for _ in range(20):
            cand = "mir_obj_" + uuid.uuid4().hex[:18].upper()
            if cand not in existing_ids:
                new_id = cand
                existing_ids.add(cand)
                break
        if not new_id:
            failures.append({"index": idx, "code": "CONFLICT", "message": "Unable to allocate object id."})
            continue

        row = {
            "id": new_id,
            "external_miro_object_id": None,
            "board_id": board_id,
            "object_type": obj_type,
            "status": "active",
            "parent_object_id": parent_id,
            "group_id": group_id,
            "title": ttl,
            "text_content": txt,
            "data": dat,
            "style": sty,
            "geometry": geom,
            "connector_from_object_id": None,
            "connector_to_object_id": None,
            "image_source_url": it.get("image_source_url"),
            "image_asset_ref": it.get("image_asset_ref"),
            "created_by_user_id": None,
            "created_at": now,
            "updated_at": now,
        }

        # enforce image XOR rule if item_image
        if obj_type == "item_image":
            src = row.get("image_source_url")
            aref = row.get("image_asset_ref")
            if (src is None or src == "") and (aref is None or aref == ""):
                failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "Image must have image_source_url or image_asset_ref."})
                continue
            if src and aref:
                failures.append({"index": idx, "code": "VALIDATION_ERROR", "message": "Image cannot have both image_source_url and image_asset_ref."})
                continue

        new_rows.append(row)

    if failures:
        # atomic: none persisted
        _log("error", "VALIDATION_ERROR", {"failures": len(failures)})
        return {"created_items": [], "failures": failures, "created_count": 0}

    # persist all
    objs.extend(new_rows)
    _save("board_objects.json", objs)
    created = new_rows
    _log("success", meta={"created_count": len(created)})
    return {"created_items": created, "failures": [], "created_count": len(created)}

def create_mindmap_node(board_id, parent_object_id, title, geometry=None, style=None, data=None, **_extra):
