    if geometry is not None:
        if "x" in geometry and not _finite_number(geometry.get("x")):
            _log("error", "VALIDATION_ERROR", {"field": "geometry.x"})
            return _err("VALIDATION_ERROR", "geometry.x must be a finite number.", field="geometry.x")
        if "y" in geometry and not _finite_number(geometry.get("y")):
