    # allow parent being mindmap node or other container that can hold nodes; enforce basic conflict rule:
    # disallow connectors/tags as parents.
    if parent.get("object_type") in ("connector", "tag"):
        _log("error", "CONFLICT", {"parent_object_id": parent_object_id})
        return _err("CONFLICT", "Parent object is not a valid mind map node/container.", parent_object_id=parent_object_id)

