def get_mindmap_nodes(board_id, parent_object_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, credential_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if detail is not None:
            entry["detail"] = detail
        logs.append(entry)
        _save("request_logs.json", logs)

    def _check_limits(endpoint):
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit_per_minute")
        quota = limits.get("quota_per_day")
        if rl is None and quota is None:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        dt_now = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        if rl is not None:
            try:
                rl = int(rl)
            except Exception:
                rl = None
            if rl is not None and rl >= 0:
                cutoff = dt_now - datetime.timedelta(minutes=1)
                c = 0
                for r in reversed(logs):
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dts = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if dts < cutoff:
                        break
                    if r.get("endpoint") == endpoint:
                        c += 1
                if c >= rl:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        if quota is not None:
            try:
                quota = int(quota)
            except Exception:
                quota = None
            if quota is not None and quota >= 0:
                cutoff = dt_now - datetime.timedelta(days=1)
                c = 0
                for r in reversed(logs):
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dts = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if dts < cutoff:
                        break
                    if r.get("endpoint") == endpoint:
                        c += 1
                if c >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    endpoint = "get-mindmap-nodes"
    lim = _check_limits(endpoint)
    if lim:
        _log(endpoint, "error", detail=lim["error"])
        return lim

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        e = _err("VALIDATION_ERROR", "Invalid board_id format.")
        _log(endpoint, "error", detail=e["error"])
        return e

    if parent_object_id is not None:
        if (not isinstance(parent_object_id, str)) or (not re.match(r"^mir_obj_[0-9A-Z]{18,}$", parent_object_id or "")):
            e = _err("VALIDATION_ERROR", "Invalid parent_object_id format.")
            _log(endpoint, "error", detail=e["error"])
            return e

    if status is not None:
        if status not in ("active", "deleted"):
            e = _err("VALIDATION_ERROR", "Invalid status. Must be 'active' or 'deleted'.")
            _log(endpoint, "error", detail=e["error"])
            return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "Invalid limit. Must be an integer.")
        _log(endpoint, "error", detail=e["error"])
        return e
    if limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "Invalid limit. Must be between 1 and 100.")
        _log(endpoint, "error", detail=e["error"])
        return e

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "-created_at", "updated_at", "-updated_at"):
        e = _err("VALIDATION_ERROR", "Invalid sort.")
        _log(endpoint, "error", detail=e["error"])
        return e

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log(endpoint, "error", detail=e["error"])
            return e
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("bad cursor")
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log(endpoint, "error", detail=e["error"])
            return e

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found.")
        _log(endpoint, "error", detail=e["error"])
        return e

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []
    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict)}
    allowed = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("invited", "active"):
            continue
        pid = m.get("member_principal_id")
        p = principal_by_id.get(pid)
        if p and p.get("principal_type") == "user" and p.get("status") == "active":
            allowed = True
            break
    if not allowed:
        e = _err("UNAUTHORIZED", "Not authorized to view this board.")
        _log(endpoint, "error", detail=e["error"])
        return e

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []

    if parent_object_id is not None:
        parent = next((o for o in objs if isinstance(o, dict) and o.get("id") == parent_object_id and o.get("board_id") == board_id), None)
        if not parent or parent.get("status") == "deleted":
            e = _err("NOT_FOUND", "parent_object_id not found on this board.")
            _log(endpoint, "error", detail=e["error"])
            return e

    nodes = []
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("board_id") != board_id:
            continue
        if o.get("object_type") != "item_mindmap_node":
            continue
        if parent_object_id is not None and o.get("parent_object_id") != parent_object_id:
            continue
        if status is None:
            if o.get("status") != "active":
                continue
        else:
            if o.get("status") != status:
                continue
        nodes.append(o)

    key = sort.lstrip("-")
    reverse = sort.startswith("-")

    def _dt(v):
        if not isinstance(v, str):
            return ""
        return v

    nodes.sort(key=lambda r: (_dt(r.get(key)), r.get("id") or ""), reverse=reverse)

    total = len(nodes)
    page = nodes[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{start+limit}".encode("utf-8")).decode("utf-8")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort
        }
    }
    _log(endpoint, "ok")
    return resp

