                    try:
                        dts = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if dts < cutoff:
                        break
                    if r.get("endpoint") == endpoint:
                        c += 1
                if c >= rl:
