            try:
                quota = int(quota)
            except Exception:
                quota = None
            if quota is not None and quota >= 0:
                cutoff = dt_now - datetime.timedelta(days=1)
                c = 0
                for r in reversed(logs):
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dts = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if dts < cutoff:
                        break
                    if r.get("endpoint") == endpoint:
                        c += 1
                if c >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    endpoint = "delete-mindmap-node"
    lim = _check_limits(endpoint)
    if lim:
        _log(endpoint, "error", detail=lim["error"])
        return lim

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        e = _err("VALIDATION_ERROR", "Invalid board_id format.")
        _log(endpoint, "error", detail=e["error"])
        return e
    if not isinstance(node_id, str) or not re.match(r"^mir_obj_[0-9A-Z]{18,}$", node_id or ""):
        e = _err("VALIDATION_ERROR", "Invalid node_id format.")
        _log(endpoint, "error", detail=e["error"])
        return e

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found.")
        _log(endpoint, "error", detail=e["error"])
        return e

    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []
    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict)}

    # Need edit permission: any active membership with role owner/editor for an active user principal.
    can_edit = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") != "active":
            continue
        if m.get("role") not in ("owner", "editor"):
            continue
        pid = m.get("member_principal_id")
        p = principal_by_id.get(pid)
        if p and p.get("principal_type") == "user" and p.get("status") == "active":
            can_edit = True
            break
    if not can_edit:
        e = _err("UNAUTHORIZED", "Not authorized to edit this board.")
        _log(endpoint, "error", detail=e["error"])
        return e

    objs = _load("board_objects.json")
    if not isinstance(objs, list):
        objs = []
    idx = None
    node = None
    for i, o in enumerate(objs):
        if not isinstance(o, dict):
            continue
        if o.get("id") == node_id and o.get("board_id") == board_id and o.get("object_type") == "item_mindmap_node":
            idx = i
            node = o
            break
    if node is None:
        e = _err("NOT_FOUND", "Mind map node not found on this board.")
        _log(endpoint, "error", detail=e["error"])
        return e

    if node.get("status") == "deleted":
        # Idempotent: already deleted -> acknowledge with current state
        resp = {"data": {"id": node_id, "board_id": board_id, "status": "deleted", "deleted": True}}
        _log(endpoint, "ok")
        return resp

    # Dependency rule: cannot delete if there are active mindmap children
    children = []
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("board_id") != board_id:
            continue
        if o.get("object_type") == "item_mindmap_node" and o.get("status") == "active" and o.get("parent_object_id") == node_id:
            children.append(o.get("id"))
    if children:
        e = _err("CONFLICT", "Cannot delete mind map node with active child nodes.", child_node_ids=children)
        _log(endpoint, "error", detail=e["error"])
        return e

    # Soft delete + clean up object_links that reference it (either side) as per business rules
    objs[idx]["status"] = "deleted"
    objs[idx]["updated_at"] = now

    links = _load("object_links.json")
    if not isinstance(links, list):
        links = []
    new_links = []
    removed_links = 0
    for l in links:
        if not isinstance(l, dict):
            continue
        if l.get("board_id") != board_id:
            new_links.append(l)
            continue
        if l.get("from_object_id") == node_id or l.get("to_object_id") == node_id:
            removed_links += 1
            continue
        new_links.append(l)

    _save("board_objects.json", objs)
    if removed_links:
        _save("object_links.json", new_links)

    resp = {
        "data": {
            "id": node_id,
            "board_id": board_id,
            "status": "deleted",
            "deleted": True,
            "removed_links": removed_links
        }
    }
    _log(endpoint, "ok")
    return resp

