                quota = int(quota)
            except Exception:
                quota = None
            if quota is not None and quota >= 0:
                cutoff = dt_now - datetime.timedelta(days=1)
                c = 0
                for r in reversed(logs):
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    try:
                        dts = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    except Exception:
                        continue
                    if dts < cutoff:
                        break
                    if r.get("endpoint") == endpoint:
                        c += 1
                if c >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    endpoint = "get-board-classification"
    lim = _check_limits(endpoint)
    if lim:
        _log(endpoint, "error", detail=lim["error"])
        return lim

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id or ""):
        e = _err("VALIDATION_ERROR", "Invalid board_id format.")
        _log(endpoint, "error", detail=e["error"])
        return e

    boards = _load("boards.json")
    if not isinstance(boards, list):
        boards = []
    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found.")
        _log(endpoint, "error", detail=e["error"])
        return e

    org_id = board.get("organization_id")
    if not org_id:
        e = _err("UNAUTHORIZED", "Board is not in an Enterprise organization.")
        _log(endpoint, "error", detail=e["error"])
        return e

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    org = next((p for p in principals if isinstance(p, dict) and p.get("id") == org_id and p.get("principal_type") == "organization" and p.get("status") == "active"), None)
    if not org:
        e = _err("UNAUTHORIZED", "Enterprise organization not found or not active.")
        _log(endpoint, "error", detail=e["error"])
        return e

    # Permission: any active/invited membership for any active user whose ancestor chain includes this org (team->org, project->team->org).
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        memberships = []
    principal_by_id = {p.get("id"): p for p in principals if isinstance(p, dict)}

    def _in_org(principal_id):
        seen = set()
        cur = principal_id
        while isinstance(cur, str) and cur and cur not in seen:
            seen.add(cur)
            p = principal_by_id.get(cur)
            if not p:
                return False
            if p.get("id") == org_id:
                return True
            cur = p.get("parent_principal_id")
        return False

    allowed = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("invited", "active"):
            continue
        pid = m.get("member_principal_id")
        p = principal_by_id.get(pid)
        if not p or p.get("principal_type") != "user" or p.get("status") != "active":
            continue
        if _in_org(pid):
            allowed = True
            break
    if not allowed:
        e = _err("UNAUTHORIZED", "Not authorized to view governance settings for this board.")
        _log(endpoint, "error", detail=e["error"])
        return e

    classification = board.get("classification")
    resp = {
        "data": {
            "board_id": board_id,
            "organization_id": org_id,
            "classification": classification
        }
    }
    _log(endpoint, "ok")
    return resp

def update_board_classification(board_id, classification, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(endpoint, status, credential_id=None, principal_id=None, meta=None, started=None):
        if not _ensure_request_log():
            return
        logs = _load("request_logs.json")
        if started is None:
            started = time.time()
        latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": "mir_req_" + uuid.uuid4().hex[:18].upper(),
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "principal_id": principal_id,
            "meta": meta or {},
            "latency_ms": latency_ms,
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint = "update-board-classification"

    # Validate
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "board_id is malformed")
    if classification is None or not isinstance(classification, dict):
        _log(endpoint, "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "classification must be an object")

    principals = _load("principals.json")
    boards = _load("boards.json")
    memberships = _load("board_memberships.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        _log(endpoint, "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Board not found")

    org_id = board.get("organization_id")
    # Enterprise-only: board.organization_id must be non-null
    if not org_id or not isinstance(org_id, str):
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Enterprise features are not enabled for this board")

    org = next((p for p in principals if p.get("id") == org_id and p.get("principal_type") == "organization" and p.get("status") == "active"), None)
    if not org:
        _log(endpoint, "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Organization not found for this board")

    # Ambient auth: pick any active user principal in the org that has an active membership on this board
    # (or invited membership is allowed? rule says accessible memberships; for updates we require active).
    active_user_ids = {p.get("id") for p in principals if p.get("principal_type") == "user" and p.get("status") == "active" and p.get("id")}
    # Determine org membership by hierarchy: user->team->organization, or direct parent
    principal_by_id = {p.get("id"): p for p in principals if p.get("id")}

    def _user_in_org(user_id, target_org_id):
        u = principal_by_id.get(user_id)
        if not u or u.get("principal_type") != "user":
            return False
        cur = u
        seen = set()
        while cur and cur.get("parent_principal_id") and cur.get("parent_principal_id") not in seen:
            seen.add(cur.get("parent_principal_id"))
            par = principal_by_id.get(cur.get("parent_principal_id"))
            if not par:
                break
            if par.get("id") == target_org_id and par.get("principal_type") == "organization":
                return True
            cur = par
        return False

    accessible_user_id = None
    for m in memberships:
        if m.get("board_id") != board_id:
            continue
        if m.get("status") != "active":
            continue
        uid = m.get("member_principal_id")
        if uid in active_user_ids and _user_in_org(uid, org_id):
            accessible_user_id = uid
            break

    if not accessible_user_id:
        _log(endpoint, "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authorized to access this board in the organization")

    # Apply classification with audit fields
    now = _now()
    new_class = dict(classification)
    # Ensure typical fields exist for observability
    new_class.setdefault("updated_by", accessible_user_id)
    new_class.setdefault("updated_at", now)

    board["classification"] = new_class
    board["updated_at"] = now

    _save("boards.json", boards)

    # Write an audit event (enterprise_ops)
    ent = _load("enterprise_ops.json")
    occurred_dt = now
    exp_dt = (datetime.datetime.utcnow() + datetime.timedelta(days=90)).replace(microsecond=0).isoformat() + "Z"
    ent.append({
        "id": "mir_ent_" + uuid.uuid4().hex[:18].upper(),
        "record_type": "audit_event",
        "organization_id": org_id,
        "board_id": board_id,
        "case_id": None,
        "legal_hold_id": None,
        "object_id": None,
        "status": "immutable",
        "payload": {
            "action": "update_board_classification",
            "actor_user_id": accessible_user_id,
            "classification": new_class,
        },
        "occurred_at": occurred_dt,
        "expires_at": exp_dt,
        "created_at": now,
        "updated_at": now,
    })
    _save("enterprise_ops.json", ent)

    resp = {
        "board": board,
        "classification": board.get("classification"),
    }
    _log(endpoint, "ok", principal_id=accessible_user_id)
    return resp

def create_board_export_job(organization_id, board_ids, payload=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create-board-export-job"
    started = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status, error_code=None, meta=None):
        logs = _ensure_logs()
        logs.append({
            "id": "mir_req_" + uuid.uuid4().hex[:18].upper(),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int(max(0, (time.time() - started) * 1000)),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limited():
        # heavy endpoint: 120/min per endpoint
        logs = _ensure_logs()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < cutoff:
                break
            cnt += 1
            if cnt >= 120:
                return True
        return False

    if _rate_limited():
        _log("error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    if not isinstance(organization_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", organization_id):
        _log("error", "VALIDATION_ERROR", {"field": "organization_id"})
        return _err("VALIDATION_ERROR", "organization_id is malformed.", field="organization_id")
    if not isinstance(board_ids, list) or len(board_ids) < 1:
        _log("error", "VALIDATION_ERROR", {"field": "board_ids"})
        return _err("VALIDATION_ERROR", "board_ids must be a non-empty array.", field="board_ids")
    for bid in board_ids:
        if not isinstance(bid, str) or not re.match(r"^mir_brd_[0-9A-Z]{18,}$", bid):
            _log("error", "VALIDATION_ERROR", {"field": "board_ids"})
            return _err("VALIDATION_ERROR", "One or more board_ids are malformed.", field="board_ids", board_id=bid)
    if payload is not None and not isinstance(payload, dict):
        _log("error", "VALIDATION_ERROR", {"field": "payload"})
        return _err("VALIDATION_ERROR", "payload must be an object.", field="payload")

    principals = _load("principals.json")
    if not isinstance(principals, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for principals.")
    org = next((p for p in principals if isinstance(p, dict) and p.get("id") == organization_id), None)
    if not org or org.get("status") != "active" or org.get("principal_type") != "organization":
        _log("error", "NOT_FOUND", {"organization_id": organization_id})
        return _err("NOT_FOUND", "Organization not found.", organization_id=organization_id)

    boards = _load("boards.json")
    if not isinstance(boards, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for boards.")

    # ensure boards exist and belong to organization and are enterprise-enabled (organization_id non-null matches)
    by_id = {b.get("id"): b for b in boards if isinstance(b, dict)}
    for bid in board_ids:
        b = by_id.get(bid)
        if not b or b.get("status") == "deleted":
            _log("error", "NOT_FOUND", {"board_id": bid})
            return _err("NOT_FOUND", "Board not found.", board_id=bid)
        if b.get("organization_id") != organization_id:
            _log("error", "NOT_FOUND", {"board_id": bid, "organization_id": organization_id})
            return _err("NOT_FOUND", "Board is not in the specified organization.", board_id=bid, organization_id=organization_id)

    # caller must be in that organization: infer via any membership on any board in that org
    memberships = _load("board_memberships.json")
    if not isinstance(memberships, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for board_memberships.")
    board_ids_in_org = {b.get("id") for b in boards if isinstance(b, dict) and b.get("organization_id") == organization_id and b.get("status") != "deleted"}
    in_org = any(
        isinstance(m, dict)
        and m.get("board_id") in board_ids_in_org
        and m.get("status") == "active"
        for m in memberships
    )
    if not in_org:
        _log("error", "UNAUTHORIZED", {"organization_id": organization_id})
        return _err("UNAUTHORIZED", "Caller is not in the organization.", organization_id=organization_id)

    ops = _load("enterprise_ops.json")
    if not isinstance(ops, list):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore malformed for enterprise_ops.")

    export_job_id = "mir_eop_" + uuid.uuid4().hex[:18].upper()
    job_payload = {"board_ids": list(board_ids)}
    if isinstance(payload, dict):
        job_payload.update(payload)

    row = {
        "id": export_job_id,
        "record_type": "board_export_job",
        "organization_id": organization_id,
        "board_id": None,
        "case_id": None,
        "legal_hold_id": None,
        "object_id": None,
        "status": "queued",
        "payload": job_payload,
        "occurred_at": None,
        "expires_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(row)
    _save("enterprise_ops.json", ops)

    _log("success", meta={"export_job_id": export_job_id, "board_count": len(board_ids)})
    return {"export_job": row}

def get_board_export_job_status(export_job_id, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(22))

    t0 = time.time()
    endpoint = "get-board-export-job-status"
    used_credential = None

    request_logs = _load("request_logs.json")
    usage = _load("usage_counters.json")

    def _log_and_return(resp, status="succeeded", code_for_log=None):
        nonlocal request_logs, usage
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append(
            {
                "id": _gen_id("mir_req_"),
                "endpoint": endpoint,
                "credential_id": used_credential,
                "status": status,
                "error_code": code_for_log,
                "latency_ms": latency_ms,
                "timestamp": _now(),
            }
        )
        _save("request_logs.json", request_logs)
        if isinstance(usage, list):
            usage.append(
                {
                    "id": _gen_id("mir_use_"),
                    "endpoint": endpoint,
                    "timestamp": _now(),
                    "status": status,
                    "latency_ms": latency_ms,
                }
            )
            _save("usage_counters.json", usage)
        return resp

    # Rate limit: 120 req/min global for polling.
    try:
        now_dt = datetime.datetime.utcnow()
        one_min_ago = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for r in request_logs[-5000:]:
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= one_min_ago:
                recent += 1
        if recent >= 120:
            return _log_and_return(_err("RATE_LIMIT", "Rate limit exceeded"), status="failed", code_for_log="RATE_LIMIT")
    except Exception:
        pass

    # Validate
    if not isinstance(export_job_id, str) or not re.match(r"^mir_ent_[0-9A-Z]{18,}$", export_job_id or ""):
        return _log_and_return(
            _err("VALIDATION_ERROR", "export_job_id is malformed", field="export_job_id"),
            status="failed",
            code_for_log="VALIDATION_ERROR",
        )

    ent = _load("enterprise_ops.json")
    principals = _load("principals.json")
    boards = _load("boards.json")

    job = next((r for r in ent if r.get("id") == export_job_id and r.get("record_type") == "board_export_job"), None)
    if not job:
        return _log_and_return(
            _err("NOT_FOUND", "Export job not found", export_job_id=export_job_id),
            status="failed",
            code_for_log="NOT_FOUND",
        )

    org_id = job.get("organization_id")
    if not org_id:
        return _log_and_return(
            _err("NOT_FOUND", "Export job not found", export_job_id=export_job_id),
            status="failed",
            code_for_log="NOT_FOUND",
        )

    org = next((p for p in principals if p.get("id") == org_id), None)
    if not org or org.get("principal_type") != "organization" or org.get("status") != "active":
        return _log_and_return(
            _err("NOT_FOUND", "Export job not found", export_job_id=export_job_id),
            status="failed",
            code_for_log="NOT_FOUND",
        )

    # Enterprise-enabled visibility: ensure there exists at least one board in this org with organization_id set
    # and at least one active user in org (ambient auth selection).
    by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and p.get("id")}
    def _resolve_org(principal_id, limit=10):
        cur = by_id.get(principal_id)
        for _ in range(limit):
            if not cur:
                return None
            if cur.get("principal_type") == "organization":
                return cur.get("id")
            pid = cur.get("parent_principal_id")
            if not pid:
                return None
            cur = by_id.get(pid)
        return None

    has_active_user_in_org = False
    for p in principals:
        if p.get("principal_type") == "user" and p.get("status") == "active":
            if _resolve_org(p.get("id")) == org_id:
                has_active_user_in_org = True
                break
    if not has_active_user_in_org:
        return _log_and_return(
            _err("UNAUTHORIZED", "Not authorized to view export jobs for this organization"),
            status="failed",
            code_for_log="UNAUTHORIZED",
        )

    # If job references boards not enterprise-enabled, treat as not visible (shouldn't happen if created via API).
    payload = job.get("payload") if isinstance(job.get("payload"), dict) else {}
    job_board_ids = payload.get("board_ids") if isinstance(payload.get("board_ids"), list) else []
    for bid in job_board_ids:
        b = next((x for x in boards if x.get("id") == bid), None)
        if not b or b.get("organization_id") != org_id:
            return _log_and_return(
                _err("NOT_FOUND", "Export job not found", export_job_id=export_job_id),
                status="failed",
                code_for_log="NOT_FOUND",
            )

    # Observable dynamics: advance job status over time and create result on success.
    now_dt = datetime.datetime.utcnow()
    updated = False

    status = job.get("status")
    created_dt = _parse_dt(job.get("created_at")) or now_dt
    age_s = (now_dt - created_dt).total_seconds()

    # Progress simulation: queued -> running after 2s, running -> succeeded after 8s.
    if status == "queued" and age_s >= 2:
        job["status"] = "running"
        job["updated_at"] = _now()
        # init progress
        if isinstance(job.get("payload"), dict):
            prog = job["payload"].get("progress")
            if not isinstance(prog, dict):
                job["payload"]["progress"] = {"total": len(job_board_ids), "completed": 0}
        updated = True
        status = "running"

    if status == "running":
        total = len(job_board_ids)
        if isinstance(job.get("payload"), dict):
            prog = job["payload"].get("progress")
            if not isinstance(prog, dict):
                prog = {"total": total, "completed": 0}
                job["payload"]["progress"] = prog
            if not isinstance(prog.get("total"), int):
                prog["total"] = total
            # advance completed based on age
            # after 8s total completion, linearly scale between 2..8 seconds.
            if age_s >= 8:
                completed = total
            else:
                span = max(1.0, 8.0 - 2.0)
                frac = max(0.0, min(1.0, (age_s - 2.0) / span))
                completed = int(frac * total)
            if completed != prog.get("completed"):
                prog["completed"] = completed
                job["updated_at"] = _now()
                updated = True

        if age_s >= 8:
            job["status"] = "succeeded"
            job["updated_at"] = _now()
            updated = True

            # Create immutable result if not already present
            # Match existing by payload.job_id
            res = None
            for r in ent:
                if r.get("record_type") == "board_export_result" and r.get("organization_id") == org_id:
                    rp = r.get("payload")
                    if isinstance(rp, dict) and rp.get("job_id") == export_job_id:
                        res = r
                        break
            if res is None:
                # Create a per-board artifact list (fake refs) but persist as real row.
                artifacts = []
                for bid in job_board_ids:
                    artifacts.append(
                        {
                            "board_id": bid,
                            "artifact_type": (payload.get("format") if isinstance(payload, dict) else None) or "pdf",
                            "ref": _gen_id("mir_art_"),
                        }
                    )
                res = {
                    "id": _gen_id("mir_ent_"),
                    "record_type": "board_export_result",
                    "organization_id": org_id,
                    "board_id": None,
                    "case_id": None,
                    "legal_hold_id": None,
                    "object_id": None,
                    "status": "immutable",
                    "payload": {
                        "job_id": export_job_id,
                        "artifacts": artifacts,
                        "generated_at": _now(),
                    },
                    "occurred_at": _now(),
                    "expires_at": None,
                    "created_at": _now(),
                    "updated_at": _now(),
                }
                ent.append(res)
                updated = True
            # Store pointer
            if isinstance(job.get("payload"), dict):
                job["payload"]["result_id"] = res.get("id")

    if updated:
        _save("enterprise_ops.json", ent)

    # Return record
    return _log_and_return({"export_job": job}, status="succeeded")

def get_board_export_job_results(export_job_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, meta=None):
        meta = meta or {}
        for fname in ("request_logs.json", "usage.json", "audit_requests.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rows.append({
                    "id": "mir_req_" + uuid.uuid4().hex.upper(),
                    "endpoint": endpoint,
                    "status": status,
                    "credential_id": credential_id,
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now(),
                    "meta": meta
                })
                _save(fname, rows)
                break

    # --- Validate inputs ---
    if not isinstance(export_job_id, str) or not re.match(r"^mir_ent_[0-9A-Z]{18,}$", export_job_id):
        _log("get-board-export-job-results", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "export_job_id is malformed.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("get-board-export-job-results", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("get-board-export-job-results", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    ent = _load("enterprise_ops.json")
    principals = _load("principals.json")

    job = next((r for r in ent if isinstance(r, dict) and r.get("id") == export_job_id and r.get("record_type") == "board_export_job"), None)
    if not job:
        _log("get-board-export-job-results", "NOT_FOUND")
        return _err("NOT_FOUND", "Export job not found.")

    org_id = job.get("organization_id")
    if not org_id:
        _log("get-board-export-job-results", "CONFLICT")
        return _err("CONFLICT", "Export job is missing organization_id.")

    # Ambient auth visibility: require existence of any principal affiliated with org (same heuristic as create)
    def _org_owns_team(team_id):
        t = next((p for p in principals if p.get("id") == team_id), None)
        return bool(t and t.get("principal_type") == "team" and t.get("parent_principal_id") == org_id)

    has_access_principal = False
    for p in principals:
        if p.get("principal_type") == "team" and p.get("parent_principal_id") == org_id:
            has_access_principal = True
            break
        if p.get("principal_type") == "project" and _org_owns_team(p.get("parent_principal_id")):
            has_access_principal = True
            break
        if p.get("principal_type") == "user" and _org_owns_team(p.get("parent_principal_id")):
            has_access_principal = True
            break
    if not has_access_principal:
        _log("get-board-export-job-results", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Export job is not visible within the caller's organization.")

    # Service dynamics: progress queued/running jobs forward on polling
    now = datetime.datetime.utcnow().replace(microsecond=0)
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    changed = False
    st = job.get("status")
    created_at = _parse_dt(job.get("created_at")) or now
    age_s = (now - created_at).total_seconds()

    if st in ("queued", "running"):
        target = "running" if age_s >= 2 else "queued"
        if age_s >= 6:
            target = "succeeded"
        if target != st:
            job["status"] = target
            job["updated_at"] = _now()
            changed = True

    # If succeeded, ensure result rows exist (idempotent)
    results = [r for r in ent if isinstance(r, dict) and r.get("record_type") == "board_export_result" and (r.get("payload") or {}).get("job_id") == export_job_id]
    if job.get("status") == "succeeded" and not results:
        board_ids = []
        pl = job.get("payload") or {}
        if isinstance(pl, dict):
            board_ids = pl.get("board_ids") or []
        if not isinstance(board_ids, list):
            board_ids = []
        ts = _now()
        for bid in board_ids:
            rid = "mir_ent_" + uuid.uuid4().hex.upper()
            ent.append({
                "id": rid,
                "record_type": "board_export_result",
                "organization_id": org_id,
                "board_id": bid if isinstance(bid, str) else None,
                "case_id": None,
                "legal_hold_id": None,
                "object_id": None,
                "status": "immutable",
                "payload": {
                    "job_id": export_job_id,
                    "board_id": bid if isinstance(bid, str) else None,
                    "artifacts": [
                        {
                            "type": "download",
                            "format": (pl.get("config") or {}).get("format") if isinstance(pl.get("config"), dict) else None,
                            "url": f"file://export/{export_job_id}/{bid}.zip" if isinstance(bid, str) else f"file://export/{export_job_id}/unknown.zip"
                        }
                    ]
                },
                "occurred_at": ts,
                "expires_at": None,
                "created_at": ts,
                "updated_at": ts
            })
        changed = True
        results = [r for r in ent if isinstance(r, dict) and r.get("record_type") == "board_export_result" and (r.get("payload") or {}).get("job_id") == export_job_id]

    if changed:
        _save("enterprise_ops.json", ent)

    # Sort results in stable order: by occurred_at asc then id
    def _key(r):
        dt = _parse_dt(r.get("occurred_at")) or datetime.datetime.min
        return (dt, r.get("id") or "")
    results_sorted = sorted(results, key=_key)

    # Pagination cursor as base64 of integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("o:"):
                offset = int(raw[2:])
            else:
                offset = int(raw)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("get-board-export-job-results", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")
    page = results_sorted[offset:offset + limit]
    next_cursor = None
    if offset + limit < len(results_sorted):
        next_cursor = base64.urlsafe_b64encode(f"o:{offset+limit}".encode("utf-8")).decode("utf-8")

    _log("get-board-export-job-results", "OK", meta={"export_job_id": export_job_id, "returned": len(page), "total": len(results_sorted)})
    return {
        "export_job": {"id": job.get("id"), "status": job.get("status"), "organization_id": org_id, "updated_at": job.get("updated_at")},
        "results": page,
        "limit": limit,
        "next_cursor": next_cursor,
        "has_more": bool(next_cursor),
        "total": len(results_sorted)
    }

def get_audit_logs(organization_id, occurred_after=None, occurred_before=None, limit=None, cursor=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.replace(microsecond=0).isoformat() + "Z"
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _log(endpoint, status, credential_id=None, principal_id=None, meta=None, started=None):
        try:
            ops = _load("enterprise_ops.json")
            now = _now()
            latency_ms = None
            if started is not None:
                latency_ms = int(max(0, (time.time() - started) * 1000))
            rid = "mir_ent_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")
            row = {
                "id": rid,
                "record_type": "audit_event",
                "organization_id": organization_id,
                "board_id": None,
                "case_id": None,
                "legal_hold_id": None,
                "object_id": None,
                "status": "immutable",
                "payload": {
                    "event_type": "api_call",
                    "endpoint": endpoint,
                    "http_status": status,
                    "credential_id": credential_id,
                    "principal_id": principal_id,
                    "meta": meta or {},
                    "latency_ms": latency_ms,
                },
                "occurred_at": _iso(now),
                "expires_at": _iso(now + datetime.timedelta(days=90)),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            ops.append(row)
            _save("enterprise_ops.json", ops)
        except Exception:
            return

    started = time.time()
    endpoint = "get-audit-logs"

    # Validate inputs
    if not isinstance(organization_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", organization_id):
        _log(endpoint, 400, meta={"error": "invalid_organization_id"}, started=started)
        return _err("VALIDATION_ERROR", "organization_id is malformed.", field="organization_id")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log(endpoint, 400, meta={"error": "invalid_limit"}, started=started)
        return _err("VALIDATION_ERROR", "limit is out of range (1..500).", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log(endpoint, 400, meta={"error": "invalid_cursor_type"}, started=started)
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        _log(endpoint, 400, meta={"error": "invalid_sort_order"}, started=started)
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.", field="sort_order")

    oa = _parse_dt(occurred_after)
    ob = _parse_dt(occurred_before)
    if occurred_after is not None and oa is None:
        _log(endpoint, 400, meta={"error": "invalid_occurred_after"}, started=started)
        return _err("VALIDATION_ERROR", "occurred_after must be an RFC3339 date-time.", field="occurred_after")
    if occurred_before is not None and ob is None:
        _log(endpoint, 400, meta={"error": "invalid_occurred_before"}, started=started)
        return _err("VALIDATION_ERROR", "occurred_before must be an RFC3339 date-time.", field="occurred_before")
    if oa and ob and ob <= oa:
        _log(endpoint, 400, meta={"error": "bad_time_window"}, started=started)
        return _err("VALIDATION_ERROR", "occurred_before must be later than occurred_after.")

    now = _now()
    min_allowed = now - datetime.timedelta(days=90)
    if oa and oa < min_allowed:
        _log(endpoint, 400, meta={"error": "occurred_after_too_old"}, started=started)
        return _err("VALIDATION_ERROR", "occurred_after must be within the last 90 days.", field="occurred_after")

    principals = _load("principals.json")
    org = next((p for p in principals if p.get("id") == organization_id and p.get("principal_type") == "organization"), None)
    if not org or org.get("status") != "active":
        _log(endpoint, 404, meta={"organization_id": organization_id}, started=started)
        return _err("NOT_FOUND", "Organization not found.")

    # Ambient auth: require at least one active user under the org to treat the org as "callable"
    has_visible_principal = any(
        p.get("principal_type") == "user"
        and p.get("status") == "active"
        and p.get("parent_principal_id") == organization_id
        for p in principals
    )
    if not has_visible_principal:
        _log(endpoint, 401, meta={"organization_id": organization_id}, started=started)
        return _err("UNAUTHORIZED", "Not authorized to access this organization's audit logs.")

    ops = _load("enterprise_ops.json")

    # Filter audit_event rows per rules
    rows = []
    for r in ops:
        if r.get("record_type") != "audit_event":
            continue
        if r.get("organization_id") != organization_id:
            continue
        if r.get("status") != "immutable":
            continue
        occ = _parse_dt(r.get("occurred_at"))
        exp = _parse_dt(r.get("expires_at"))
        if not occ or not exp:
            continue
        # retention constraints: last 90 days and not expired
        if occ < min_allowed:
            continue
        if exp <= now:
            continue
        if oa and occ < oa:
            continue
        if ob and occ >= ob:
            continue
        rows.append(r)

    # Order by occurred_at per sort_order, tie-break id
    def _occ_key(row):
        dt = _parse_dt(row.get("occurred_at")) or datetime.datetime.min
        return (dt, row.get("id") or "")

    rows.sort(key=_occ_key, reverse=(sort_order == "desc"))

    # Cursor is base64url of {"o": <offset>}
    offset = 0
    if cursor:
        try:
            pad = "=" * ((4 - (len(cursor) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            offset = int(obj.get("o", 0))
            if offset < 0:
                raise ValueError("neg")
        except Exception:
            _log(endpoint, 400, meta={"error": "bad_cursor"}, started=started)
            return _err("VALIDATION_ERROR", "cursor is invalid or expired.", field="cursor")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        token = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    _log(endpoint, 200, meta={"organization_id": organization_id, "returned": len(page)}, started=started)
    return {
        "organization_id": organization_id,
        "events": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "sort_order": sort_order,
        },
        "filters": {
            "occurred_after": occurred_after,
            "occurred_before": occurred_before,
        },
    }

def get_organization_info(organization_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # --- minimal request log + rate limiting using enterprise_ops as audit_event ---
    def _log(status_code, credential_used=None, extra=None):
        extra = extra or {}
        ops = _load("enterprise_ops.json")
        principals = _load("principals.json")

        # choose any enterprise organization to anchor audit log; if none, still return response without logging
        org_ids = [p["id"] for p in principals if p.get("principal_type") == "organization" and p.get("status") == "active"]
        if not org_ids:
            return  # nowhere to log

        # basic rate limit: 120 requests/min across all calls (since no auth context is provided)
        window_start = now - datetime.timedelta(seconds=60)
        def _parse_dt(s):
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        recent = 0
        for r in ops:
            if r.get("record_type") != "audit_event":
                continue
            oc = _parse_dt(r.get("occurred_at"))
            if oc and oc.tzinfo is None:
                oc = oc.replace(tzinfo=datetime.timezone.utc)
            if oc and oc >= window_start:
                recent += 1
        if recent >= 120:
            # refuse and also log the refusal if possible
            # log refusal
            org_id = org_ids[0]
            rid = "mir_eop_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
            ops.append({
                "id": rid,
                "record_type": "audit_event",
                "organization_id": org_id,
                "board_id": None,
                "case_id": None,
                "legal_hold_id": None,
                "object_id": None,
                "status": "immutable",
                "payload": {
                    "endpoint": "get-organization-info",
                    "credential_used": credential_used,
                    "status": "RATE_LIMIT",
                    "details": extra
                },
                "occurred_at": now_iso,
                "expires_at": (now + datetime.timedelta(days=90)).isoformat(),
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("enterprise_ops.json", ops)
            raise RuntimeError("__RATE_LIMIT__")

        # log actual call
        org_id = org_ids[0]
        rid = "mir_eop_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        ops.append({
            "id": rid,
            "record_type": "audit_event",
            "organization_id": org_id,
            "board_id": None,
            "case_id": None,
            "legal_hold_id": None,
            "object_id": None,
            "status": "immutable",
            "payload": {
                "endpoint": "get-organization-info",
                "credential_used": credential_used,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "request": {"organization_id": organization_id},
                "details": extra
            },
            "occurred_at": now_iso,
            "expires_at": (now + datetime.timedelta(days=90)).isoformat(),
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("enterprise_ops.json", ops)

    # Validate input
    if not isinstance(organization_id, str):
        try:
            _log("VALIDATION_ERROR", extra={"reason": "organization_id type"})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "organization_id must be a string")
    if not re.match(r"^mir_prn_[0-9A-Z]{18,}$", organization_id or ""):
        try:
            _log("VALIDATION_ERROR", extra={"reason": "organization_id pattern"})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "organization_id is malformed", field="organization_id")

    # Rate limit enforcement (raises sentinel)
    try:
        _log("START")
    except RuntimeError as e:
        if str(e) == "__RATE_LIMIT__":
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit check failed")

    principals = _load("principals.json")
    org = next((p for p in principals if p.get("id") == organization_id and p.get("principal_type") == "organization"), None)
    if not org or org.get("status") == "deleted":
        try:
            _log("NOT_FOUND", extra={"reason": "org not found"})
        except Exception:
            pass
        return _err("NOT_FOUND", "Organization not found")

    # Enterprise-enabled check: must have at least one enterprise_ops org_snapshot record for this org
    ops = _load("enterprise_ops.json")
    has_snapshot = any(r for r in ops if r.get("record_type") == "org_snapshot" and r.get("organization_id") == organization_id)
    if not has_snapshot:
        # The tool description mentions FORBIDDEN; contract limits codes. Use UNAUTHORIZED for lack of enterprise permission/enabled.
        try:
            _log("UNAUTHORIZED", extra={"reason": "org not enterprise-enabled"})
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Organization is not Enterprise-enabled or caller lacks permission")

    # Caller accessibility: no explicit auth context exists; best-effort: accessible if organization exists and active.
    # Return governance data primarily from latest org_snapshot payload if available, else from principal fields.
    snapshots = [r for r in ops if r.get("record_type") == "org_snapshot" and r.get("organization_id") == organization_id]
    snapshots.sort(key=lambda r: r.get("created_at") or "", reverse=True)
    snap = snapshots[0] if snapshots else None

    result = {
        "id": org.get("id"),
        "principal_type": org.get("principal_type"),
        "display_name": org.get("display_name"),
        "external_miro_id": org.get("external_miro_id"),
        "status": org.get("status"),
        "created_at": org.get("created_at"),
        "updated_at": org.get("updated_at"),
        "enterprise": True,
        "governance": (snap.get("payload") if snap else None),
        "snapshot_updated_at": (snap.get("updated_at") if snap else None)
    }

    try:
        _log("OK", extra={"organization_id": organization_id})
    except Exception:
        pass
    return {"organization": result}

def get_organization_members(organization_id, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if s is None:
            return None
        if not isinstance(s, str) or s == "":
            return None
        try:
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _log(status_code, code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mir_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "get-organization-members",
            "credential_id": None,
            "status": status_code,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat()
        })
        _save("request_logs.json", logs)

    if not isinstance(organization_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", organization_id):
        _log(400, "VALIDATION_ERROR", "organization_id is malformed")
        return _err("VALIDATION_ERROR", "organization_id is malformed")

    if status is not None and status not in ("active", "suspended", "deleted"):
        _log(400, "VALIDATION_ERROR", "status must be one of 'active','suspended','deleted'")
        return _err("VALIDATION_ERROR", "status must be one of 'active','suspended','deleted'")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _log(400, "VALIDATION_ERROR", "limit must be an integer between 1 and 500")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "display_name", "email"):
        _log(400, "VALIDATION_ERROR", "sort_by must be one of created_at, updated_at, display_name, email")
        return _err("VALIDATION_ERROR", "sort_by must be one of created_at, updated_at, display_name, email")

    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        _log(400, "VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'")
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'")

    c = _decode_cursor(cursor)
    if cursor is not None and c is None:
        _log(400, "VALIDATION_ERROR", "cursor is invalid")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    org = next((p for p in principals if p.get("id") == organization_id and p.get("principal_type") == "organization" and p.get("status") != "deleted"), None)
    if org is None:
        _log(404, "NOT_FOUND", "organization not found or not accessible")
        return _err("NOT_FOUND", "organization not found or not accessible")

    # Membership inference: principals whose parent chain leads to the org (team->org, project->team->org, user->team->org)
    by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and isinstance(p.get("id"), str)}

    def _is_in_org(prn_id):
        seen = set()
        cur = by_id.get(prn_id)
        while cur and cur.get("id") not in seen:
            seen.add(cur.get("id"))
            if cur.get("id") == organization_id:
                return True
            parent = cur.get("parent_principal_id")
            if not isinstance(parent, str):
                return False
            cur = by_id.get(parent)
        return False

    members = []
    for p in principals:
        if not isinstance(p, dict):
            continue
        if p.get("principal_type") != "user":
            continue
        pid = p.get("id")
        if not isinstance(pid, str):
            continue
        if not _is_in_org(pid):
            continue
        if status is not None and p.get("status") != status:
            continue
        members.append(p)

    reverse = (sort_order == "desc")

    def _sort_key(p):
        v = p.get(sort_by)
        if v is None:
            return ""
        if isinstance(v, str):
            return v.lower() if sort_by in ("display_name", "email") else v
        return str(v)

    # Stable tie-breaker by id
    members.sort(key=lambda p: (_sort_key(p), p.get("id", "")), reverse=reverse)

    # Cursor is exclusive start on (sort_value, id)
    if c is not None:
        cur_val = c.get("v")
        cur_id = c.get("id")
        if not isinstance(cur_val, str) or not isinstance(cur_id, str):
            _log(400, "VALIDATION_ERROR", "cursor is invalid")
            return _err("VALIDATION_ERROR", "cursor is invalid")

        def _after(p):
            pv = str(_sort_key(p))
            pid = p.get("id", "")
            if reverse:
                return (pv, pid) < (cur_val, cur_id)
            else:
                return (pv, pid) > (cur_val, cur_id)

        members = [p for p in members if _after(p)]

    page = members[:limit]
    has_more = len(members) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"v": str(_sort_key(last)), "id": last.get("id")})

    _log(200)
    return {
        "data": page,
        "meta": {
            "total": len(members),
            "limit": limit,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_organization_member(organization_id, member_principal_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
