    if not isinstance(member_principal_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", member_principal_id):
        _log(400, "VALIDATION_ERROR", "member_principal_id is malformed")
        return _err("VALIDATION_ERROR", "member_principal_id is malformed")

    principals = _load("principals.json")
    if not isinstance(principals, list):
        principals = []
    by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and isinstance(p.get("id"), str)}

    org = by_id.get(organization_id)
    if org is None or org.get("principal_type") != "organization" or org.get("status") == "deleted":
        _log(404, "NOT_FOUND", "organization not found or not accessible")
        return _err("NOT_FOUND", "organization not found or not accessible")

    member = by_id.get(member_principal_id)
    if member is None:
        _log(404, "NOT_FOUND", "member not found")
        return _err("NOT_FOUND", "member not found")

    # Must be a user member
    if member.get("principal_type") != "user":
        _log(404, "NOT_FOUND", "member is not a user principal")
        return _err("NOT_FOUND", "member is not a user principal")

