                return True
            parent = cur.get("parent_principal_id")
            if not isinstance(parent, str):
                return False
            cur = by_id.get(parent)
        return False

    if not _is_in_org(member_principal_id):
        _log(404, "NOT_FOUND", "member is not part of the organization")
        return _err("NOT_FOUND", "member is not part of the organization")

    _log(200)
    return {"data": member}

def add_project_member(project_id, member_principal_id, role, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # request logging + rate limiting via enterprise_ops audit_event
    def _parse_dt(s):
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_code, extra=None):
        extra = extra or {}
        ops = _load("enterprise_ops.json")
        principals = _load("principals.json")

        org_ids = [p["id"] for p in principals if p.get("principal_type") == "organization" and p.get("status") == "active"]
        if not org_ids:
            return

        # basic rate limit: 120 requests/min global
        window_start = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in ops:
            if r.get("record_type") != "audit_event":
                continue
            oc = _parse_dt(r.get("occurred_at"))
            if oc and oc.tzinfo is None:
                oc = oc.replace(tzinfo=datetime.timezone.utc)
            if oc and oc >= window_start:
                recent += 1
        if recent >= 120:
            org_id = org_ids[0]
            rid = "mir_eop_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
            ops.append({
                "id": rid,
                "record_type": "audit_event",
                "organization_id": org_id,
                "board_id": None,
                "case_id": None,
                "legal_hold_id": None,
                "object_id": None,
                "status": "immutable",
                "payload": {
                    "endpoint": "add-project-member",
                    "status": "RATE_LIMIT",
                    "request": {"project_id": project_id, "member_principal_id": member_principal_id, "role": role},
                    "details": extra
                },
                "occurred_at": now_iso,
                "expires_at": (now + datetime.timedelta(days=90)).isoformat(),
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("enterprise_ops.json", ops)
            raise RuntimeError("__RATE_LIMIT__")

        org_id = org_ids[0]
        rid = "mir_eop_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        ops.append({
            "id": rid,
            "record_type": "audit_event",
            "organization_id": org_id,
            "board_id": None,
            "case_id": None,
            "legal_hold_id": None,
            "object_id": None,
            "status": "immutable",
            "payload": {
                "endpoint": "add-project-member",
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "request": {"project_id": project_id, "member_principal_id": member_principal_id, "role": role},
                "details": extra
            },
            "occurred_at": now_iso,
            "expires_at": (now + datetime.timedelta(days=90)).isoformat(),
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("enterprise_ops.json", ops)

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", project_id or ""):
        try:
            _log("VALIDATION_ERROR", {"field": "project_id"})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
    if not isinstance(member_principal_id, str) or not re.match(r"^mir_prn_[0-9A-Z]{18,}$", member_principal_id or ""):
        try:
            _log("VALIDATION_ERROR", {"field": "member_principal_id"})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "member_principal_id is malformed", field="member_principal_id")
    if role not in ("owner", "editor", "commenter", "viewer"):
        try:
            _log("VALIDATION_ERROR", {"field": "role"})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "role is invalid", field="role", allowed=["owner", "editor", "commenter", "viewer"])

    # Rate limit check
    try:
        _log("START")
    except RuntimeError as e:
        if str(e) == "__RATE_LIMIT__":
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit check failed")

    principals = _load("principals.json")

    project = next((p for p in principals if p.get("id") == project_id), None)
    if not project or project.get("status") == "deleted":
        try:
            _log("NOT_FOUND", {"reason": "project not found"})
        except Exception:
            pass
        return _err("NOT_FOUND", "Project not found")
    if project.get("principal_type") != "project":
        try:
            _log("VALIDATION_ERROR", {"reason": "principal_type not project"})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "project_id does not identify a project principal", field="project_id")

    member = next((p for p in principals if p.get("id") == member_principal_id), None)
    if not member or member.get("status") == "deleted":
        try:
            _log("NOT_FOUND", {"reason": "member not found"})
        except Exception:
            pass
        return _err("NOT_FOUND", "Member principal not found")

    # Ensure project is under a team/org hierarchy if present; also used to validate team/org relationship if needed later
    # parent_principal_id references principals; no further rule needed here.

    # Use board_memberships as "project membership" record (no dedicated collection provided).
    memberships = _load("board_memberships.json")

    # idempotent upsert for (board_id=project_id, member_principal_id) with status != removed uniqueness
    existing = None
    for m in memberships:
        if m.get("board_id") == project_id and m.get("member_principal_id") == member_principal_id and m.get("status") != "removed":
            existing = m
            break

    # If membership exists and is active/invited, update role (even if invited) to requested role, return mutated record
    # If membership was removed previously, create a new row.
    def _gen_id(prefix):
        return prefix + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")

    if existing:
        # Update in place
        existing["role"] = role
        # keep status; if invited, stays invited; if active, stays active
        existing["updated_at"] = now_iso
        _save("board_memberships.json", memberships)
        try:
            _log("OK", {"idempotent": True, "membership_id": existing.get("id")})
        except Exception:
            pass
        return {"project_membership": existing}

    # create new membership
    new_row = {
        "id": _gen_id("mir_bm_"),
        "board_id": project_id,
        "member_principal_id": member_principal_id,
        "role": role,
        "status": "active",  # no invite flow params in this tool; treat as direct add
        "invited_by_user_id": None,
        "team_assignment_id": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # enforce uniqueness constraint (board_id, member_principal_id) where status != 'removed'
    for m in memberships:
        if m.get("board_id") == project_id and m.get("member_principal_id") == member_principal_id and m.get("status") != "removed":
            try:
                _log("CONFLICT", {"reason": "unique constraint"})
            except Exception:
                pass
            return _err("CONFLICT", "Member already exists in project")

    memberships.append(new_row)
    _save("board_memberships.json", memberships)

    try:
        _log("OK", {"created": True, "membership_id": new_row["id"]})
    except Exception:
        pass
    return {"project_membership": new_row}

def get_project_member(project_id, member_principal_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_id=None, meta=None, started=None):
        import time as _t
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ended = _t.time()
        latency_ms = int(max(0, (ended - (started or ended)) * 1000))
        row = {
            "id": f"mir_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{os.urandom(6).hex()}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint = "get-project-member"

    try:
        pid_re = re.compile(r"^mir_prn_[0-9A-Z]{18,}$")
        if not isinstance(project_id, str) or not pid_re.match(project_id):
            _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "project_id"})
            return _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
        if not isinstance(member_principal_id, str) or not pid_re.match(member_principal_id):
            _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "member_principal_id"})
            return _err("VALIDATION_ERROR", "member_principal_id is malformed", field="member_principal_id")

        principals = _load("principals.json")
        if not isinstance(principals, list):
            principals = []
        by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and isinstance(p.get("id"), str)}

        project = by_id.get(project_id)
        if not project:
            _log(endpoint, "NOT_FOUND", started=started)
            return _err("NOT_FOUND", "Project not found")
        if project.get("principal_type") != "project":
            _log(endpoint, "VALIDATION_ERROR", started=started)
            return _err("VALIDATION_ERROR", "project_id does not identify a project principal")

        memberships = _load("board_memberships.json")
        if not isinstance(memberships, list):
            memberships = []

        found = None
        for m in memberships:
            if not isinstance(m, dict):
                continue
            if m.get("board_id") == project_id and m.get("member_principal_id") == member_principal_id and m.get("status") != "removed":
                found = m
                break

        if not found:
            _log(endpoint, "NOT_FOUND", started=started)
            return _err("NOT_FOUND", "Project membership not found")

        _log(endpoint, "OK", started=started, meta={"id": found.get("id")})
        return {"data": found}
    except Exception as e:
        _log(endpoint, "VALIDATION_ERROR", started=started, meta={"exception": str(e)})
        return _err("VALIDATION_ERROR", "Request could not be processed")

