            _log(endpoint, "VALIDATION_ERROR", started=started)
            return _err("VALIDATION_ERROR", "project_id does not identify a project principal")

        member = by_id.get(member_principal_id)
        if not member:
            _log(endpoint, "NOT_FOUND", started=started)
            return _err("NOT_FOUND", "Member principal not found")

        memberships = _load("board_memberships.json")
        if not isinstance(memberships, list):
            memberships = []

        target = None
        for m in memberships:
            if not isinstance(m, dict):
                continue
            if m.get("board_id") == project_id and m.get("member_principal_id") == member_principal_id:
                # remove only if currently not removed
                if m.get("status") != "removed":
                    target = m
                break

        if not target:
            # if row exists but already removed or not present -> CONFLICT per tool description
            exists_any = any(
                isinstance(m, dict) and m.get("board_id") == project_id and m.get("member_principal_id") == member_principal_id
                for m in memberships
            )
            if exists_any:
                _log(endpoint, "CONFLICT", started=started)
                return _err("CONFLICT", "Member is not currently a member of the project")
            _log(endpoint, "NOT_FOUND", started=started)
            return _err("NOT_FOUND", "Project membership not found")

        # Transition to removed (invited->removed, active->removed allowed)
        if target.get("status") not in ("invited", "active"):
            _log(endpoint, "INVALID_TRANSITION", started=started)
            return _err("INVALID_TRANSITION", "Membership cannot be removed from its current state", from_status=target.get("status"), to_status="removed")

        now = _now_iso()
        target["status"] = "removed"
        target["updated_at"] = now
        _save("board_memberships.json", memberships)

        _log(endpoint, "OK", started=started, meta={"id": target.get("id")})
        return {"data": {"project_id": project_id, "member_principal_id": member_principal_id, "removed": True}}
    except Exception as e:
        _log(endpoint, "VALIDATION_ERROR", started=started, meta={"exception": str(e)})
        return _err("VALIDATION_ERROR", "Request could not be processed")

def get_all_cases(organization_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not cur or not isinstance(cur, str):
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _log(endpoint, status_s, credential_id=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ended = time.time()
        latency_ms = int(max(0, (ended - (started or ended)) * 1000))
        row = {
            "id": f"mir_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}{os.urandom(6).hex()}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_s,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint = "get-all-cases"

    try:
        pid_re = re.compile(r"^mir_prn_[0-9A-Z]{18,}$")
        if not isinstance(organization_id, str) or not pid_re.match(organization_id):
            _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "organization_id"})
            return _err("VALIDATION_ERROR", "organization_id is malformed", field="organization_id")

        if status is not None and status not in ("open", "closed"):
            _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: open, closed", field="status")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

        if sort is None:
            sort = "created_at"
        if sort not in ("occurred_at", "created_at", "updated_at"):
            _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "sort"})
            return _err("VALIDATION_ERROR", "sort must be one of: occurred_at, created_at, updated_at", field="sort")

        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "order"})
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc", field="order")

        principals = _load("principals.json")
        if not isinstance(principals, list):
            principals = []
        org = None
        for p in principals:
            if isinstance(p, dict) and p.get("id") == organization_id:
                org = p
                break
        if not org:
            _log(endpoint, "NOT_FOUND", started=started)
            return _err("NOT_FOUND", "Organization not found")
        if org.get("principal_type") != "organization":
            _log(endpoint, "VALIDATION_ERROR", started=started)
            return _err("VALIDATION_ERROR", "organization_id does not identify an organization principal")

        ops = _load("enterprise_ops.json")
        if not isinstance(ops, list):
            ops = []

        rows = []
        for r in ops:
            if not isinstance(r, dict):
                continue
            if r.get("record_type") != "ediscovery_case":
                continue
            if r.get("organization_id") != organization_id:
                continue
            if status is not None and r.get("status") != status:
                continue
            rows.append(r)

        reverse = (order == "desc")

        def sort_key(r):
            v = r.get(sort)
            dt = _parse_dt(v)
            if dt is not None:
                return dt
            # missing/invalid dates sort last in asc, first in desc
            return datetime.datetime.max.replace(tzinfo=datetime.timezone.utc) if not reverse else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

        rows.sort(key=sort_key, reverse=reverse)

        # Cursor is an index into the sorted result set for this query shape
        start_idx = 0
        c = _decode_cursor(cursor) if cursor else None
        if c is not None:
            # validate cursor shape matches this query
            if not isinstance(c, dict) or c.get("organization_id") != organization_id or c.get("status") != status or c.get("sort") != sort or c.get("order") != order:
                _log(endpoint, "VALIDATION_ERROR", started=started, meta={"field": "cursor"})
                return _err("VALIDATION_ERROR", "cursor is invalid for this request", field="cursor")
            if isinstance(c.get("offset"), int) and c["offset"] >= 0:
                start_idx = c["offset"]

        page = rows[start_idx:start_idx + limit]
        next_cursor = None
        if start_idx + limit < len(rows):
            next_cursor = _encode_cursor({"organization_id": organization_id, "status": status, "sort": sort, "order": order, "offset": start_idx + limit})

        _log(endpoint, "OK", started=started, meta={"returned": len(page), "total": len(rows)})
        return {
            "data": page,
            "meta": {
                "total": len(rows),
                "limit": limit,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor,
                "sort": sort,
                "order": order,
            },
        }
    except Exception as e:
        _log(endpoint, "VALIDATION_ERROR", started=started, meta={"exception": str(e)})
        return _err("VALIDATION_ERROR", "Request could not be processed")

def get_case(case_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
