    principals = _load("principals.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Rate limiting (simple): 300 req/min global
    def _enforce_rate_limit():
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        c = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                c += 1
        if c >= 300:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    ok, rlerr = _enforce_rate_limit()
    if not ok:
        _log("error", error_code=rlerr["error"]["code"])
        return rlerr

    if not isinstance(case_id, str) or not case_id or re.match(r"^mir_ent_[0-9A-Z]{18,}$", case_id) is None:
        e = _err("VALIDATION_ERROR", "case_id is required and must match pattern ^mir_ent_[0-9A-Z]{18,}$.")
        _log("error", error_code=e["error"]["code"])
        return e

    case = None
    for row in enterprise_ops:
        if isinstance(row, dict) and row.get("id") == case_id and row.get("record_type") == "ediscovery_case":
            case = row
            break
    if not case:
        e = _err("NOT_FOUND", "eDiscovery case not found.", case_id=case_id)
        _log("error", error_code=e["error"]["code"])
        return e

    org_id = case.get("organization_id")
    org = None
    for p in principals:
        if isinstance(p, dict) and p.get("id") == org_id and p.get("principal_type") == "organization" and p.get("status") == "active":
            org = p
            break

    # Enterprise-enabled authorization: require active org principal exists.
    # Ambient auth: if there exists any active org, allow; otherwise forbidden.
    if not org:
        e = _err("UNAUTHORIZED", "Not authorized or organization is not Enterprise-enabled.", organization_id=org_id)
        _log("error", error_code=e["error"]["code"])
        return e

    _log("ok")
    return {"case": case}

