        if not isinstance(logs, list):
            return True, None
        c = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                c += 1
        if c >= 300:
            return False, _err("RATE_LIMIT", "Rate limit exceeded.")
        return True, None

    ok, rlerr = _enforce_rate_limit()
    if not ok:
        _log("error", error_code=rlerr["error"]["code"])
        return rlerr

    if not isinstance(legal_hold_id, str) or re.match(r"^mir_ent_[0-9A-Z]{18,}$", legal_hold_id) is None:
        e = _err("VALIDATION_ERROR", "legal_hold_id must match pattern ^mir_ent_[0-9A-Z]{18,}$.")
        _log("error", error_code=e["error"]["code"])
        return e

    if board_id is not None:
        if not isinstance(board_id, str) or re.match(r"^mir_brd_[0-9A-Z]{18,}$", board_id) is None:
            e = _err("VALIDATION_ERROR", "board_id must match pattern ^mir_brd_[0-9A-Z]{18,}$.")
            _log("error", error_code=e["error"]["code"])
            return e

    if object_id is not None:
        if not isinstance(object_id, str) or re.match(r"^mir_obj_[0-9A-Z]{18,}$", object_id) is None:
            e = _err("VALIDATION_ERROR", "object_id must match pattern ^mir_obj_[0-9A-Z]{18,}$.")
            _log("error", error_code=e["error"]["code"])
            return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _log("error", error_code=e["error"]["code"])
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided.")
        _log("error", error_code=e["error"]["code"])
        return e

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("occurred_at", "created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "sort must be one of: occurred_at, created_at, updated_at.")
        _log("error", error_code=e["error"]["code"])
        return e

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
        _log("error", error_code=e["error"]["code"])
        return e

    hold = None
    for row in enterprise_ops:
        if isinstance(row, dict) and row.get("id") == legal_hold_id and row.get("record_type") == "legal_hold":
            hold = row
            break
    if not hold:
        e = _err("NOT_FOUND", "Legal hold not found.", legal_hold_id=legal_hold_id)
        _log("error", error_code=e["error"]["code"])
        return e

    org_id = hold.get("organization_id")
    org = None
    for p in principals:
        if isinstance(p, dict) and p.get("id") == org_id and p.get("principal_type") == "organization" and p.get("status") == "active":
            org = p
            break
    if not org:
        e = _err("UNAUTHORIZED", "Not authorized or organization is not Enterprise-enabled.", organization_id=org_id)
        _log("error", error_code=e["error"]["code"])
        return e

    # If board_id/object_id are provided, they must exist
    if board_id is not None:
        b = None
        for row in boards:
            if isinstance(row, dict) and row.get("id") == board_id:
                b = row
                break
        if not b:
            e = _err("NOT_FOUND", "Board not found.", board_id=board_id)
            _log("error", error_code=e["error"]["code"])
            return e

    if object_id is not None:
        o = None
        for row in board_objects:
            if isinstance(row, dict) and row.get("id") == object_id:
                o = row
                break
        if not o:
            e = _err("NOT_FOUND", "Board object not found.", object_id=object_id)
            _log("error", error_code=e["error"]["code"])
            return e

    items = []
    for row in enterprise_ops:
        if not isinstance(row, dict):
            continue
        if row.get("record_type") != "legal_hold_content_item":
            continue
        if row.get("legal_hold_id") != legal_hold_id:
            continue
        if row.get("organization_id") != org_id:
            continue
        if board_id is not None and row.get("board_id") != board_id:
            continue
        if object_id is not None and row.get("object_id") != object_id:
            continue
        items.append(row)

    def _dt_key(v):
        if not isinstance(v, str) or not v:
            return datetime.datetime(1970, 1, 1)
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime(1970, 1, 1)

    reverse = (order == "desc")
    items.sort(key=lambda r: _dt_key(r.get(sort)), reverse=reverse)

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                start = int(raw.split(":", 1)[1])
                if start < 0:
                    start = 0
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("error", error_code=e["error"]["code"])
            return e

    total = len(items)
    page = items[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    _log("ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        }
    }

def get_board_content_logs(organization_id, board_id, object_id=None, status=None, occurred_from=None, occurred_to=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a date-time string")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(f"{field} must be RFC3339/ISO8601 date-time")

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v.astimezone(datetime.timezone.utc) if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                if v.endswith("Z"):
                    v2 = v[:-1] + "+00:00"
                else:
                    v2 = v
                dt = datetime.datetime.fromisoformat(v2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _encode_cursor(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            raise ValueError("cursor must be a non-empty string")
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                raise ValueError("cursor invalid")
            return obj
        except Exception:
            raise ValueError("cursor invalid")

    # --- request logging + rate limit/quota enforcement ---
    start = time.time()
    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    now = datetime.datetime.now(datetime.timezone.utc)

    # rate limit: 300 requests / 60s
    window_s = 60
    limit_window = 300
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in request_logs[-5000:]:
        ts = _dt_from_row(r.get("timestamp"))
        if ts and ts >= cutoff:
            recent += 1
    if recent >= limit_window:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "get-board-content-logs",
            "credential_id": None,
            "status": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "timestamp": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # quota: 50k/day
    day_cutoff = now - datetime.timedelta(days=1)
    day_count = 0
    for r in request_logs[-200000:]:
        ts = _dt_from_row(r.get("timestamp"))
        if ts and ts >= day_cutoff:
            day_count += 1
    if day_count >= 50000:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({
            "id": f"mir_req_{int(time.time()*1000)}",
            "endpoint": "get-board-content-logs",
            "credential_id": None,
            "status": "QUOTA_EXCEEDED",
            "latency_ms": latency_ms,
            "timestamp": _now_iso()
        })
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # --- validation ---
    org_pat = re.compile(r"^mir_prn_[0-9A-Z]{18,}$")
    brd_pat = re.compile(r"^mir_brd_[0-9A-Z]{18,}$")
    obj_pat = re.compile(r"^mir_obj_[0-9A-Z]{18,}$")

    if not isinstance(organization_id, str) or not org_pat.match(organization_id):
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid organization_id")
    if not isinstance(board_id, str) or not brd_pat.match(board_id):
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid board_id")
    if object_id is not None and (not isinstance(object_id, str) or not obj_pat.match(object_id)):
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid object_id")
    if status is not None and status != "immutable":
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid status (must be 'immutable')")
    if sort is None:
        sort = "-occurred_at"
    if sort not in ("occurred_at", "-occurred_at", "created_at", "-created_at"):
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid sort")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid limit (must be 1..200)")

    try:
        dt_from = _parse_dt(occurred_from, "occurred_from")
        dt_to = _parse_dt(occurred_to, "occurred_to")
    except ValueError as e:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", str(e))
    if dt_from and dt_to and dt_from > dt_to:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid occurred_at range: occurred_from must be <= occurred_to")

    try:
        cur = _decode_cursor(cursor) if cursor else None
    except ValueError as e:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", str(e))

    if cur:
        # validate cursor scope matches request
        if cur.get("org") != organization_id or cur.get("board") != board_id or cur.get("sort") != sort:
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "cursor does not match request scope")
        if cur.get("object_id") != (object_id or None):
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "cursor does not match request scope")
        if cur.get("occurred_from") != (occurred_from or None) or cur.get("occurred_to") != (occurred_to or None):
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "cursor does not match request scope")

    principals = _load("principals.json")
    boards = _load("boards.json")
    board_objects = _load("board_objects.json")
    enterprise_ops = _load("enterprise_ops.json")
    board_memberships = _load("board_memberships.json")

    # --- existence checks ---
    org = next((p for p in principals if p.get("id") == organization_id), None)
    if not org or org.get("principal_type") != "organization" or org.get("status") == "deleted":
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Organization not found")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Board not found")
    if board.get("organization_id") != organization_id:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Board not found in the given organization")

    # Enterprise-only + requesting principal in organization:
    # Ambient auth: choose any active user that is a member of this board and whose org chain matches.
    team_id = board.get("team_id")
    proj_id = board.get("project_id")

    principals_by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and p.get("id")}
    def _resolve_org_for_principal(pid):
        seen = set()
        curp = principals_by_id.get(pid)
        while curp and curp.get("id") not in seen:
            seen.add(curp.get("id"))
            if curp.get("principal_type") == "organization":
                return curp.get("id")
            parent = curp.get("parent_principal_id")
            if not parent:
                return None
            curp = principals_by_id.get(parent)
        return None

    # find a membership that implies access; prefer active/invited
    access_user_id = None
    for m in board_memberships:
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("active", "invited"):
            continue
        member_id = m.get("member_principal_id")
        pr = principals_by_id.get(member_id)
        if not pr or pr.get("principal_type") != "user" or pr.get("status") != "active":
            continue
        org_id = _resolve_org_for_principal(member_id) or _resolve_org_for_principal(team_id) or _resolve_org_for_principal(proj_id)
        if org_id == organization_id:
            access_user_id = member_id
            break

    if access_user_id is None:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "UNAUTHORIZED", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "No authorized principal available for this organization/board")

    if object_id is not None:
        obj = next((o for o in board_objects if o.get("id") == object_id), None)
        if not obj or obj.get("board_id") != board_id:
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("NOT_FOUND", "Object not found on board")

    # --- filtering ---
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    rows = []
    for r in enterprise_ops:
        if r.get("record_type") != "board_content_log":
            continue
        if r.get("organization_id") != organization_id:
            continue
        if r.get("board_id") != board_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        # rule: content log implies immutable; if store has bad row, treat it as not matching immutable filter by default
        if status is None and r.get("status") != "immutable":
            continue

        occ = _dt_from_row(r.get("occurred_at"))
        if occ is None:
            continue
        if dt_from and occ < dt_from:
            continue
        if dt_to and occ > dt_to:
            continue
        if object_id is not None and r.get("object_id") != object_id:
            continue
        rows.append(r)

    # --- sorting + pagination ---
    def _key_dt(row, field):
        d = _dt_from_row(row.get(field))
        # ensure stable sort even with bad/missing timestamps
        return d or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    reverse = sort.startswith("-")
    sort_field = sort[1:] if reverse else sort

    rows.sort(key=lambda x: (_key_dt(x, sort_field), str(x.get("id") or "")), reverse=reverse)

    # apply cursor
    if cur:
        last_ts = cur.get("last_ts")
        last_id = cur.get("last_id")
        if not isinstance(last_ts, str) or not isinstance(last_id, str):
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "cursor invalid")
        try:
            last_dt = _parse_dt(last_ts, "cursor.last_ts")
        except ValueError:
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board-content-logs", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "cursor invalid")

        def _after(row):
            rdt = _key_dt(row, sort_field)
            rid = str(row.get("id") or "")
            if reverse:
                # descending: next page has strictly smaller key or same key with id < last_id (since reversed)
                if rdt < last_dt:
                    return True
                if rdt == last_dt and rid < last_id:
                    return True
                return False
            else:
                if rdt > last_dt:
                    return True
                if rdt == last_dt and rid > last_id:
                    return True
                return False

        rows = [r for r in rows if _after(r)]

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({
            "org": organization_id,
            "board": board_id,
            "object_id": object_id or None,
            "occurred_from": occurred_from or None,
            "occurred_to": occurred_to or None,
            "sort": sort,
            "last_ts": (_key_dt(last, sort_field)).isoformat(),
            "last_id": str(last.get("id") or "")
        })

    latency_ms = int((time.time() - start) * 1000)
    request_logs.append({
        "id": f"mir_req_{int(time.time()*1000)}",
        "endpoint": "get-board-content-logs",
        "credential_id": None,
        "status": "OK",
        "latency_ms": latency_ms,
        "timestamp": _now_iso()
    })
    _save("request_logs.json", request_logs)

    return {
        "data": page,
        "meta": {
            "total": len(page) if cursor else len(rows) if not has_more else None,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "server_time": now_dt.isoformat()
        }
    }

def get_board(board_id, include_trashed=None, include_deleted=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v.astimezone(datetime.timezone.utc) if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                if v.endswith("Z"):
                    v2 = v[:-1] + "+00:00"
                else:
                    v2 = v
                dt = datetime.datetime.fromisoformat(v2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    start = time.time()
    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    now = datetime.datetime.now(datetime.timezone.utc)

    # rate limit: 300 requests / 60s
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in request_logs[-5000:]:
        ts = _dt_from_row(r.get("timestamp"))
        if ts and ts >= cutoff:
            recent += 1
    if recent >= 300:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "RATE_LIMIT", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # quota: 50k/day
    day_cutoff = now - datetime.timedelta(days=1)
    day_count = 0
    for r in request_logs[-200000:]:
        ts = _dt_from_row(r.get("timestamp"))
        if ts and ts >= day_cutoff:
            day_count += 1
    if day_count >= 50000:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "QUOTA_EXCEEDED", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    if include_trashed is None:
        include_trashed = False
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_trashed, bool):
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "include_trashed must be boolean")
    if not isinstance(include_deleted, bool):
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "include_deleted must be boolean")

    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18}$", board_id):
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "VALIDATION_ERROR", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid board_id")

    boards = _load("boards.json")
    principals = _load("principals.json")
    memberships = _load("board_memberships.json")

    board = next((b for b in boards if b.get("id") == board_id), None)
    if not board:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Board not found")

    # Visibility: board must not be deleted unless include_deleted and privileged
    st = board.get("status")
    if st == "trashed" and not include_trashed:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Board not found")
    if st == "deleted":
        # only privileged can see deleted; without an explicit auth param we treat "privileged" as: user principal in same org and there exists at least one organization principal for board, plus include_deleted=true.
        if not include_deleted:
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("NOT_FOUND", "Board not found")

    principals_by_id = {p.get("id"): p for p in principals if isinstance(p, dict) and p.get("id")}

    def _resolve_org_for_principal(pid):
        seen = set()
        curp = principals_by_id.get(pid)
        while curp and curp.get("id") not in seen:
            seen.add(curp.get("id"))
            if curp.get("principal_type") == "organization":
                return curp.get("id")
            parent = curp.get("parent_principal_id")
            if not parent:
                return None
            curp = principals_by_id.get(parent)
        return None

    # Access control: caller must have membership invited/active (business rule for visibility)
    # Ambient auth: choose any active user with membership on this board.
    access_user_id = None
    for m in memberships:
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("active", "invited"):
            continue
        member_id = m.get("member_principal_id")
        pr = principals_by_id.get(member_id)
        if not pr or pr.get("principal_type") != "user" or pr.get("status") != "active":
            continue
        access_user_id = member_id
        break

    if access_user_id is None:
        latency_ms = int((time.time() - start) * 1000)
        request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "NOT_FOUND", "latency_ms": latency_ms, "timestamp": _now_iso()})
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Board not found")

    # If include_deleted requested, require "privileged": board has organization_id and user is in that organization.
    if st == "deleted":
        org_id = board.get("organization_id")
        if not org_id:
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "UNAUTHORIZED", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Not privileged to view deleted boards")
        user_org = _resolve_org_for_principal(access_user_id)
        if user_org != org_id:
            latency_ms = int((time.time() - start) * 1000)
            request_logs.append({"id": f"mir_req_{int(time.time()*1000)}", "endpoint": "get-board", "credential_id": None, "status": "UNAUTHORIZED", "latency_ms": latency_ms, "timestamp": _now_iso()})
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Not privileged to view deleted boards")

    latency_ms = int((time.time() - start) * 1000)
    request_logs.append({
        "id": f"mir_req_{int(time.time()*1000)}",
        "endpoint": "get-board",
        "credential_id": None,
        "status": "OK",
        "latency_ms": latency_ms,
        "timestamp": _now_iso()
    })
    _save("request_logs.json", request_logs)

    return {"data": board}

def list_board_items(board_id, object_type=None, parent_object_id=None, group_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "mir_req_" + os.urandom(9).hex().upper(),
            "endpoint": "list-board-items",
            "timestamp": now,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "credential_id": credential_id,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        # If a request log collection exists, enforce simple rate/quota based on it.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        # Rate limit: 120 requests/minute globally (per offline store).
        window_s = 60
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        # Daily quota: 20000 requests/day globally.
        cutoff_d = datetime.datetime.utcnow() - datetime.timedelta(days=1)
        day = 0
        for r in logs[-50000:]:
            ts = r.get("timestamp")
            if not ts or not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff_d:
                day += 1
        if day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate inputs
    if not isinstance(board_id, str) or not re.match(r"^mir_brd_[0-9A-Z]{18}$", board_id):
        e = _err("VALIDATION_ERROR", "Invalid board_id")
        try:
            _log("VALIDATION_ERROR", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    if object_type is not None and not isinstance(object_type, str):
        e = _err("VALIDATION_ERROR", "object_type must be a string")
        try:
            _log("VALIDATION_ERROR", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    for nm, val in (("parent_object_id", parent_object_id), ("group_id", group_id)):
        if val is not None:
            if not isinstance(val, str) or not re.match(r"^mir_obj_[0-9A-Z]{18}$", val):
                e = _err("VALIDATION_ERROR", f"Invalid {nm}")
                try:
                    _log("VALIDATION_ERROR", meta={"board_id": board_id})
                except Exception:
                    pass
                return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
        try:
            _log("VALIDATION_ERROR", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            _log("VALIDATION_ERROR", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at")
        try:
            _log("VALIDATION_ERROR", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")
        try:
            _log("VALIDATION_ERROR", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    # Rate/quota enforcement
    limerr = _check_limits()
    if limerr:
        try:
            _log(limerr["error"]["code"], meta={"board_id": board_id})
        except Exception:
            pass
        return limerr

    boards = _load("boards.json")
    board = None
    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found")
        try:
            _log("NOT_FOUND", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    # Accessibility: must have a non-removed membership row for this board for some principal.
    memberships = _load("board_memberships.json")
    accessible = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") in ("invited", "active"):
            accessible = True
            break
    if not accessible:
        e = _err("NOT_FOUND", "Board not found or not accessible")
        try:
            _log("NOT_FOUND", meta={"board_id": board_id})
        except Exception:
            pass
        return e

    objs = _load("board_objects.json")
    # Pre-index for parent/group filters validity? If provided but not found, treat as empty results (filter match nothing).
    rows = []
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("board_id") != board_id:
            continue
        if o.get("status") != "active":
            continue
        ot = o.get("object_type")
        if not (isinstance(ot, str) and ot.startswith("item_")):
            continue
        if object_type is not None and ot != object_type:
            continue
        if parent_object_id is not None and o.get("parent_object_id") != parent_object_id:
            continue
        if group_id is not None and o.get("group_id") != group_id:
            continue
        rows.append(o)

    def _dt_key(v):
        s = v.get(sort_by)
        if not isinstance(s, str):
            return datetime.datetime.min
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.min

    reverse = (sort_order == "desc")
    rows.sort(key=_dt_key, reverse=reverse)

    start = 0
    if cursor:
        # cursor format: "idx:<int>"
        if not cursor.startswith("idx:"):
            e = _err("VALIDATION_ERROR", "Invalid cursor")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id})
            except Exception:
                pass
            return e
        try:
            start = int(cursor.split(":", 1)[1])
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id})
            except Exception:
                pass
            return e
        if start < 0 or start > len(rows):
            e = _err("VALIDATION_ERROR", "Invalid cursor")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id})
            except Exception:
                pass
            return e

    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < len(rows):
        next_cursor = f"idx:{start + limit}"

    out = {
        "board_id": board_id,
        "items": page,
        "pagination": {
            "total": len(rows),
            "limit": limit,
            "cursor": cursor,
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

    try:
        _log("OK", meta={"board_id": board_id, "returned": len(page)})
    except Exception:
        pass
    return out

