    if limerr:
        try:
            _log(limerr["error"]["code"], meta={"board_id": board_id, "object_id": object_id})
        except Exception:
            pass
        return limerr

    boards = _load("boards.json")
    board = None
    for b in boards:
        if isinstance(b, dict) and b.get("id") == board_id:
            board = b
            break
    if not board or board.get("status") == "deleted":
        e = _err("NOT_FOUND", "Board not found")
        try:
            _log("NOT_FOUND", meta={"board_id": board_id, "object_id": object_id})
        except Exception:
            pass
        return e

    memberships = _load("board_memberships.json")
    # "FORBIDDEN if caller cannot edit" - without explicit principal context, derive edit capability if any active owner/editor exists.
    can_access = False
    can_edit = False
    for m in memberships:
        if not isinstance(m, dict):
            continue
        if m.get("board_id") != board_id:
            continue
        if m.get("status") not in ("invited", "active"):
            continue
        can_access = True
        if m.get("status") == "active" and m.get("role") in ("owner", "editor"):
            can_edit = True
    if not can_access:
        e = _err("NOT_FOUND", "Object not found or not accessible")
        try:
            _log("NOT_FOUND", meta={"board_id": board_id, "object_id": object_id})
        except Exception:
            pass
        return e
    if not can_edit:
        e = _err("UNAUTHORIZED", "Forbidden: insufficient permissions to edit this board")
        try:
            _log("UNAUTHORIZED", meta={"board_id": board_id, "object_id": object_id})
        except Exception:
            pass
        return e

    objs = _load("board_objects.json")
    obj = None
    obj_idx = None
    for i, o in enumerate(objs):
        if isinstance(o, dict) and o.get("id") == object_id and o.get("board_id") == board_id:
            obj = o
            obj_idx = i
            break
    if not obj:
        e = _err("NOT_FOUND", "Object not found")
        try:
            _log("NOT_FOUND", meta={"board_id": board_id, "object_id": object_id})
        except Exception:
            pass
        return e

    # Validate connector constraints
    ot = obj.get("object_type")
    is_connector = (ot == "connector")
    if (connector_from_object_id is not None or connector_to_object_id is not None) and not is_connector:
        e = _err("VALIDATION_ERROR", "connector_from_object_id/connector_to_object_id can only be set for connector objects")
        try:
            _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
        except Exception:
            pass
        return e

    # Validate geometry numbers if provided
    if geometry is not None:
        for k in ("x", "y"):
            if k in geometry:
                v = geometry.get(k)
                if not isinstance(v, (int, float)) or not math.isfinite(float(v)):
                    e = _err("VALIDATION_ERROR", f"geometry.{k} must be a finite number")
                    try:
                        _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
                    except Exception:
                        pass
                    return e

    # Validate parent container rules if changing parent_object_id
    if parent_object_id is not None:
        if parent_object_id == object_id:
            e = _err("VALIDATION_ERROR", "parent_object_id cannot be the object itself")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
            except Exception:
                pass
            return e
        parent_obj = None
        for o in objs:
            if isinstance(o, dict) and o.get("id") == parent_object_id:
                parent_obj = o
                break
        if not parent_obj or parent_obj.get("board_id") != board_id or parent_obj.get("status") != "active":
            e = _err("VALIDATION_ERROR", "parent_object_id must reference an active object on the same board")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
            except Exception:
                pass
            return e
        # Application container rule: only frames can contain items (simple enforcement).
        if parent_obj.get("object_type") not in ("item_frame",):
            e = _err("VALIDATION_ERROR", "parent_object_id must reference a container object (e.g., item_frame)")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
            except Exception:
                pass
            return e

    # Validate connector endpoints if updating
    if is_connector and (connector_from_object_id is not None or connector_to_object_id is not None):
        new_from = connector_from_object_id if connector_from_object_id is not None else obj.get("connector_from_object_id")
        new_to = connector_to_object_id if connector_to_object_id is not None else obj.get("connector_to_object_id")
        if new_from is None or new_to is None:
            e = _err("VALIDATION_ERROR", "Connectors must have both connector_from_object_id and connector_to_object_id")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
            except Exception:
                pass
            return e
        # Must exist and be on same board, active
        idset = {new_from, new_to}
        found = {}
        for o in objs:
            if not isinstance(o, dict):
                continue
            oid = o.get("id")
            if oid in idset:
                found[oid] = o
        for endpoint_id in (new_from, new_to):
            ep = found.get(endpoint_id)
            if not ep or ep.get("board_id") != board_id or ep.get("status") != "active":
                e = _err("VALIDATION_ERROR", f"Connector endpoint {endpoint_id} must reference an active object on the same board")
                try:
                    _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
                except Exception:
                    pass
                return e

    # Lifecycle transition validation
    if status is not None and status != obj.get("status"):
        cur = obj.get("status")
        allowed = {"active": ["deleted"], "deleted": []}
        if cur not in allowed or status not in allowed[cur]:
            e = _err("INVALID_TRANSITION", f"Cannot transition status from {cur} to {status}")
            try:
                _log("INVALID_TRANSITION", meta={"board_id": board_id, "object_id": object_id})
            except Exception:
                pass
            return e

    # If deleting object, remove object_links referencing it (business rule)
    links = _load("object_links.json")
    links_changed = False

    updated = dict(obj)
    if title is not None:
        updated["title"] = title
    if text_content is not None:
        updated["text_content"] = text_content
    if data is not None:
        updated["data"] = data
    if style is not None:
        updated["style"] = style
    if geometry is not None:
        updated["geometry"] = geometry
    if parent_object_id is not None:
        updated["parent_object_id"] = parent_object_id

    if is_connector:
        if connector_from_object_id is not None:
            updated["connector_from_object_id"] = connector_from_object_id
        if connector_to_object_id is not None:
            updated["connector_to_object_id"] = connector_to_object_id
    else:
        # Ensure non-connectors keep connector fields null if present in schema
        if "connector_from_object_id" in updated and updated.get("connector_from_object_id") is not None:
            updated["connector_from_object_id"] = None
        if "connector_to_object_id" in updated and updated.get("connector_to_object_id") is not None:
            updated["connector_to_object_id"] = None

    if status is not None:
        updated["status"] = status

    # Enforce connector constraint after patch
    if updated.get("object_type") == "connector":
        if not updated.get("connector_from_object_id") or not updated.get("connector_to_object_id"):
            e = _err("VALIDATION_ERROR", "Connector must have both connector_from_object_id and connector_to_object_id")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
            except Exception:
                pass
            return e
    else:
        if updated.get("connector_from_object_id") is not None or updated.get("connector_to_object_id") is not None:
            e = _err("VALIDATION_ERROR", "Non-connector objects cannot have connector endpoint fields")
            try:
                _log("VALIDATION_ERROR", meta={"board_id": board_id, "object_id": object_id})
            except Exception:
                pass
            return e

    updated["updated_at"] = now

    # Apply
    objs[obj_idx] = updated

    # If deleted now, remove links referencing deleted object
    if obj.get("status") != "deleted" and updated.get("status") == "deleted":
        new_links = []
        for l in links:
            if not isinstance(l, dict):
                continue
            if l.get("board_id") != board_id:
                new_links.append(l)
                continue
            if l.get("from_object_id") == object_id or l.get("to_object_id") == object_id:
                links_changed = True
                continue
            new_links.append(l)
        links = new_links

    # Persist
    _save("board_objects.json", objs)
    if links_changed:
        _save("object_links.json", links)

    out = {"board_id": board_id, "object": updated}
    try:
        _log("OK", meta={"board_id": board_id, "object_id": object_id})
    except Exception:
        pass
    return out

def get_caller_context(access_token=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0090000" if __import__("os").path.isdir("./environment_mix/0090000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(float(s))
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    now_iso = _now()
    status = "success"
    used_credential = None

    # ---- Load datastore collections ----
    principals = _load("principals.json")

    # Optional collections for auth/usage if present in the datastore directory.
    # (Schema excerpt did not include them, but real behavior expects dynamics when they exist.)
    try:
        db_files = set(os.listdir(_DB))
    except Exception:
        db_files = set()

    auth_tokens = _load("auth_tokens.json") if "auth_tokens.json" in db_files else []
    api_keys = _load("api_keys.json") if "api_keys.json" in db_files else []
    access_tokens = _load("access_tokens.json") if "access_tokens.json" in db_files else []
    request_logs = _load("request_logs.json") if "request_logs.json" in db_files else []
    usage_counters = _load("usage_counters.json") if "usage_counters.json" in db_files else []
    quotas = _load("quotas.json") if "quotas.json" in db_files else []
    rate_limits = _load("rate_limits.json") if "rate_limits.json" in db_files else []

    # ---- Validate inputs ----
    if access_token is not None and not isinstance(access_token, str):
        status = "error"
        # log then return
        if "request_logs.json" in db_files:
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": _gen_id("req"),
                "endpoint": "get-caller-context",
                "credential": None,
                "status": "VALIDATION_ERROR",
                "latency_ms": latency_ms,
                "timestamp": now_iso
            })
            _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "access_token must be a string when provided")

    # ---- Resolve credential (ambient or explicit) ----
    # Vendor rule: if explicit credential is provided, authenticate it by matching stored client-visible value or id.
    # If none provided, attempt to use an ambient "active" credential if the store provides such markers;
    # otherwise pick a working principal context without refusing well-formed calls.
    resolved = None  # dict describing credential
    principal = None

    def _find_principal(pid):
        if not _is_nonempty_str(pid):
            return None
        for p in principals:
            if p.get("id") == pid and p.get("status") != "deleted":
                return p
        return None

    def _token_matches(row, token_value):
        # match by id or plaintext token field (client-visible)
        if not isinstance(row, dict):
            return False
        if row.get("id") == token_value:
            return True
        for k in ("access_token", "token", "value", "key"):
            if row.get(k) == token_value:
                return True
        return False

    def _token_is_valid(row):
        if not isinstance(row, dict):
            return False
        if row.get("status") in ("revoked", "expired", "inactive", "deleted"):
            return False
        exp = row.get("expires_at") or row.get("expires")
        if exp is not None:
            dt = _parse_dt(exp)
            if dt is not None and dt <= datetime.datetime.utcnow():
                return False
        return True

    def _extract_scopes(row):
        sc = row.get("scopes")
        if isinstance(sc, list):
            return [s for s in sc if isinstance(s, str)]
        if isinstance(sc, str):
            # comma/space separated
            parts = [p.strip() for p in sc.replace(",", " ").split()]
            return [p for p in parts if p]
        return []

    # explicit access_token path
    if _is_nonempty_str(access_token):
        candidates = []
        for src, coll in (("auth_tokens", auth_tokens), ("access_tokens", access_tokens), ("api_keys", api_keys)):
            for r in coll:
                if _token_matches(r, access_token):
                    candidates.append((src, r))
        # choose a valid one tied to a principal if possible
        for src, r in candidates:
            if not _token_is_valid(r):
                continue
            pid = r.get("principal_id") or r.get("user_id") or r.get("subject_principal_id")
            p = _find_principal(pid)
            if p is None:
                # allow service-level credentials if no principal exists, but only if explicitly marked
                if r.get("service") is True or r.get("principal_id") is None:
                    resolved = {"type": src, "id": r.get("id"), "value": access_token}
                    principal = None
                    break
                continue
            resolved = {"type": src, "id": r.get("id"), "value": access_token}
            principal = p
            break
        if resolved is None:
            status = "UNAUTHORIZED"
            if "request_logs.json" in db_files:
                latency_ms = int((time.time() - t0) * 1000)
                request_logs.append({
                    "id": _gen_id("req"),
                    "endpoint": "get-caller-context",
                    "credential": access_token,
                    "status": "UNAUTHORIZED",
                    "latency_ms": latency_ms,
                    "timestamp": now_iso
                })
                _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Invalid or expired access token")
        used_credential = access_token
        scopes = []
        # retrieve scopes from matching record
        for src, r in (("auth_tokens", auth_tokens), ("access_tokens", access_tokens), ("api_keys", api_keys)):
            for row in r:
                pass  # kept for structure

        # locate actual row used
        used_row = None
        for src, coll in (("auth_tokens", auth_tokens), ("access_tokens", access_tokens), ("api_keys", api_keys)):
            for r in coll:
                if r.get("id") == resolved.get("id"):
                    used_row = r
                    break
            if used_row is not None:
                break
        scopes = _extract_scopes(used_row) if used_row else []
    else:
        # ambient auth: attempt to find any valid active token marked as current; else select any active user principal
        scopes = []
        # look for a token with is_current/active marker
        for src, coll in (("auth_tokens", auth_tokens), ("access_tokens", access_tokens), ("api_keys", api_keys)):
            best = None
            for r in coll:
                if not _token_is_valid(r):
                    continue
                if r.get("is_current") is True or r.get("current") is True or r.get("active") is True:
                    best = (src, r)
                    break
            if best:
                src, r = best
                pid = r.get("principal_id") or r.get("user_id") or r.get("subject_principal_id")
                p = _find_principal(pid)
                resolved = {"type": src, "id": r.get("id"), "value": r.get("access_token") or r.get("token") or r.get("value") or r.get("key") or r.get("id")}
                principal = p
                scopes = _extract_scopes(r)
                used_credential = resolved["value"]
                break

        # If no credential collections exist or no active token found, do not refuse a well-formed call:
        # pick an active user principal as the caller (best-effort).
        if resolved is None:
            for p in principals:
                if p.get("principal_type") == "user" and p.get("status") == "active":
                    principal = p
                    break
            if principal is None:
                # last resort: any active principal
                for p in principals:
                    if p.get("status") == "active":
                        principal = p
                        break
            if principal is None:
                status = "UNAUTHORIZED"
                if "request_logs.json" in db_files:
                    latency_ms = int((time.time() - t0) * 1000)
                    request_logs.append({
                        "id": _gen_id("req"),
                        "endpoint": "get-caller-context",
                        "credential": None,
                        "status": "UNAUTHORIZED",
                        "latency_ms": latency_ms,
                        "timestamp": now_iso
                    })
                    _save("request_logs.json", request_logs)
                return _err("UNAUTHORIZED", "No authenticated context available")
            resolved = {"type": "ambient", "id": None, "value": None}
            used_credential = None

    # ---- Enforce rate limit / quota if configured ----
    # Generic enforcement based on optional config collections.
    # rate_limits rows: {scope:'global'|'credential', limit:int, window_seconds:int}
    # quotas rows: {scope:'credential'|'principal', limit:int, period:'day'|'month'}
    def _enforce_limits():
        nonlocal status, request_logs
        now = datetime.datetime.utcnow()

        # rate limit
        if "rate_limits.json" in db_files and isinstance(rate_limits, list) and rate_limits:
            # pick tightest applicable rule
            applicable = []
            for rl in rate_limits:
                if not isinstance(rl, dict):
                    continue
                scope = rl.get("scope", "global")
                lim = rl.get("limit")
                win = rl.get("window_seconds")
                if not isinstance(lim, int) or lim <= 0:
                    continue
                if not isinstance(win, int) or win <= 0:
                    continue
                if scope == "global":
                    applicable.append(("global", rl))
                elif scope == "credential" and used_credential is not None:
                    applicable.append(("credential", rl))
            # enforce all applicable (fail if any exceeded)
            for scope, rl in applicable:
                lim = rl["limit"]
                win = rl["window_seconds"]
                cutoff = now - datetime.timedelta(seconds=win)
                count = 0
                if "request_logs.json" in db_files:
                    for ev in request_logs:
                        if not isinstance(ev, dict):
                            continue
                        ts = _parse_dt(ev.get("timestamp"))
                        if ts is None or ts < cutoff:
                            continue
                        if scope == "global":
                            count += 1
                        else:
                            if ev.get("credential") == used_credential:
                                count += 1
                if count >= lim:
                    status = "RATE_LIMIT"
                    return _err("RATE_LIMIT", "Rate limit exceeded", limit=lim, window_seconds=win, used=count)

        # quota
        if "quotas.json" in db_files and isinstance(quotas, list) and quotas:
            # pick applicable quotas
            pid = principal.get("id") if isinstance(principal, dict) else None
            for q in quotas:
                if not isinstance(q, dict):
                    continue
                scope = q.get("scope")
                lim = q.get("limit")
                period = q.get("period")
                if not isinstance(lim, int) or lim <= 0:
                    continue
                if period not in ("day", "month"):
                    continue
                if scope == "credential" and used_credential is None:
                    continue
                if scope == "principal" and not _is_nonempty_str(pid):
                    continue

                if period == "day":
                    start = datetime.datetime(now.year, now.month, now.day)
                else:
                    start = datetime.datetime(now.year, now.month, 1)

                used = 0
                if "request_logs.json" in db_files:
                    for ev in request_logs:
                        if not isinstance(ev, dict):
                            continue
                        ts = _parse_dt(ev.get("timestamp"))
                        if ts is None or ts < start:
                            continue
                        if scope == "credential":
                            if ev.get("credential") == used_credential:
                                used += 1
                        else:
                            # principal scope: requires request log to include principal_id; if absent, best-effort not enforce
                            if ev.get("principal_id") == pid:
                                used += 1

                if used >= lim:
                    status = "QUOTA_EXCEEDED"
                    return _err("QUOTA_EXCEEDED", "Quota exceeded", limit=lim, period=period, used=used)

        return None

    limit_err = _enforce_limits()
    if limit_err is not None:
        if "request_logs.json" in db_files:
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": _gen_id("req"),
                "endpoint": "get-caller-context",
                "credential": used_credential,
                "principal_id": principal.get("id") if isinstance(principal, dict) else None,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": now_iso
            })
            _save("request_logs.json", request_logs)
        return limit_err

    # ---- Build consumption snapshot (best-effort) ----
    # Use request_logs if present; otherwise infer 0 usage.
    consumption = {"rate_limit": None, "quota": None}
    if "request_logs.json" in db_files:
        now = datetime.datetime.utcnow()
        # simple computed windows: last 60s for rate, today for quota
        last60 = now - datetime.timedelta(seconds=60)
        today = datetime.datetime(now.year, now.month, now.day)
        cred_used_60 = 0
        cred_used_today = 0
        for ev in request_logs:
            if not isinstance(ev, dict):
                continue
            if used_credential is not None and ev.get("credential") != used_credential:
                continue
            ts = _parse_dt(ev.get("timestamp"))
            if ts is None:
                continue
            if ts >= last60:
                cred_used_60 += 1
            if ts >= today:
                cred_used_today += 1
        consumption["rate_limit"] = {"window_seconds": 60, "used": cred_used_60}
        consumption["quota"] = {"period": "day", "used": cred_used_today}

        # overlay configured limits if present
        if "rate_limits.json" in db_files and isinstance(rate_limits, list) and rate_limits:
            # choose a relevant configured rule
            chosen = None
            for rl in rate_limits:
                if not isinstance(rl, dict):
                    continue
                if rl.get("scope") == "credential" and used_credential is not None:
                    chosen = rl
                    break
            if chosen is None:
                for rl in rate_limits:
                    if isinstance(rl, dict) and rl.get("scope", "global") == "global":
                        chosen = rl
                        break
            if chosen and isinstance(consumption["rate_limit"], dict):
                if isinstance(chosen.get("limit"), int):
                    consumption["rate_limit"]["limit"] = chosen["limit"]
                if isinstance(chosen.get("window_seconds"), int):
                    consumption["rate_limit"]["window_seconds"] = chosen["window_seconds"]

        if "quotas.json" in db_files and isinstance(quotas, list) and quotas:
            chosen = None
            for q in quotas:
                if not isinstance(q, dict):
                    continue
                if q.get("scope") == "credential" and used_credential is not None:
                    chosen = q
                    break
            if chosen is None:
                for q in quotas:
                    if isinstance(q, dict) and q.get("scope") == "principal":
                        chosen = q
                        break
            if chosen and isinstance(consumption["quota"], dict):
                if isinstance(chosen.get("limit"), int):
                    consumption["quota"]["limit"] = chosen["limit"]
                if chosen.get("period") in ("day", "month"):
                    consumption["quota"]["period"] = chosen["period"]

    # ---- Prepare response ----
    caller = None
    if isinstance(principal, dict):
        caller = {
            "principal_id": principal.get("id"),
            "principal_type": principal.get("principal_type"),
            "display_name": principal.get("display_name"),
            "email": principal.get("email"),
            "status": principal.get("status"),
            "external_miro_id": principal.get("external_miro_id"),
            "parent_principal_id": principal.get("parent_principal_id")
        }
    else:
        caller = {
            "principal_id": None,
            "principal_type": None,
            "display_name": None,
            "email": None,
            "status": None,
            "external_miro_id": None,
            "parent_principal_id": None
        }

    resp = {
        "caller": caller,
        "credential": {
            "type": resolved.get("type") if isinstance(resolved, dict) else None,
            "id": resolved.get("id") if isinstance(resolved, dict) else None
        },
        "scopes": scopes if isinstance(scopes, list) else [],
        "consumption": consumption,
        "server_time": now_iso
    }

    # ---- Record request log & counters ----
    if "request_logs.json" in db_files:
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": _gen_id("req"),
            "endpoint": "get-caller-context",
            "credential": used_credential,
            "principal_id": principal.get("id") if isinstance(principal, dict) else None,
            "status": "OK",
            "latency_ms": latency_ms,
            "timestamp": now_iso
        })
        _save("request_logs.json", request_logs)

    if "usage_counters.json" in db_files:
        # increment a simple counter by endpoint and optionally credential
        updated = False
        for row in usage_counters:
            if not isinstance(row, dict):
                continue
            if row.get("metric") == "calls" and row.get("endpoint") == "get-caller-context" and row.get("credential") == used_credential:
                row["count"] = int(row.get("count") or 0) + 1
                row["updated_at"] = now_iso
                updated = True
                break
        if not updated:
            usage_counters.append({
                "id": _gen_id("uc"),
                "metric": "calls",
                "endpoint": "get-caller-context",
                "credential": used_credential,
                "count": 1,
                "created_at": now_iso,
                "updated_at": now_iso
            })
        _save("usage_counters.json", usage_counters)

    return resp
